/* Persona 3: Equinox · Act III story events, 7/28 to 9/24 early (format: assets/femc/game/scene.js; events: core.js dueEvent).
   Loads after story-act2.js. Sixteen dated events. The two full moons are operations, as in Acts I and II: each has a
   { battle: { kind: 'operation' } } line whose op is listed in calendar.js `ops`, and the battle side plays it from
   battle.js SCRIPTS ('eqx-table-op' 8/25, 'eqx-equinox' 9/23). Both are town operations: neither opens a block of the Well.
   The summer trip is one event (8/9 early) whose scene breaks carry the date on to 8/12 (scene.js `date`); nothing else is
   dated 8/10-8/11. The act closes on 9/24 early; Act IV starts after it.
   Who's dating whom: a few scenes read the year's romance standing with `dating(id, then, else)` below (the link's route,
   or a kiss flag from its ranks or Act II), and `nobody(lines)` for none of them. Data only: the helpers just build
   ifRomance / ifCount lines.
   Speakers: the parents use their couple links' member ids (config.js `faces`); people without portraits speak in narration.
   Bookkeeping (data/flags.js): counters `cakes`, `choose`, `asked`; choices `asks.solar.ferry`, `asks.solar.moon`; flags
   listed in flags.js `hooks` / `cosmetic`. This file reads the romance flags above, eqx-from-strangers-family and a few of
   its own flags; nothing else reads the new ones yet.
   Art still to make: `// CG: eqx-*` and `// BG: *` comments mark it; stand-in backgrounds are used until then. */
{
  // Kiss flags (and Haechan's stayed night) set in the romance links' ranks 2-3 and in Act II (links/*.js, story-act2.js).
  const KISS = {
    haechan: ['eqx-hc-roof-kiss', 'eqx-hc-stayed-night'],
    jungwon: ['eqx-jw-council-kiss', 'eqx-jw-summer-kiss', 'eqx-jw-room-four', 'eqx-jw-both-names', 'eqx-jw-last-train', 'eqx-jw-chosen'],
    jihoon: ['eqx-jihoon-roof', 'eqx-jihoon-booth-kiss', 'eqx-jihoon-canal-kiss', 'eqx-jihoon-dark-kiss', 'eqx-jihoon-room'],
    akihiko: ['eqx-aki-lamp-kiss', 'eqx-aki-gate-kiss', 'eqx-aki-shallows-kiss', 'eqx-aki-room-kiss', 'eqx-aki-woke'],
    minji: ['eqx-minji-kiss'],
    shinjiro: ['eqx-shinji-sink-kiss', 'eqx-shinji-awning-kiss', 'eqx-shinji-stayed-night', 'eqx-shinji-seed-kiss']
  };
  // Lines that play when Solar is on `id`'s romance route, or has kissed him / her this year.
  const dating = (id, then, els) => ({ ifRomance: id, then, else: KISS[id].length ? [{ ifCount: { of: KISS[id], min: 1 }, then, else: els || [] }] : (els || []) });
  // Lines that play only when she's on no romance route and has kissed nobody.
  const ALL_KISS = Object.values(KISS).flat();
  const nobody = lines => Object.keys(KISS).reduceRight((inner, id) => [{ ifRomance: id, then: [], else: inner }],
    [{ ifCount: { of: ALL_KISS, max: 0 }, then: lines }])[0];

(window.FEMC_GAME_EVENTS ||= []).push(

  { id: 'eqx-rehearsal', date: '7/28', slot: 'after', consumes: true, title: 'twos', place: 'The Oka Boarding House · Tatami Room', time: 'Daytime',
    cast: { solar: 'Solar', hanni: 'Hanni', yunjin: 'Yunjin', chaewon: 'Chaewon', sakura: 'Sakura', kazuha: 'Kazuha', eunchae: 'Eunchae', mrsoka: 'Mrs. Oka', akihiko: 'Akihiko' },
    scene: [
    { place: 'Iwatodai Dorm · Lounge', time: 'Morning', bg: 'iwatodaidorm-livingroom', music: 'tension' },
    { n: "Nobody had wiped the whiteboard. Somebody had tried to, Solar thought, sometime in the night; there was a gray smear across the bottom corner where a palm had gone over it once and stopped. But the word was still there in Mitsuru's red marker under the two long columns of names, and the four names boxed under it, and in the morning light coming through the lounge windows it looked less like a word and more like a stain on the wall that had been there before any of them." },
    { n: "*HUNTING*" },
    { n: "Summer break had started a week ago. It was supposed to feel like summer break. The cicadas had started up at five in the trees along the street, all of them at once, a wall of sound that made the heat feel louder, and Ken had come down at six in a T-shirt and shorts with a towel round his neck because he and Koromaru had been going to walk to the beach, and then he'd seen the whiteboard, and remembered, and gone back upstairs, and come down again with the towel folded and asked Shinjiro, very politely, if there was toast." },
    { n: "Hanni had redone the rota in the night. It was taped to the corkboard by the front door over the old one, and every box had two names in it now, and some of them had three, and in the corner, small, in pencil, she'd written *nobody alone, nobody alone, nobody alone* down the margin like lines she'd been made to write at school." },
    { s: 'hanni', f: 'neutral', t: "You're with me today. We're doing the boarding house. Somebody has to go and look at them every day. I'm not leaving four girls in that house without somebody looking." },
    { s: 'solar', f: 'neutral', t: "Mitsuru asked you to?" },
    { s: 'hanni', f: 'serious', t: "Mitsuru asked me to do the rota. I put us on the boarding house. Get your shoes." },
    { n: "Her phone buzzed against the counter on the way out. Akihiko, from the pier, where he went every morning now whether there was anything to run from or not." },
    { phone: [
      { from: 'akihiko', t: "64:07." },
      { from: 'akihiko', t: "I said over 64. It's over 64." },
      { from: 'akihiko', t: "I don't want to be right about this anymore." }
    ], contact: 'akihiko' },
    { place: 'The Oka Boarding House · Gate', time: 'Daytime', bg: 'eqx-oka-gate', music: 'mystery' },
    { n: "The river street at ten in the morning in late July was the stillest street in Iwatodai. The heat came up off the stones of it in a shimmer that made the far end swim, and the river beyond the garden walls was low and brown and slow, and the persimmon tree over the boarding house wall had put out its fruit since June, small and green and hard, a hundred little fists." },
    { n: "Mrs. Oka was at the gate. Of course she was. In a gray cotton summer kimono with the sleeves tied back and her white cotton gloves on, and a tray with two glasses of barley tea on it, already poured, the ice in them not yet melted, as if she'd poured them at the exact moment they'd turned the corner of the street." },
    { s: 'mrsoka', f: 'sad', t: "Oh. Oh, there you are. The two of you. Come in out of the sun, children, you'll fall down. I haven't slept. I keep getting up in the night and going down to the front room and standing in the door. As if he'd still be there. As if he'd want one more." },
    { n: "Her eyes were red at the rims. Her face was gray and soft and old. She put a glass of barley tea into Hanni's hand, and one into Solar's, and closed their fingers round them with hers, the gloves warm and a little damp, and Solar felt, through the cotton, through the cold glass, the four small hard points of the fingertips press, once, the way you'd test whether bread was done." },
    { n: "Hanni didn't drink hers. Solar watched her not drink it, and then not drink her own." },
    { s: 'mrsoka', f: 'neutral', t: "They're upstairs. In the big room. They've been at it since seven, bless them, I don't think they know how to stop. Go on up. It does me good to hear it. It's the only thing in this house that sounds alive." },
    { place: 'The Oka Boarding House · Tatami Room', time: 'Daytime', bg: 'eqx-oka-kitchen', music: 'joy' },
    // BG: oka-tatami-room — a long, bare twelve-mat tatami room on the upper floor of an old Japanese house, the paper screens slid wide open onto a summer garden with a persimmon tree and a stone-capped well below, a phone propped in the alcove for music, bright hot daylight.
    { n: "The big room took up the whole of the back of the upper floor, twelve mats, and they'd slid every screen in it open to the garden so the air could move, and it didn't, and the five of them were dancing anyway." },
    { n: "Five. Yunjin was with them. Solar hadn't known. She was at the end of the line in a pair of borrowed shorts and one of Haechan's T-shirts with the sleeves cut off, her hair scraped up, sweat running down the back of her neck, and she was counting with the others under her breath, in Korean, while Chaewon at the front counted out loud in English for all of them, over a song coming tinny and small out of a phone propped up in the alcove where a scroll should have been." },
    { s: 'chaewon', f: 'serious', t: "Five, six, seven, eight— Sakura, you're early. You're early on the turn every time. Kazuha, beautiful. Eunchae, you're watching your feet. Don't watch your feet. Your feet know." },
    { s: 'eunchae', f: 'flustered', t: "My feet don't know! My feet have never known! My feet are from a completely different life!" },
    { s: 'sakura', f: 'neutral', t: "Three different lives. Pick one of them to have feet in." },
    { n: "They didn't miss a count. That was the thing Solar couldn't get used to. They'd been here a month and they'd never once been in a room together in any of their lives before the night they came through, and they moved like they'd been doing this since they were children. Every head turning at once. Every arm. Five bodies, one shape, the floor going *hush, hush* under their bare feet on the beat." },
    { n: "Hanni sat down in the doorway with her back against the frame and her knees up, where she could see the room and the stairs at the same time. She did it without thinking about it. She did everything that way now." },
    { s: 'kazuha', f: 'happy', t: "Solar-ssi. Solar-senpai. You came to watch? Sit, sit, there is a cushion. It is the only one that is not damp." },
    { n: "On the veranda outside the open screens, at the very edge of the boards, where the garden started, there was a small white saucer. Kazuha put rice in it every night; Solar knew that. She'd seen her do it, a little mound of plain white rice, *for whoever is following, in Japan we leave a little*. This morning the saucer was empty, and it was upside down, set neatly face down on the wood the way the cups were set on the trays upstairs in the eight made-up rooms, and around it, on the boards, there was a fine pale ring, like dust, like a circle somebody had drawn with their finger in flour." },
    { n: "Kazuha saw her looking at it. Kazuha didn't look at it." },
    { s: 'kazuha', f: 'neutral', t: "It is like that every morning now. Since the twenty-seventh. I wash it and I put the rice. In the morning it is like that." },
    { s: 'kazuha', f: 'neutral', t: "My grandmother would say, it means it was accepted. She would say it was polite." },
    { n: "The song started again from the top. Yunjin, at the end of the line, looked over at the doorway, at Solar, and jerked her head at the empty space beside her on the mats. Her left side. The space she'd stood in front of Solar in the atrium in June and told her she was on the wrong side of." },
    { s: 'yunjin', f: 'neutral', t: "Come on, Sol. The bridge part. You know it." },
    { s: 'solar', f: 'neutral', t: "I don't know it. I've never learned it. You made it up." },
    { s: 'yunjin', f: 'neutral', t: "Yeah. And you know it." },
    { choose: [
      { t: "(Take the space on her left.)", flag: 'eqx-danced-left', then: [
        { n: "She got up. She went and stood on Yunjin's left in her socks, in her shorts, with her barley tea still in her hand until Eunchae took it off her, and Chaewon said *five, six, seven, eight*, and Solar's body did it." },
        { n: "She didn't decide anything. Her arms went up when theirs did. Her weight went over onto her left foot on the turn a quarter of a count before Sakura's, on time. Her chin came up on the last beat with all of theirs. It was the strangest feeling she'd had in this town, stranger than the red, stranger than the well: like hearing your own voice on a recording, and it being better than you." },
        { n: "When it ended the six of them stood in a line breathing hard, chins up, one arm out toward the garden, and held it, and nobody said anything, and from the doorway Hanni was looking at Solar with an expression Solar had seen on her face once before, in December, in a different life, at a party, when somebody had held up a phone." },
        { s: 'eunchae', f: 'surprised', t: "...You've done that before. You have. You've done that exact thing before." },
        { s: 'solar', f: 'neutral', t: "I haven't." },
        { s: 'yunjin', f: 'neutral', t: "Not yet." },
        { n: "She said it like it was nothing. Like a weather report. And then she looked, for a second, completely lost, as if the words had come out of somebody standing slightly behind her." }
      ] },
      { t: "(Stay in the doorway with Hanni.)", then: [
        { n: "She sat down next to Hanni instead, her shoulder against Hanni's shoulder, her back against the other side of the frame. Yunjin looked at her for a long moment and then shrugged and turned back to the room, and the space on her left stayed empty all the way through the song, and Solar watched it the whole time, the empty space where her body knew to be, the way you watch a gap in a fence." },
        { s: 'hanni', f: 'neutral', t: "...You wanted to." },
        { s: 'solar', f: 'neutral', t: "I didn't." },
        { s: 'hanni', f: 'neutral', t: "Your foot was going. The whole time. Your left one." }
      ] }
    ] },
    { n: "Mrs. Oka came up the stairs at noon with a tray of cold noodles and stood in the doorway beside Hanni, not over the threshold, never over the threshold, and watched them run it one more time, and when it ended she put the tray down on the floor just inside the door, and folded her gloved hands, and her eyes were wet again." },
    { s: 'mrsoka', f: 'happy', t: "Five of you. Isn't that lovely. Five girls who'd never have found each other anywhere else in the world. My, my." },
    { s: 'mrsoka', f: 'neutral', t: "You'll stay together, won't you, girls. All of you. Promise me. Nobody on her own, not this summer. That's what your Mitsuru says, isn't it, and she's quite right. Twos. Better still, all of you. Stay together." },
    { n: "She said it so gently. She said it in exactly the words that were on the corkboard in the dorm in Hanni's handwriting, *nobody alone*, the rule that was keeping them alive; and the four girls, flushed and out of breath and sitting down on the mats round the noodles, said *we will* all at once, in three languages, like a chorus, like a cheer at the end of a set, without thinking about it at all." },
    { n: "Yunjin didn't say it. Yunjin was looking out of the open screens, down into the garden, at the well under the persimmon tree with its heavy stone cap, and Solar couldn't see her face." },
    { n: "Hanni, in the doorway, had gone completely still." },
    { place: 'Iwatodai · River Street', time: 'Daytime', bg: 'outside-daytime-neighborhood', music: 'badfeeling', soft: true },
    { n: "They walked back in the worst of the heat, the cicadas screaming, the river street empty, the shimmer coming up off the stones. Hanni didn't say anything until the corner by the post office, where Koromaru always stopped and set his legs and wouldn't go on." },
    { s: 'hanni', f: 'serious', t: "She used it. Did you hear her? She used Mitsuru's rule. Nobody alone. She said it like it was hers." },
    { s: 'solar', f: 'neutral', t: "It's a good rule." },
    { s: 'hanni', f: 'serious', t: "I know it's a good rule. I wrote it out forty times last night. I know it's a good rule." },
    { n: "She stopped at the corner. She looked back down the street, at the wall, at the persimmon tree over it, at the upstairs window of the big room with the screens open, where the song had started again, faint, carrying in the heat." },
    { s: 'hanni', f: 'sad', t: "...It just sounded different. When she said it. It sounded like a door." }
  ] },

  { id: 'eqx-wake', date: '7/31', slot: 'evening', consumes: true, title: 'one more bowl', place: 'Iwatodai · Funeral Hall', time: 'Evening',
    cast: { solar: 'Solar', junpei: 'Junpei', ken: 'Ken', aigis: 'Aigis', mitsuru: 'Mitsuru', yukari: 'Yukari', shinjiro: 'Shinjiro', fuuka: 'Fuuka' },
    scene: [
    { bg: 'naganaki-shrine-night', music: 'tender' },
    // BG: eqx-funeral-hall — a small plain funeral hall in a Japanese residential street at dusk, white and black striped curtains over the entrance, paper lanterns, a row of wreaths on stands, mourners in black waiting on the step in the heat.
    { n: "The wake was at a small funeral hall two stops down the line, in a street of shuttered shops, and the black and white curtains hung over its door didn't move at all in the heat, and the wreaths on their stands out front had started to wilt by six." },
    { n: "Junpei had a black suit. Solar hadn't known that. It was a little short at the wrists and a little tight across the back, the suit of somebody who'd bought it two years ago for something he didn't talk about, and he'd ironed the shirt himself, badly, and he stood on the step of the hall with his hands in his pockets and then took them out of his pockets because you weren't supposed to, and then didn't know where to put them." },
    { s: 'junpei', f: 'sad', t: "He wasn't even my friend. Like. Not really. He sat behind me in first year and ate chips in class. That's it. That's the whole thing. He gave me a chip once." },
    { s: 'junpei', f: 'sad', t: "...It was a good chip." },
    { n: "There were more people than Solar had expected. Classmates, a lot of them, in their uniforms because they didn't own anything black, standing in clumps on the pavement not knowing what to do with their faces. A teacher. A man from the shop on the corner where Nozomi had bought his miracle water, last year, crying openly and not seeming to know why. And inside, in the dim cool of the hall, at the front, the photograph." },
    { n: "It was a school photograph, the kind they take every April against a blue sheet, and he'd been caught with his cheeks full. Of course he had. He was looking at the camera with his eyes very slightly too wide, the way you look when somebody's said *smile* before you've swallowed, and it was so exactly him that the first three people up to the altar laughed out loud and then cried." },
    { n: "His mother was small. That was the thing Solar remembered afterward. A small, neat, gray woman in a black kimono, bowing to every single person who came in, over and over, with a face that had been put away somewhere for the evening and would have to be taken out again later." },
    { n: "On the table by the guest book, in a long row, there were white boxes tied with string. A dozen of them. A paper on top of the first one in a careful hand: *For the mourners. With love. — Oka.*" },
    { n: "Rice cakes. Solar knew before anyone opened one. She could smell them from the door, under the incense, sweet in the wrong place, at the back." },
    { n: "His mother saw her looking. She came over, bowing, and touched the top box with two fingers, the way you'd touch something precious." },
    { n: "*She's been so kind. The lady from the boarding house. She couldn't come; she said she couldn't bear it; she sent these. He was there every night, you know. All summer. He was so happy. He'd come home and tell me what she'd made. He'd never been so happy in his life. She fed him.*" },
    { n: "Her voice broke on the last word, and she bowed, and went back to the door, to bow at the next person." },
    { n: "A girl from 3-F had already untied the string on the first box. She was holding one, halfway to her mouth, crying, with the paper still round it." },
    { choose: [
      { t: "(Take the rice cake out of her hand.)", flag: 'eqx-wake-box', then: [
        { n: "Solar took it out of her hand. Not gently. The girl looked at her, wet-faced, startled, *what?*, and Solar didn't have anything to say that she could say, so she said *sorry, I— sorry*, and put it back in the box and put the lid on, and tied the string again with her fingers shaking so that it took three tries." },
        { n: "Then she picked up the whole row of boxes, all twelve, in a stack against her chest that came up to her chin, and walked out of the side door with them into the alley, and stood there in the heat with them, and didn't know what to do next." },
        { n: "Shinjiro found her there. He didn't ask. He took the stack out of her arms, all of it, the way he'd taken the pot off the stove in May, and walked to the bins at the end of the alley, and put them in, one at a time, very neatly, and put the lid on, and stood with his hand flat on the lid for a second, and wiped his hand on his coat." },
        { s: 'shinjiro', f: 'neutral', t: "...Nobody saw. Go back in." }
      ] },
      { t: "(Let it be. It's a wake.)", then: [
        { n: "She let it be. It was a wake. The girl ate it, crying, and somebody else untied the second box, and by the time the priest came in the boxes were empty, all of them, and people were wiping their fingers on their handkerchiefs and saying how good they'd been, how *good*, how strange that something could taste that good on a night like this." },
        { n: "Solar stood at the back with her hands closed at her sides until her nails hurt, and smelled the sugar in the room over the incense, and didn't eat one, and didn't say anything, and that was its own sentence." }
      ] }
    ] },
    { n: "Ken went up to the altar on his own. He'd asked to; Mitsuru had looked at him for a long time and said *yes*, and he'd gone up in his school uniform, the summer one, with his back very straight, and lit his stick of incense, and put his hands together, and stood there much longer than anyone else had, with his eyes shut." },
    { n: "Nobody in the hall knew he was the one who'd found him. His mother didn't know. The Group had seen to that." },
    { n: "When he came back his face was perfectly calm and he sat down next to Solar on the bench at the back and took her hand without looking at her and held it very hard, and that was all." },
    { place: 'Iwatodai · Funeral Hall · Outside', time: 'Night', bg: 'outside-night', music: 'night', soft: true },
    { n: "Outside, after, under the lantern by the hall door, Mitsuru was standing with her arms folded, looking at nothing, and Aigis came and stood in front of her in her black dress, which Yukari had bought her that afternoon in a hurry, the tag still on the back of the collar where nobody had had the heart to cut it." },
    { s: 'aigis', f: 'neutral', t: "Mitsuru-san. In April you told me there would be no readings of civilians in their own homes without cause." },
    { s: 'mitsuru', f: 'neutral', t: "I did." },
    { s: 'aigis', f: 'neutral', t: "You told me you would make an exception when my cause sounded like a reason." },
    { s: 'aigis', f: 'serious', t: "I was interrupted on the twenty-seventh. I was holding a cup of tea. I would like to finish my sentence." },
    { n: "Mitsuru didn't answer for a long time. She looked at the hall door, at the curtain, at the small gray woman bowing inside it in the lantern light, and her jaw moved once, the way it moved when she was reading something she'd have to sign." },
    { s: 'mitsuru', f: 'serious', t: "...It sounds like a reason. Take it. Any reading you like, of anyone you like, wherever you like. You don't need to ask me again." },
    { s: 'mitsuru', f: 'neutral', t: "Bring it to me first. Before anyone. Whatever it is." },
    { flag: 'eqx-aigis-exception' },
    { s: 'aigis', f: 'neutral', t: "Thank you. I would like to say that I will be careful. I am going to be very careful." },
    { n: "Yukari came out last, with Fuuka, with her heels in her hand because they'd blistered. She stood on the step beside Solar and looked down the shuttered street, and the heat sat on all of them like a hand." },
    { s: 'yukari', f: 'sad', t: "...His mom thanked me for coming. She said he talked about the dorm. She said he said we were all so nice to him." },
    { s: 'yukari', f: 'sad', t: "I don't think I said ten words to him all summer. I said *hey* at the shoe lockers. That's what he told his mom about. *Hey.*" },
    { s: 'fuuka', f: 'sad', t: "...I can still hear him. When I listen to the town. Not him. Where he was. There's a place at the end of the long table where it's quiet now. Like the bridge." },
    { n: "Junpei came out of the hall door behind them with his tie off and stuffed in his pocket, and stood on the step, and looked up at the sky, which was white with heat and had no stars in it, and said, to nobody, very quietly, in the voice of somebody making a joke at the very end of a very long day:" },
    { s: 'junpei', f: 'sad', t: "...Dude. You could've said no. Just once. You could've just said *I'm full*." },
    { n: "Nobody laughed. He hadn't meant anybody to. He went down the steps into the street and started walking toward the station on his own, and then remembered, and stopped, and waited under the next streetlight, with his back to them, for somebody to come and be his two." }
  ] },

  { id: 'eqx-owed', date: '8/6', slot: 'late', consumes: true, title: 'the ask he carried', place: 'Iwatodai Dorm · Front Gate', time: 'Late Night',
    cast: { solar: 'Solar', jaehyun: 'Jaehyun', minji: 'Minji' },
    scene: [
    { bg: 'iwatodaidorm-front-night', music: 'night' },
    { n: "Three knocks. Then her name, through the door, low. Then his own. Then nothing, which was the part of the procedure that was the point, and she went to her window, as she'd gone to her window every time he'd done it since April, and looked down, and he was standing at the gate under the light where she could see him, with his hands where she could see them, and he lifted the left one and waved, Hanni's addition, the way you'd wave at a ship." },
    { n: "It was twenty to twelve. She went down." },
    { n: "Minji was at the corner, under the next streetlight down, sitting on a low wall with her camera in her lap, not filming. She lifted a hand when Solar came out. Twos. She'd walked him over. She'd walk him back. She was looking very carefully at the other end of the street." },
    { n: "Jaehyun didn't come through the gate. He stayed on the other side of it, on the pavement, with the bars between them, his hands on two of them, which was so like him that Solar almost laughed: the boy who'd built a whole procedure out of not being let in." },
    { s: 'jaehyun', f: 'neutral', t: "I owe you something. I've owed you it since June. I keep not giving it to you." },
    { s: 'solar', f: 'neutral', t: "You don't owe me anything." },
    { s: 'jaehyun', f: 'serious', t: "I do. That's the problem. Somebody gave it to me to give you. And I took it. And I nodded. I've been walking round with it for two months like a— like a letter in my pocket I said I'd post." },
    { n: "He looked at his hands on the bars. Then he said it, all at once, the way you pull a splinter." },
    { s: 'jaehyun', f: 'neutral', t: "The night it rained. In June. The long table. I carried the pot in for her and she was at the sink and she said, *Ask her to stay. She'd listen to you.* She meant you. Here. For good. She said you'd listen to me." },
    { s: 'jaehyun', f: 'neutral', t: "And I nodded. I didn't say anything. I just— nodded. Like it was a perfectly normal thing to be asked by a landlady with your hands in her dishwater." },
    { flag: 'eqx-jaehyun-told' },
    { n: "Solar knew. She'd been in the hall that night, with her hand on the door, and seen him put the dish towel down too fast, as if it had been caught doing something. She'd never asked. She didn't say so now." },
    { s: 'jaehyun', f: 'sad', t: "And then Suemitsu. At that table. She was crying and making everybody tea, and I took a cup, Solar. I took a cup off her and said thank you and drank it, because there was no way not to, and I was standing there holding it and I thought, she asked me to ask my sister to stay. And I nodded." },
    { s: 'jaehyun', f: 'neutral', t: "So I'm not going to. That's what I came to say. I'm not going to ask you. I'm giving it back. It's not mine. I don't want it in my pocket anymore." },
    { n: "His knuckles on the bars had gone white. He didn't seem to know it." },
    { s: 'jaehyun', f: 'neutral', t: "...The thing is. The worst thing is. I want to. Not because she asked. I'd have wanted to anyway. Nobody calls at seven fifteen here. I set the alarm every morning for seven sixteen and it goes off and I lie there and nobody's called, and it's the best minute of the day. I ran a forty in four-fifty-one in May and I deleted it. I've never been so— I've never once in my life been somewhere nobody was waiting to hear how I did." },
    { s: 'jaehyun', f: 'sad', t: "I want you to stay. I want *me* to stay. I want to never get on a plane again. And I can't tell anymore which part of that is mine." },
    { choose: [
      { t: "Then stay. Both of us. Please.", tally: { asked: 1, cakes: 1 }, flag: 'eqx-asked-jaehyun', then: [
        { n: "She said it through the bars. It came out warm and certain, and she watched it land on him: the shoulders coming down, the breath going out of him, the look on his face of a boy who'd been told he could put something heavy down, finally, and had been waiting to be told for twenty years." },
        { s: 'jaehyun', f: 'happy', t: "...Okay. Okay. Yeah." },
        { n: "He laughed, once, shakily, and took his hands off the bars, and wiped them on his jeans. And Solar stood on her side of the gate and felt something go out of her as she'd said it, a small warm thing from under her ribs, the way it had gone in the lounge, in front of everyone, and not come back; and she couldn't have said where it went, only that her brother looked lighter than he had in years and she felt, for no reason at all, very slightly hungry." }
      ] },
      { t: "Wanting to stay is yours. Nobody asked you to want it. Keep that part.", tally: { choose: 1 }, flag: 'eqx-choose-jaehyun', then: [
        { n: "He looked at her through the bars for a long time, his face doing the thing it did when a teacher gave back a test with a mark on it he didn't understand." },
        { s: 'jaehyun', f: 'neutral', t: "...That's it? That's all you're going to say?" },
        { s: 'solar', f: 'neutral', t: "That's all I get to say." },
        { n: "He let go of the bars. He stood there with his hands open at his sides, in the light, and then he nodded, slowly, a different nod from the one at the sink, and something in his face loosened, not all the way, the way a knot loosens before it comes undone." },
        { s: 'jaehyun', f: 'neutral', t: "...Yeah. Okay. Mine. I'll— I'll think about it. On my own. That's allowed?" },
        { s: 'solar', f: 'neutral', t: "That's the only way it's allowed." }
      ] },
      { t: "Don't give her anything. Not a nod. Not a cup back. Nothing she asks for.", then: [
        { s: 'jaehyun', f: 'surprised', t: "...Solar. She's a sixty-year-old woman who makes us dinner." },
        { s: 'solar', f: 'neutral', t: "I know." },
        { s: 'jaehyun', f: 'neutral', t: "You sound like Danielle. She won't go in. She stands on the street with a list. Of who goes in." },
        { n: "He didn't argue. That was what frightened her. He stood with his hands on the bars and thought about it, carefully, as if she'd said something he'd been waiting for someone to say, and then he nodded, once, the way their father nodded when a meeting was over, and said *okay*. And she knew he'd be at the long table on Saturday, because everyone would, because where else was there." }
      ] }
    ] },
    { n: "At twelve, the red came." },
    { dark: true },
    { n: "It came over the street the way it always did, all at once, the lamps going the color of the inside of an eyelid, the hum coming up out of the ground, and down the hill in every house the coffins rose in the beds; and Jaehyun, on the other side of the bars, didn't flinch anymore. Nobody flinched anymore. That was the thing nobody said." },
    { n: "Minji had her camera up. She was filming down the hill, toward the river, the way she filmed every night. She lowered it after a minute and looked at the little screen and then held it up so Solar could see across the gate." },
    { n: "In the window of the house across the street, a coffin on a bed. Standing on its end the way they stood. Turned, not toward the island, not toward the house's own front door, not quite toward the river anymore either, but a few degrees past it, along the bank, downstream." },
    { s: 'minji', f: 'serious', t: "They're still moving. Every night. A little. Like a compass with something under it." },
    { s: 'minji', f: 'neutral', t: "Sixty-four forty, Akihiko's going to say. I'm calling it. Watch." },
    { n: "She was right, to the second. He texted it at one. Solar was in bed with the light off by then and saw it come up on the ceiling, and lay there looking at the number until it went dark, and listened to the house breathe, and somewhere far down the hill, so faint it might have been the pipes, somebody humming." }
  ] },

  { id: 'eqx-incheon', date: '8/9', slot: 'early', consumes: true, title: 'a harbor with nothing in it', place: 'Port Island · Ferry Pier', time: 'Early Morning',
    cast: { solar: 'Solar', mitsuru: 'Mitsuru', haechan: 'Haechan', jungwon: 'Jungwon', yunjin: 'Yunjin', jay: 'Jay', niki: 'Niki', sunghoon: 'Sunghoon', shinjiro: 'Shinjiro', akihiko: 'Akihiko', junpei: 'Junpei', aigis: 'Aigis', chaewon: 'Chaewon', eunchae: 'Eunchae' },
    scene: [
    { bg: 'yakushima-ferry', music: 'trip' },
    // BG: eqx-hydrofoil — a sleek white hydrofoil ferry at a concrete pier on Port Island at dawn, the bay pink and flat, a crowd of young people with bags on the gangway, gulls on the bollards.
    { n: "Mitsuru gave two reasons at breakfast on Saturday, and Solar was learning, this year, to listen for the one she didn't give." },
    { n: "The first one was summer. *It's August. We've been in this town since April. Some of you haven't left it once. The Group has a hydrofoil and a hotel and four days nobody needs, and we're taking them.* The second was the one she didn't say, and it was in the way she'd looked at the whiteboard while she said the first: *I want to know whether it stops when we go.*" },
    { n: "Where to was the part that made the room go quiet." },
    { n: "Incheon. Not *their* Incheon. This one. The one that was on the map here, across the sea, a port city with a ferry terminal and an amusement park on a little island and a Chinatown up the hill. The Group had a hotel by the water. Mitsuru said it the way she said everything, as if it were a set of figures. Haechan put his chopsticks down. Jungwon didn't put his down; he just stopped moving them. Yunjin, at the end of the table, very slowly, went white." },
    { n: "Nobody asked her why she'd picked it. Solar thought, afterward, that Mitsuru hadn't known why either, that she'd looked at a list of places the Group had hotels and her pen had stopped there and she'd let it, and that this was exactly the kind of thing that happened in this town now, and that nobody could have said whose hand the pen had been in." },
    { n: "The hydrofoil left at seven. Thirty-one of them and a dog. The tin came down to the pier with the four girls from the boarding house, full, the cranes on the lid, *for the crossing, she said, she was up at four*; and on the gangway, without a word, Shinjiro took it out of Eunchae's hands, and walked to the rail, and opened it, and tipped it out over the water for the gulls." },
    { n: "The gulls came down screaming. A dozen of them, white, wheeling round the stern. They came down to the rice cakes floating in the green water, and hung over them with their wings going, and looked at them, and didn't take one. Not one. They went back up to the bollards and sat there in a row, and the rice cakes went down slowly into the bay, one at a time, pale, like something sinking in milk." },
    { s: 'shinjiro', f: 'neutral', t: "...Huh." },
    { n: "He put the empty tin in his bag. Nobody said anything about it the whole crossing." },
    { place: 'Incheon · Wolmido', time: 'Evening', bg: 'epi-s-wolmido-night', music: 'joy', date: '8/9' },
    { n: "It was so ordinary that it hurt." },
    { n: "That was what Solar thought, coming off the ferry in the afternoon heat into the noise of the terminal, the signs in Korean, the smell of the sea and diesel and something frying, a man shouting about taxis. It was a harbor. Cranes along the water, great orange and blue ones, and container ships, and the long bridge out to the airport lying over the sea in the haze. It was a city. It was hot, and dirty, and loud, and full of people who didn't look at them twice." },
    { n: "And it was wrong in the way a room is wrong when somebody's moved one chair." },
    { n: "Haechan stood on the terminal steps with his bag on his shoulder and looked at it for a long time. Then he said, quietly, in Korean, to nobody, *I know where the fish market is from here*, and then, in English, to her, *I know which way the wind's going to be*, and then didn't say anything else for an hour." },
    { n: "They went to Wolmido in the evening because the trio wanted to. It was an amusement park on a little island joined to the city by a road, a strip of rides and lights along the seawall, the Viking ship going up and down against the sunset, music from six different places at once, squid on sticks. It was exactly an amusement park. Niki went on the Viking four times and screamed every time in two languages. Jay won a stuffed tiger at a ring toss and gave it to Eunchae, who looked at it for a second too long before she said thank you." },
    { s: 'sunghoon', f: 'neutral', t: "It's an amusement park." },
    { s: 'jay', f: 'neutral', t: "Yeah, bro. That's what it is. It's an amusement park." },
    { s: 'sunghoon', f: 'neutral', t: "No. I mean. It's *just* an amusement park." },
    { n: "Jay didn't answer. He looked out past the seawall at the dark water, at the lights of the city on the other side, at the hill above the harbor where, in another life, there'd been other things. Then he went and got in line for the Viking again with Niki, and was very loud." },
    // CG: eqx-wheel — inside a small Ferris-wheel gondola at night above a seaside amusement strip, a boy and a girl sitting on opposite benches with their knees almost touching, the lights of a harbor city and its long bridge spread out below them through the glass.
    { n: "Jungwon found her by the Ferris wheel." },
    { s: 'jungwon', f: 'neutral', t: "...It goes round once. Eleven minutes. I timed one." },
    { s: 'solar', f: 'neutral', t: "Are you asking me?" },
    { s: 'jungwon', f: 'flustered', t: "I'm telling you how long it is. In case it's relevant. To anyone." },
    { choose: [
      { t: "(Get in the gondola with him.)", flag: 'eqx-wheel-jungwon', then: [
        { n: "They sat on opposite benches with their knees almost touching and the door shut on the noise, and the wheel went up, slowly, and the harbor came out below them all at once, the cranes and the ships and the bridge and the city climbing its hills in lights." },
        { n: "He looked at it. She watched him look at it. He was looking for something, she knew, the way she was, the way all of them had been since the terminal: a roof, a wall, a gate, a window with a light on. He went over the whole of the hill above the harbor with his eyes the way he'd go over a document, line by line." },
        { s: 'jungwon', f: 'neutral', t: "...It isn't there." },
        { s: 'solar', f: 'neutral', t: "No." },
        { s: 'jungwon', f: 'neutral', t: "In one of my lives this city is the whole world. In the other one it's somewhere I've only seen from a train. I'm sitting in a gondola above it and I'm both of those people, and it's neither of those cities." },
        { s: 'jungwon', f: 'sad', t: "Nobody's waiting for me in it. Nobody's waiting for either of me. I keep waiting to feel terrible about that." },
        { n: "At the top the wheel stopped, the way they always do at the top, to let someone off at the bottom. The gondola swung, gently. He reached across the gap between the benches and took her hand, not to hold it, just to have it, his thumb on her knuckles, and they sat at the top of the night with the city under them, both of them very still." },
        { s: 'jungwon', f: 'neutral', t: "...I don't feel terrible. That's the problem." }
      ] },
      { t: "Go with the trio. Somebody has to stop Niki.", then: [
        { n: "He nodded, as if that were a perfectly reasonable motion from the floor, and got in the gondola on his own, and went round once, eleven minutes, and she watched him the whole time from the bottom with a stick of squid going cold in her hand. At the top the wheel stopped. His gondola swung. He was looking out at the hill above the harbor, not at the lights, at the dark between them, very still, for the whole time it hung there." }
      ] }
    ] },
    { place: 'Incheon · The Hill above the Harbor', time: 'Daytime', bg: 'flashback-incheon-harbor', music: 'world-strangers', date: '8/10' },
    // BG: eqx-incheon-empty-lot — a small paved lot on a hill above a harbor city, a vending machine, a chain-link fence, a single bench, weeds through the cracks, cranes and the sea far below in summer haze; nothing else.
    { n: "Haechan took her up the hill on the second morning. Just the two of them; twos. He didn't say where. He didn't have to." },
    { n: "He walked it without a map, without looking, the way you walk to your own front door in the dark: left at the noodle shop, up the steep street with the steps cut into it, past the church, left again where the old woman sold peaches off a cart. The peaches were real. The old woman was real. She called him *student* and tried to sell him a box and he bought two and gave her too much and didn't wait for change." },
    { n: "At the top of the street, where it came out onto the crown of the hill with the whole harbor below it, where there should have been a wall, old gray stone with moss in the joins, and a gate under a little tiled roof, and nineteen steps up to a house with a koi pond and a kitchen where the last lamp was always the one by the rice cooker—" },
    { n: "There was a parking lot." },
    { n: "Small. Six spaces, two of them taken, a white van and a scooter. A vending machine humming against a chain-link fence. A bench. Weeds coming up through the cracks in the asphalt. The wind came up the hill off the sea exactly the way it always had, exactly where she knew it would, salt and diesel and mud at low tide, and it blew a plastic bag across the empty spaces and caught it on the fence." },
    { n: "Haechan stood on the white line of the first space with a peach in each hand." },
    { s: 'haechan', f: 'neutral', t: "...Huh." },
    { s: 'haechan', f: 'neutral', t: "I thought there'd be something. A different house. Somebody else's house. I'd have been okay with somebody else's house." },
    { n: "He sat down on the bench. She sat down next to him. Below them the harbor went about its morning, the cranes swinging, a ship's horn going long and low, gulls. Nobody came. Nobody would. There wasn't anything here for anybody to come to." },
    { s: 'haechan', f: 'neutral', t: "No gate. No stairs. No light. Nobody up at four. Nobody sitting on the— you know. Nobody waiting up." },
    { s: 'haechan', f: 'neutral', t: "Nobody in this whole city has ever been in danger, Sol. You can feel it. Can you feel it? It's like the air's got no corners." },
    { n: "He gave her a peach. She held it. It was warm from his hand and from the sun, and the skin of it was soft as the inside of a wrist." },
    { s: 'haechan', f: 'serious', t: "...You know what it wants me to say. Sitting here. You know exactly what the whole hill wants me to say." },
    { s: 'solar', f: 'neutral', t: "I know." },
    { s: 'haechan', f: 'neutral', t: "I'm not going to." },
    { n: "He bit into his peach instead. The juice ran down his wrist. He didn't wipe it. He sat with his elbows on his knees looking at the parking lot where the house wasn't, eating a peach, and his eyes were wet and his face wasn't doing anything at all, and she understood that this was what it looked like when Haechan wanted something so loudly that you could hear it from across a city and wasn't going to say it, and she ate her own peach, and didn't say anything either, and the bag on the fence tore loose in the wind and went over the edge of the hill toward the sea." },
    { place: 'Incheon · Chinatown', time: 'Evening', bg: 'epi-s-chinatown', music: 'city', date: '8/10', soft: true },
    { n: "Jungwon asked in Chinatown, that evening. Solar watched him do it. He went into a shop selling dried fish and ginseng, and bowed to the old man behind the counter, and asked him, very politely, in the formal Korean of somebody asking for directions to a ministry, whether he knew a family in the city by the name of Yang. A large house. An old family. Everybody would know them." },
    { n: "The old man thought about it. He was very kind about it. He asked a woman in the back, who asked her son, who came out wiping his hands and thought about it too. Yang? There were Yangs, of course, lots of Yangs, there was a Yang who ran the dry cleaner's by the station. A large house? An old family? No. No, nobody like that. Was he sure he had the right city?" },
    { n: "Jungwon thanked them. He bowed again, lower. He came out into the street with his face perfectly composed and walked half a block, and then stopped in front of a window full of mooncakes, and stood looking at his own reflection in the glass for so long that the trio, coming up the hill behind them, went quiet and stood back, and Jay put his hand on Niki's arm to keep him from saying anything." },
    { s: 'jungwon', f: 'neutral', t: "...They didn't know us. Nobody's ever not known us. In that city. Ever." },
    { s: 'jay', f: 'neutral', t: "Yeah." },
    { s: 'jungwon', f: 'neutral', t: "Nobody here's ever heard of my father." },
    { s: 'jay', f: 'neutral', t: "Yeah, bro. I know." },
    { n: "Jungwon looked at his reflection a moment longer. Then he laughed, very quietly, the way you laugh when something is too big for anything else, and bought a box of mooncakes, and gave one to each of them on the street, and ate his own standing up in the lamp light with the crumbs going down his shirt, which Solar had never once seen him allow in any life." },
    { place: 'Incheon · The Seawall', time: 'The Dark Hour', bg: 'epi-s-harbor-night', music: 'darkhour', date: '8/11' },
    { dark: true },
    { n: "The red found them there anyway." },
    { n: "Of course it did. Solar had known it would, the way you know the floor will be there in the dark; she just hadn't known how much she'd hoped it wouldn't until midnight on the third night, on the seawall below the hotel, when the harbor lights went the color of the inside of a cut and the hum came up out of the sea and every window in the city behind them filled, one by one, with the dark upright shapes of coffins." },
    { n: "Akihiko had his stopwatch out. He'd had it out for an hour, waiting. He looked at it at one, when the color drained back out of the world, and read it out in a voice with nothing in it." },
    { s: 'akihiko', f: 'neutral', t: "Sixty-four fifty-eight." },
    { s: 'akihiko', f: 'serious', t: "Same as home. To the second. What it would've been at home tonight." },
    { s: 'mitsuru', f: 'neutral', t: "...So it isn't the town." },
    { s: 'akihiko', f: 'neutral', t: "No. It's us. It came with us. It's keeping time on us." },
    { n: "Mitsuru didn't say anything. She stood on the seawall with her arms folded and looked at the water, and Solar saw her answer the question she hadn't asked at breakfast, and put it away somewhere, and go on standing there." },
    { n: "Yunjin hadn't been on the seawall. Solar found her in the hour, after, on the steps going down from the seawall to the mud, where the tide had gone out and stopped. It had stopped for the whole red, the way it stopped at home, a wall of glass halfway down the flats with the moon in it; and Yunjin had sat on the bottom step for the whole hour and watched it, and hadn't gone into the mud, and was still sitting there." },
    { s: 'yunjin', f: 'neutral', t: "...I slept with the light off. Both nights. Here." },
    { s: 'yunjin', f: 'neutral', t: "It's the right water, Sol. It smells right. It's the right mud. It goes out at the right time. And there's nobody in this whole city who's ever going to knock on my door at three in the morning to tell me somebody's dead." },
    { n: "She didn't say anything else. She didn't have to. It was in the way she was sitting, the way you sit on the step of a house you've been shown round, a house you can afford, a house with the light already on." },
    { n: "The ferry home was at seven." },
    { place: 'Incheon · Ferry Terminal', time: 'Early Morning', bg: 'yakushima-ferry', music: 'tender', date: '8/12' },
    { n: "Nobody said it. That was the thing Solar remembered afterward: that in four days, thirty-one people, nobody once said it out loud." },
    { n: "They stood on the pier at a quarter to seven with their bags at their feet and the hydrofoil white and humming at the end of the gangway, and the horn went, once, long, and nobody moved." },
    { n: "Not for long. A few seconds. The trio with their hands in their pockets, looking at the hill. Haechan with the peach stone he'd kept, turning it over in his fingers. Jungwon looking at his watch, which was running perfectly, which had run perfectly for four days and nights here, the only place since April it had never once stopped. Yunjin on the bollard at the end of the pier with her back to the boat, her face to the mud." },
    { n: "Nobody moved, and nobody said it, and the whole city behind them said it for them, softly, in the voice of a harbor at low tide on a summer morning with no corners in the air: *you could just stay. Nobody would ever have to die here. You could just not get on.*" },
    { n: "Mitsuru, at the foot of the gangway, didn't call anyone. She stood with the passenger list in her hand and waited, and Solar saw that she was waiting on purpose, and saw that she knew that if she said a word, any word, *come on* or *we're leaving* or *stay*, it would be her word they went on, or stayed on, and not theirs." },
    { choose: [
      { t: "(Sit down on your bag. Just for a minute.)", tally: { cakes: 1, 'asks.solar.ferry': 'yes' }, flag: 'eqx-ferry-stayed', then: [
        { n: "She sat down on her bag. Just for a minute. Just to feel what it was like, the sun on the back of her neck and the gulls and the slow mud smell and no hurry anywhere. It felt like putting something down. It felt like the end of a long day." },
        { n: "Around her, one by one, she saw them see her sit, and something in all of them went slack and easy, the shoulders, the hands; Niki sat down on his bag too, and then Eunchae, and Yunjin on her bollard let out a long breath and closed her eyes. And the horn went again, and again, and the third time Mitsuru said *Solar*, very quietly, not a request, just her name, and Solar got up, and they all got up, and got on." },
        { n: "She felt it go, getting up. Something warm and small under her ribs that she'd put down on the pier and couldn't pick up again. She stood at the stern rail as they pulled out and watched the pier get smaller with nobody on it, and couldn't for the life of her have said what she'd left there, only that the boat felt very slightly lighter, and she very slightly less." }
      ] },
      { t: "(Pick up your bag and go up the gangway. First.)", tally: { 'asks.solar.ferry': 'no' }, then: [
        { n: "She picked up her bag and walked up the gangway. First. Without looking back, because if she looked back she'd see their faces. Her footsteps rang on the metal. Behind her, after a second, she heard the others pick up their bags, one after another, the scrape and the zips, and come after her, the way a line comes after the girl at the front of it." },
        { n: "Yunjin came last. She sat down next to Solar in the cabin without a word and didn't speak to her until Japan, and on the pier at Port Island she said, very quietly, *you didn't have to go first*, and walked off before Solar could answer." }
      ] },
      { t: "(Wait. Let them decide for themselves.)", tally: { choose: 1, 'asks.solar.ferry': 'choose' }, flag: 'eqx-ferry-mine', then: [
        { n: "She didn't move. She didn't sit and she didn't go. She stood on the pier with her bag at her feet and her hands at her sides and let the minute be as long as it was, which was the longest minute she'd stood through since the bottom of the Well." },
        { n: "It was Jay who went first, in the end. He picked up Niki's bag and his own and said *bro, I'm not doing the Viking again, I'll die*, and walked up the gangway, and Niki went after his bag, and Sunghoon after Niki. Then Jungwon, looking at his watch. Then the girls. Then, with the peach stone in his fist, Haechan, who stopped at the top of the gangway and turned and looked at her, and didn't say anything, and waited." },
        { n: "Yunjin was the last one on the pier but her. She sat on the bollard for a long time. Then she got up, and looked at the mud one more time, and walked past Solar to the gangway without looking at her, and at the bottom of it she stopped." },
        { s: 'yunjin', f: 'neutral', t: "...You weren't going to say anything. Were you. Either way." },
        { s: 'solar', f: 'neutral', t: "It wasn't mine to say." },
        { n: "Yunjin looked at her for a long moment, with something in her face Solar couldn't read. Then she went up. And Solar went last, and the gangway came up behind her, and the hydrofoil pulled out into the harbor, and the city with nobody in it got smaller and smaller and was gone." }
      ] }
    ] },
    { place: 'Port Island · Ferry Pier', time: 'Daytime', bg: 'port-island-pier', music: 'badfeeling', soft: true },
    { n: "Port Island at two in the afternoon. The heat came off the concrete like something alive. The pier where the old men fished was empty, all the way to the end. No rods, no buckets, no folding stools. Nobody." },
    { n: "Akihiko stood at the top of it with his bag over his shoulder and looked at it for a long time." },
    { s: 'akihiko', f: 'neutral', t: "...There was one left. In May. The one who said no. He was the last one out here. Every morning." },
    { n: "He didn't say anything else. He didn't have to. Down the length of the empty pier, on the bollard at the very end, somebody had left a small white saucer with nothing in it, upside down." }
  ] },

  { id: 'eqx-festival', date: '8/14', slot: 'evening', consumes: true, title: 'somewhere with lanterns', place: 'Naganaki Shrine · Summer Festival', time: 'Evening',
    cast: { solar: 'Solar', cherry: 'Cherry', jihoon: 'Jihoon', haechan: 'Haechan', akihiko: 'Akihiko', jungwon: 'Jungwon', minji: 'Minji', shinjiro: 'Shinjiro', ken: 'Ken', mark: 'Mark', danielle: 'Danielle', junkyu: 'Junkyu', asahi: 'Asahi', hanni: 'Hanni', hyein: 'Hyein', stallkeeper: 'Stall Keeper', junpei: 'Junpei' },
    scene: [
    { bg: 'naganaki-shrine-festival', music: 'trip' },
    { n: "Naganaki's summer festival was on the Saturday of Obon, and it was the first thing in a month that the whole household went to on purpose, in twos and threes and sixes, because Mitsuru had looked at the poster on the dorm door for a long time on Thursday and said, finally, *we're going, all of us, and nobody leaves the lanterns*, as if the lanterns were a wall." },
    { n: "They were, nearly. Strings of them from every eave and tree, red and white, swinging a little in the hot wind off the bay, so many that the shrine grounds glowed like the inside of a paper lamp, and the stalls ran in two rows down to the torii and out into the street beyond it: goldfish, shaved ice, masks, takoyaki, a shooting gallery with a stuffed bear on the top shelf that nobody had won since the war. Taiko on a platform by the main hall. Kids in yukata running between everybody's legs. The smell of sauce and charcoal and sweet bean paste and the sea." },
    { n: "Cherry was in yellow." },
    { n: "The sundress. Solar had seen it in April, in a bag, on the floor of Cherry's room at the guesthouse, with a straw hat on top of it; *for somewhere with lanterns*, Cherry had said, as if it were a place on a map. She was wearing it now. Bare shoulders, the hat pushed back, her hair down, standing under the biggest string of lanterns at the top of the steps with a shaved ice in each hand and her face doing something Solar had never seen it do in either of the lives she'd known it in." },
    { n: "She looked like some girl. Just some girl at a festival. She looked off duty." },
    { s: 'cherry', f: 'happy', t: "Don't. Don't say anything. I know. I know, okay, I *know*." },
    { s: 'jihoon', f: 'happy', t: "She's been standing there for ten minutes waiting for somebody to say something so she can tell them not to." },
    { n: "Jihoon took one of the shaved ices off her, the blue one, and stood beside her eating it, his shoulder against her shoulder. He was in a black T-shirt, his hood down for once. He looked tired and clean and young. Cherry, without looking, reached out with the hand that had just been emptied and took hold of his sleeve, between finger and thumb, the way she did at crossings." },
    { s: 'cherry', f: 'neutral', t: "...A hundred and thirty. Today. I count in the shower." },
    { s: 'jihoon', f: 'neutral', t: "She counts in the shower. She tells everybody she counts in the shower. It's her whole brand now." },
    { s: 'cherry', f: 'happy', t: "It's a good brand." },
    { place: 'Naganaki Shrine · The Stalls', time: 'Evening', bg: 'naganaki-shrine-festival', music: 'joy', soft: true },
    { n: "The shooting gallery was where it started. It was always going to start somewhere." },
    { n: "Akihiko had his eye on the bear. He'd had his eye on the bear since they came through the torii. He paid for five corks and put four of them into it, square in the chest, and it rocked, and didn't fall, and the old man running the stall smiled the smile of a man who'd glued it down in 1987." },
    { s: 'akihiko', f: 'serious', t: "It's weighted. That's a weighted bear." },
    { s: 'haechan', f: 'happy', t: "It's a bear, man. It's a bear at a shrine. Nobody weighted the bear." },
    { s: 'akihiko', f: 'neutral', t: "You do it, then." },
    { n: "Haechan did it. He put three corks into it, all on the left shoulder, the same spot, and it rocked further, and didn't fall, and the old man's smile went fractionally less certain." },
    { n: "They looked at each other. Solar, holding Ken's takoyaki, watched them look at each other, and saw it happen in their faces at exactly the same moment, the thing that had been happening between them since the rope, since the snow on the First Hill, since Akihiko had pried his own fingers off her wrist and Haechan had said *respect*: two boys who'd spent a year and a half wanting to be the one she watched, deciding, at a shooting gallery, in about a second and a half, to stop." },
    { s: 'akihiko', f: 'neutral', t: "Left shoulder. Together. On three." },
    { s: 'haechan', f: 'neutral', t: "On *three*, or on the *three*? Because—" },
    { s: 'akihiko', f: 'serious', t: "On three, Lee." },
    { n: "They fired on three. Both corks hit the left shoulder in the same instant with a sound like a single slap, and the bear went over backward off the shelf, and Ken said *YES* so loud that the taiko drummers looked round." },
    { n: "Then there was the bear, on the counter, between them. And a pause. And Solar watched both of them understand that there was now going to have to be a conversation about who gave it to her, and both of them decide, in the same second and a half, that they would rather die." },
    { n: "Akihiko picked it up and held it out. To Ken." },
    { s: 'akihiko', f: 'neutral', t: "Here. It's yours. You did the hard part." },
    { s: 'ken', f: 'surprised', t: "I didn't do anything. I held the takoyaki." },
    { s: 'haechan', f: 'happy', t: "Exactly. Hardest job here. Respect." },
    { n: "Ken took the bear. It was nearly as big as he was. He stood holding it with both arms round it and his chin on its head, and looked from one of them to the other, and then at Solar, with an expression of enormous twelve-year-old patience, and said, very seriously, *you're both really weird*, and walked off with it toward Koromaru, who was waiting under the lanterns where he'd been told to and who barked at the bear exactly once." },
    { n: "Further down, at the goldfish, Junkyu and Asahi had been kneeling on the edge of the pool for forty minutes with a growing pile of torn paper scoops and no fish. Asahi had stopped trying. He was watching the fish." },
    { s: 'asahi', f: 'neutral', t: "...They're all facing the same way." },
    { s: 'junkyu', f: 'neutral', t: "Because the guy's got a filter going. It's current. It's physics. Give me another scoop." },
    { s: 'asahi', f: 'neutral', t: "The filter's on that side. They're facing that way. Against it." },
    { n: "Solar looked. Two hundred little red fish in a blue plastic pool under the lanterns, all of them, every one, hanging in the water with their noses pointed the same way, out past the end of the stalls, past the torii, downhill, toward the river." },
    { n: "Mark was at the end of the row, by the mask stall, in his coat." },
    { n: "In August. At a summer festival, at seven in the evening, in a heat that had people fanning themselves with the paper programs. The December coat, buttoned. It was damp all over, the way it had been damp since he came, dark at the shoulders as if he'd just walked in out of snow, in a heat that dried everything else in minutes. He looked at the masks, foxes and cats and a smiling white woman's face, and didn't buy one. His hand was on the front of his coat, the inside pocket on the left, pressed flat. He didn't seem to know it was." },
    { s: 'mark', f: 'neutral', t: "...Hey, Sol. Hot one. I'm fine. It just won't dry. I run cold." },
    { n: "He rubbed the back of his neck. He overplayed it, the casual, the way he always did. He didn't take the coat off. Solar didn't ask him to. She'd stopped asking in July." },
    { n: "Danielle was outside the torii. Not at the festival: outside it, on the street, leaning on a lamppost with her phone in her hand, watching people come and go through the gate the way she'd watched people come and go through the guesthouse door in a different life, with a ledger. She lifted two fingers at Solar without smiling. She didn't come in. Her phone screen, when Solar passed close enough to see, was a list. Names, and times, and an arrow by some of them. The arrows all pointed the same way." },
    { s: 'danielle', f: 'neutral', t: "Don't. I'm working. You're not on it. Yet." },
    { place: 'Naganaki Shrine · Amulet Stall', time: 'Evening', bg: 'naganaki-amulet-stall', music: 'mystery', soft: true },
    { n: "The amulet stall had a sign on it in marker. SOLD OUT: HOUSE CHARMS. SOLD OUT: DOOR BELLS. SORRY. The old woman behind it was the same one who'd sold Hanni the bell on the red cord in April. She looked at Solar over her glasses and seemed to remember her, which nobody in this town did." },
    { s: 'stallkeeper', f: 'neutral', t: "Three times this month. Sold out three times. All the river side. They come up the steps in the morning, the old ones, with their purses, and they want something for the door." },
    { s: 'stallkeeper', f: 'neutral', t: "I tell them what I told your friend. A bell tells you somebody's come in. A charm tells whoever's coming that you'd rather they didn't. Neither one of them stops you opening it." },
    { s: 'stallkeeper', f: 'neutral', t: "And they all say, *oh, but I wouldn't open it, not to a stranger*. And I say, *no. Not to a stranger.*" },
    { place: 'Naganaki Shrine · The Steps', time: 'Night', bg: 'naganaki-shrine-night', music: 'date' },
    { n: "The fireworks were at nine, over the bay, and you could see them best from the top of the shrine steps if you got there early, and everybody knew it, so everybody was there, the whole household in a long uneven line along the top step and the ones below it, forty people and a dog and a bear, and somewhere in the pressing and the shuffling and the shaved ice going round, the way it always happens at the top of a set of steps with fireworks coming, people sorted themselves out into twos." },
    { n: "Solar found that there was somebody next to her. She found that she'd half-known who it would be." },
    { choose: [
      { t: "(Haechan.)", flag: 'eqx-fireworks-haechan', then: [
        { n: "He sat down on the step beside her with two cans of barley tea, the way he'd sat down on the roof the night of the whiteboard, and handed her one, and didn't say anything until the first rocket went up." },
        { n: "Gold. It burst over the bay and hung there, and came down slowly in long falling threads, and his face went gold with it, and then dark, and she watched him watch it. She'd watched him watch fireworks before. Through her own hands. On a different street. In a different life that was also this one." },
        { s: 'haechan', f: 'neutral', t: "...Don't say it. I know. Fifth Avenue. I'm thinking about it too." },
        { n: "His hand was on the step between them. Palm down, flat on the warm stone, the pink rope scar across it catching the light from the next one. He didn't move it toward her. He left it exactly where it was, where she could see it, the whole time, like a sentence he'd written down and wasn't going to read out." },
        { n: "She put hers on top of it. He turned his over under hers, slowly, so they were palm to palm, and held on, and didn't look at her, and the sky went green and red and white and gold over the water, and he didn't say anything at all, very loudly, for the whole of it." }
      ] },
      { t: "(Jungwon.)", flag: 'eqx-fireworks-jungwon', then: [
        { n: "He sat down one step below her, so that his shoulder was against her knee, and leaned back against her legs as if it were the most natural thing in the world, which from Jungwon, in public, at a shrine, with Jay three steps away, it was not." },
        { s: 'jungwon', f: 'neutral', t: "...I'm told this is what people do. At these. I read about it." },
        { s: 'solar', f: 'neutral', t: "You read about leaning on someone at fireworks?" },
        { s: 'jungwon', f: 'flustered', t: "I read about a lot of things. I'm very prepared." },
        { n: "The first one went up. Gold. It lit the whole of the bay, and the long white line of the bridge across it, and his face tipped back against her knee looking up. She put her hand in his hair. He went very still under it, and then less still, and then, by the third one, not still at all, his head resting back against her, his eyes half shut, the most unguarded she'd ever seen him in any life." },
        { s: 'jungwon', f: 'neutral', t: "...Nobody here needs me to be anybody. I keep saying it. I'm going to keep saying it until I believe it's bad." }
      ] },
      { t: "(Jihoon.)", flag: 'eqx-fireworks-jihoon', then: [
        { n: "He didn't sit next to her. He came and stood behind her, on the step above, so close she could feel the heat off him through the back of her shirt, and put his chin on the top of her head." },
        { s: 'jihoon', f: 'neutral', t: "Hi. Don't turn round. Cherry's watching. Cherry's always watching. She'll tell me I'm being obvious." },
        { s: 'solar', f: 'neutral', t: "You're being obvious." },
        { s: 'jihoon', f: 'happy', t: "I'm being *tall*. It's different." },
        { n: "The first one went up. In the light of it she could see his hands, on either side of her, on the stone of the step, very near her hips and not touching them, his knuckles pale. A hundred and thirty days. She knew he was counting too. She knew he knew she knew." },
        { s: 'jihoon', f: 'neutral', t: "...I keep thinking, nobody's filming. Nobody at home's ever going to see this. I could stand here all night. I could put my arms round you right now in front of forty people and there's not one camera in this whole stupid perfect town that'd post it." },
        { n: "He didn't, though. He stood there with his chin on her head and his hands on the stone either side of her and watched the sky go off over the water, and on the last one, the big gold one that hung longest, he put his mouth to her hair, just once, just there, where nobody but her would know, and then stepped back down into the crowd before it had finished falling." }
      ] },
      { t: "(Akihiko.)", flag: 'eqx-fireworks-akihiko', then: [
        { n: "He sat down next to her with his taped hand in his lap and his elbows on his knees and looked straight ahead at the bay, very seriously, the way he looked at a ring before a bout." },
        { s: 'akihiko', f: 'neutral', t: "I gave the bear to Ken." },
        { s: 'solar', f: 'neutral', t: "I saw." },
        { s: 'akihiko', f: 'neutral', t: "I want it noted that I'd have given it to you. If it hadn't been— if he hadn't been there. I want that on record." },
        { s: 'solar', f: 'neutral', t: "It's on record." },
        { n: "The first one went up. He flinched at the bang, a fraction, and covered it, and she pretended not to see. In the gold light his taped hand had closed, on his knee, by itself, round nothing; it did that now, he'd told her, at night. She watched him notice. She watched him open it, one finger at a time, deliberately, and lay it flat on his knee, palm up, and leave it there." },
        { s: 'akihiko', f: 'neutral', t: "...You can. If you want. I'm not going to hold on. I'll just be here." },
        { n: "She put her hand in his. He didn't close his on it. He held still and let her hand lie in his open one for the whole of the fireworks, and it was harder for him, she could tell, than anything he'd done in a ring." }
      ] },
      { t: "(Minji.)", flag: 'eqx-fireworks-minji', then: [
        { n: "Minji sat down beside her and put the camera up, and then, for the first time Solar could remember in this whole year, put it down again, on the step, lens to the stone, and left it there." },
        { s: 'minji', f: 'neutral', t: "...I'm not going to film these. I've decided. I'm going to just look at them. Like a person." },
        { s: 'solar', f: 'neutral', t: "How's that going?" },
        { s: 'minji', f: 'serious', t: "Badly. My hand's itching. I'm going to see them all in frames anyway. I can't not." },
        { n: "The first one went up, and Minji watched it with her whole face, and Solar watched her watch it, and at the second one Minji's hand, the one that had wanted the camera, found Solar's on the step between them instead, and held it, and Solar felt the calluses on her fingertips from the focus ring." },
        { s: 'minji', f: 'neutral', t: "...Fourteen thousand two hundred and six. I keep a count. This one's not going in it. This one's just mine." }
      ] },
      { t: "(Shinjiro.)", flag: 'eqx-fireworks-shinjiro', then: [
        { n: "He didn't sit. He stood at the end of the step with his hands in his coat pockets and his collar up, in August, the way he stood everywhere, a little apart. When she looked at him he looked at the bay." },
        { s: 'shinjiro', f: 'neutral', t: "...Ate yet?" },
        { s: 'solar', f: 'neutral', t: "Takoyaki. Half of Ken's." },
        { s: 'shinjiro', f: 'neutral', t: "That's not eating." },
        { n: "He took his hand out of his pocket. In it, wrapped in a paper napkin, was a rice ball. Not from a stall. Not from anywhere in this town. His. Lopsided, the seaweed on crooked, because his right hand still shook when he pressed. He held it out without looking at her." },
        { s: 'shinjiro', f: 'neutral', t: "Plum. Made it before we left. Figured you'd do this." },
        { n: "She ate it on the step while the sky went gold and red over the water, and he stood beside her and watched her eat it instead of watching the fireworks, and when she finished he took the napkin back off her and folded it and put it in his pocket, as if it were something worth keeping, and said *good*, very quietly, and that was all." }
      ] },
      { t: "(Hanni and Hyein, one on each side.)", flag: 'eqx-fireworks-girls', then: [
        { n: "They sat down on either side of her at the same moment, as if they'd planned it, which they had, and Hyein put her head on Solar's shoulder and Hanni put her arm through Solar's arm and held on." },
        { s: 'hyein', f: 'neutral', t: "We're claiming you. For the fireworks. Everybody else had you all day." },
        { s: 'hanni', f: 'neutral', t: "It's on the rota. I wrote it on the rota. *Fireworks: H, H, S.* Mitsuru initialled it." },
        { n: "The first one went up. Gold. Hyein flinched at the bang and then laughed at herself and didn't lift her head. Hanni held on harder." },
        { s: 'hyein', f: 'sad', t: "...We used to do this. At home. Remember? The roof, the Fourth. The three of us and a blanket and you being a nightmare about the blanket." },
        { s: 'solar', f: 'neutral', t: "You took the whole blanket." },
        { s: 'hyein', f: 'happy', t: "*You* took the whole blanket. Hanni, tell her." },
        { s: 'hanni', f: 'neutral', t: "You both took the whole blanket. I sat on the roof." },
        { n: "They watched the rest of it like that, the three of them in a knot on the top step, and nobody said anything about home again, and Hanni didn't let go of her arm until the last one had fallen all the way into the bay and gone out." }
      ] }
    ] },
    { place: 'Naganaki Shrine · The Steps', time: 'Night', bg: 'naganaki-shrine-night', music: 'eerie', soft: true },
    { n: "Afterward, when the smoke was drifting off over the town and the crowd was coming down the steps in a slow pressing river toward the street, Solar stood at the top a moment longer and watched the lanterns." },
    { n: "The ones furthest down, at the bottom of the shrine's lane, out by the street, were going out. Not all at once. One string at a time. The last string by the torii, and then the one before it, and then the one before that, from the street up the lane toward the shrine, *tick, tick, tick*, the way a row of houses goes dark at bedtime, each one a beat after the last." },
    { n: "It wasn't the wind. There wasn't any. It wasn't the stallholders; they were still packing up, in the dark now, swearing, groping for their flashlights. It was just the lanterns going out, one string at a time, in order, coming up the lane." },
    { n: "Then they stopped. Halfway. With half the lane dark and half of it lit, and the line between them very straight, like a tide line." },
    { n: "Junpei, beside her, had seen it too. He'd stopped on the step with the betting book under his arm, the one he carried everywhere now, and was looking at the dark half of the lane with his mouth a little open." },
    { s: 'junpei', f: 'neutral', t: "...Which way's the river from here?" },
    { s: 'solar', f: 'neutral', t: "That way." },
    { n: "She didn't need to point. The dark half of the lane was the half nearest the river. Junpei looked at it for a long moment, and then put the book inside his shirt, against his chest, and buttoned the shirt over it, and went down the steps without making a single joke, and caught up with Ken and the bear, and walked the whole way home on the side of Ken nearest the river." }
  ] },

  { id: 'eqx-lanterns', date: '8/16', slot: 'evening', consumes: true, title: 'the lanterns go home', place: 'Iwatodai · Riverside', time: 'Evening',
    cast: { solar: 'Solar', ken: 'Ken', jungwon: 'Jungwon', shinjiro: 'Shinjiro', mitsuru: 'Mitsuru', akihiko: 'Akihiko', mrsoka: 'Mrs. Oka', aigis: 'Aigis' },
    scene: [
    { bg: 'iwatodai-riverside-night', music: 'tender' },
    // BG: eqx-riverside-obon — the riverbank in Iwatodai at dusk on the last night of Obon, people crouched at the water's edge setting small paper lanterns afloat, dozens of little lights drifting on dark water, a long bridge far downstream against the last of the sunset.
    { n: "The last night of Obon was the night you sent them home." },
    { n: "Ken explained it on the walk down, carefully, in the voice he used for things he'd looked up. The dead came back for three days in August, to the houses they'd lived in, and you lit a fire at the gate so they could find the way, and fed them, and on the last night you set paper lanterns on the river, and the river carried them down to the sea, and the lanterns took the dead with them, back where they'd come from. So they wouldn't get lost. So they wouldn't stay." },
    { s: 'ken', f: 'neutral', t: "That's the important part. They're not supposed to stay. If they stay it's— it's not good for them. Or for anybody. They have to go back." },
    { n: "He was carrying his lantern in both hands. A little square paper box on a wooden float, with a candle stub inside it, and on the paper, in his neatest characters, a name. He'd written it four times on scrap first, in the dorm kitchen, to get it right." },
    { n: "*Suemitsu Nozomi.*" },
    { n: "Half the town was at the riverbank. Families, old couples, children, crouched along the water's edge in the dusk with their lanterns, lighting the candles with long matches, setting them down on the water, giving them a little push. The river was low and slow and brown. It took them. Downstream, a long line of them already, dozens, a hundred little lights going away in the dark water toward the sea, toward the bay, toward the long white line of Moonlight Bridge lying across the mouth of the river in the last of the sunset." },
    { n: "Jungwon had one. Solar hadn't known he would. He'd written it in Japanese, which he wrote like a careful foreign student, very straight. *Tanabe.* No first name. He'd never known it. He crouched at the water and lit the candle and sat looking at it for a long time with the match burning down in his fingers until it burned him." },
    { s: 'jungwon', f: 'neutral', t: "...I checked his chain at eleven. Every night. I wrote it in the diary. *Chain on.* I wrote *chain on* on the night of the twenty-eighth." },
    { s: 'jungwon', f: 'neutral', t: "I still write it. Every night at eleven I go down and I look at the new man's door. He doesn't even have a chain. He thinks I'm strange." },
    { n: "Shinjiro had one too. He didn't explain it. *Hata*, it said, in a crooked hand, the characters leaning, written with his right hand in a fist. He set it down on the water without crouching, bending from the waist, and gave it a push with two fingers, and stood back up, and put his hands in his pockets." },
    { s: 'shinjiro', f: 'neutral', t: "...He snored. In the next bed. Eight months. I used to lie there wishing he'd shut up." },
    { n: "Solar had three. She'd written them at the kitchen table after Ken, when he'd gone up to get his matches, and she hadn't decided until she was doing it. *Hata. Tanabe. Suemitsu.* One each. They weren't hers. Nobody had asked her to. She'd just thought that somebody should send them all, in case." },
    { n: "She set them down. The river took them. Four of theirs, then hers, a little cluster of lights in the dark water going away from the bank, catching up with the others, joining the long line downstream." },
    { n: "And then they stopped." },
    { place: 'Iwatodai · Riverside', time: 'Evening', bg: 'iwatodai-riverside-night', music: 'eerie', soft: true },
    { n: "Not just theirs. All of them. The whole river of lights, the hundred little lanterns going down to the sea: in the middle of the river, about fifty meters down, the leading ones slowed, and turned on the current the way a boat turns at anchor, and stopped. The ones behind came up and bumped against them gently and stopped too. The river kept flowing. You could see it flowing, brown and slow, the reeds at the edge leaning with it. The lanterns sat on top of it, still, as if somebody had put a hand flat on the water." },
    { n: "A murmur went down the bank. People standing up. A woman laughed, uncertainly. Somebody said *the tide*, and somebody else said *it's a river*." },
    { n: "Then the lanterns started to come back." },
    { n: "Slowly. Against the current. All of them, together, the whole long line of little lights turning round and coming back up the river the way they'd gone down it, past the bank where the town stood watching with its matches still in its hands, past the families and the old couples and the children, past Ken, who had taken a step back and then another, and kept coming, upstream, unhurried, steady, the candles not even flickering, toward the bend." },
    { n: "Solar knew the bend before she looked. Where the river curved round behind the gardens of the old houses on the river street. Where the boarding house garden came down to the water in three stone steps, under the persimmon tree." },
    { n: "Mrs. Oka was standing on the bottom step." },
    { n: "In a dark summer kimono, with her apron on over it, white, and her white gloves. She'd lifted the corners of the apron to make a sort of bowl of it, the way a woman in a field holds up her apron to gather fruit. And as the lanterns came up the river to her, one by one, unhurried, she bent and took them out of the water, one by one, and blew out each candle with a little puff, the way you blow out a birthday candle for a child, and put them in her apron." },
    { n: "One by one. A hundred of them. The town watched her do it from fifty meters away. Nobody moved. The light on the river went out lantern by lantern, coming nearer and nearer to the steps, until it was only her, at the bottom of her garden, in the dusk, with her apron full of paper boxes and a little smoke going up from them, and the last three lanterns coming to her across the dark water in a little cluster." },
    { n: "Solar's. She knew them by the handwriting." },
    { n: "Mrs. Oka took them out of the river. She looked at each one. She read them, Solar thought, she couldn't have read them from there, but she held each one up to the last of the light and looked at it and smiled, and blew it out, and put it in her apron with the others, and then she looked up the river, along the bank, at the town standing there with its matches, and found Solar among them, fifty meters off in the dusk, as easily as if she'd been standing next to her." },
    { n: "And waved. A small wave, with her gloved hand. The way you wave across a street at somebody you're expecting for supper." },
    { n: "Ken made a sound. Not a word. Shinjiro's hand came down on the back of his neck and stayed there." },
    { s: 'mitsuru', f: 'neutral', t: "...Everybody home. Now. Twos. Don't run." },
    { n: "Nobody ran. That was the worst part. The whole town turned and went quietly up the bank in the dusk with its matches and its empty hands, not looking at each other, the way people leave a room where somebody has said something unforgivable at dinner, and nobody said anything, and in the morning, Solar knew, nobody would remember it at all." },
    { place: 'Iwatodai · Riverside Path', time: 'Night', bg: 'moonlightbridge-night', music: 'mystery', soft: true },
    { n: "She was the last one off the bank. She'd stayed a second too long, looking at the bend; and so she was the only one who looked the other way, downstream, at the mouth of the river where it opened into the bay under the bridge." },
    { n: "There was a woman on the bridge." },
    { n: "In the dusk. Not at midnight. Not in the red. In the ordinary blue end of an ordinary summer evening, with the lamps along the bridge just coming on and the traffic going over it in two bright lines. A woman at the rail, halfway across, with her back to the road. A long blue coat, in August, buttoned to the throat. A black case at her feet, open. And her arm moving, slow, long, the bow going *the long way round*, and across a kilometer of water, over the traffic and the town and the evening, very faint, so faint Solar would never be sure afterward she hadn't made it up, a viola." },
    { n: "Akihiko had come back for her. He stood beside her on the path and followed her eyes down the river to the bridge, and saw it, and went very still." },
    { s: 'akihiko', f: 'serious', t: "...That's her. That's the one from June. In daylight. She's never been there in daylight." },
    { s: 'akihiko', f: 'neutral', t: "You said a name. On the bridge. In June. You said a name and she stopped playing. You've never said it since." },
    { n: "Mitsuru was there too, at the top of the path, waiting with Aigis. She'd heard. She came down two steps and stood looking at Solar with the look she'd had in the lounge, over the whiteboard, with the red pen in her hand." },
    { choose: [
      { t: "Her name's Hanne. I knew her. Last year. She went home.", flag: 'eqx-hanne-told', then: [
        { n: "She told them. All of it, on the riverside path in the dark, with the viola going faint over the water the whole time and Aigis standing very still at the top of the steps listening the way she listened to everything, as if it would be needed later." },
        { n: "The woman on the station steps, twice, the year before last, a case and a coat and a face like a held breath; walked past, both times, because everyone walked past. The Last Train. The platform at the end of everything, and saying her name, and the woman waking up, and a door. Elizabeth's door. Hanne going home through it. The door closing. Solar watching it close." },
        { s: 'mitsuru', f: 'neutral', t: "...She went home. You saw her go." },
        { s: 'solar', f: 'neutral', t: "I saw the door close." },
        { s: 'akihiko', f: 'neutral', t: "Then what's she doing on our bridge." },
        { n: "Nobody had an answer. Mitsuru looked downriver at the bridge for a long time. Then she took her phone out and typed something into it, with her thumb, slowly, and Solar knew without seeing it that in the morning there would be a new line on the whiteboard, under HUNTING, under the boxed names, in red, with a question mark after it." },
        { s: 'mitsuru', f: 'neutral', t: "Hanne. The violist. Thank you." },
        { s: 'mitsuru', f: 'serious', t: "...That's the first name. Do you understand? Since April. It's the first name anyone's been able to give me." }
      ] },
      { t: "(Say nothing. Watch her play.)", then: [
        { n: "She didn't say anything. She stood on the path and watched the woman on the bridge, a kilometer off, playing to the bay in the blue dusk with her back to the whole town, and Akihiko waited, and Mitsuru waited, and Solar didn't say it." },
        { n: "It was her name. It was the only thing anyone had ever given her. Solar didn't want to be the person who wrote it on a whiteboard under that word." },
        { n: "Mitsuru looked at her a long time. Then she nodded, once, the way she nodded at a figure she'd come back to, and went up the steps with Aigis without a word; and Akihiko stayed, and stood with Solar until the lamps on the bridge were all lit and the woman at the rail was only a shape, and then not even that." }
      ] }
    ] },
    { n: "The viola stopped. Mid-phrase. The way it had stopped in June." },
    { n: "On the bridge, a kilometer off, in the lamp light, the shape at the rail bent, and closed the case, and stood up with it; and for one second, before the traffic hid her, she turned her head. Not toward the town. Upriver. Toward the bend. Toward the garden steps and the persimmon tree and the woman standing at the bottom of them with her apron full of little paper boxes." },
    { n: "Akihiko texted the hour at one that night. *65:10.* And under it, a minute later, in a separate message, as if he'd typed it and deleted it and typed it again: *she's not the one who's eating. I don't know how I know that.*" }
  ] },

  { id: 'eqx-table-op', date: '8/25', slot: 'evening', consumes: true, title: 'the long table', place: 'Iwatodai Dorm · Lounge', time: 'Evening',
    cast: { solar: 'Solar', mitsuru: 'Mitsuru', haechan: 'Haechan', jungwon: 'Jungwon', fuuka: 'Fuuka', chenle: 'Chenle', chaewon: 'Chaewon', jaehyun: 'Jaehyun', yunjin: 'Yunjin',
      'jaesang-runners': 'Jaesang', 'solji-runners': 'Solji', 'taesang-strangers': 'Taejoon', 'miyeon-strangers': 'Miseon', 'kim-dad': 'Mr. Kim', 'kim-mom': 'Mrs. Kim', mrsoka: 'Mrs. Oka', akihiko: 'Akihiko' },
    scene: [
    { bg: 'iwatodaidorm-livingroom-night-summer', music: 'badfeeling' },
    { n: "The moon came up full over the bay at a quarter to seven, enormous and orange and low, and by nine it had climbed and gone white and small and hard, and the whole dorm was in the lounge, waiting, the way they waited now on full moons, with the lights on and nobody pretending to watch the television." },
    { n: "Akihiko had the stopwatch on the coffee table in front of him, face up. Sixty-six oh two last night. He'd said, at dinner, *it'll be fifteen over, tonight, at least, the full moons go up every time*, in the voice of a man reading a weather forecast for a town he didn't live in." },
    { s: 'fuuka', f: 'neutral', t: "...Mrs. Oka set the long table on Saturday. For dinner. All the way down. Forty places. Kazuha told me. And then on Sunday she didn't clear it. And on Monday she set it again, on top. And today she's set it a third time." },
    { s: 'fuuka', f: 'sad', t: "Kazuha says there are three of everything at every place now. Three bowls. Three cups. Three pairs of chopsticks. Stacked. And nobody's come for supper since Saturday. She asked them not to. She said she was expecting people." },
    { s: 'mitsuru', f: 'neutral', t: "Who?" },
    { s: 'fuuka', f: 'neutral', t: "She didn't say. She just said, *family*." },
    { n: "Jaehyun and Yunjin were on the rota at the boarding house tonight. Twos. They'd gone down at eight, after Mitsuru had said, once, flatly, *you don't have to*, and Jaehyun had said, *it's my box on the rota*, and that had been the end of it." },
    { n: "At eleven-forty, Mitsuru's phone rang. Chaewon. On speaker. Her voice very low and very steady, the voice of a girl counting the beats so the others could keep time." },
    { s: 'chaewon', f: 'neutral', t: "We're all in the big room. All six of us. Light on. Door shut. We're fine." },
    { s: 'chaewon', f: 'serious', t: "Somebody's laying the table downstairs. We can hear it. Plates going down. Cups. It's been going for ten minutes. It's very— it's very careful. It's not stopping." },
    { s: 'chaewon', f: 'neutral', t: "We're not opening the door. Jaehyun-ssi says to tell you we're not opening the door." },
    { s: 'mitsuru', f: 'neutral', t: "Good. Don't. We're coming." },
    { n: "Mitsuru was already up. Solar was already up. It was always going to be the boarding house; she thought, afterward, that she'd known since the whiteboard. Mitsuru looked round the lounge once, the way she did, counting, and Solar saw her decide." },
    { s: 'mitsuru', f: 'neutral', t: "Haechan. Jungwon. Solar. With me. Fuuka, Chenle, the command room. Akihiko, you have the dorm." },
    { s: 'akihiko', f: 'serious', t: "Mitsuru—" },
    { s: 'mitsuru', f: 'neutral', t: "You have the dorm. Somebody has to have the dorm." },
    { place: 'The Oka Boarding House · Front Hall', time: 'The Dark Hour', bg: 'darkhour-dorm-lounge', music: 'darkhour' },
    { dark: true },
    // BG: oka-hall-redhour — the narrow front hall of an old Japanese wooden house in the red Dark Hour, a step up from the entry, a dark staircase going up on one side, closed paper doors along the other, one lamp burning red at the end of the hall.
    { n: "The red came as they turned into the river street, at a run, and the river went the color of the inside of a mouth, and the persimmon over the wall went black against it, every little green fruit standing out like a knuckle." },
    { n: "The gate was open. The front door was open. Not a hand's width. All the way, slid back to the frame, the way you'd leave it for a crowd." },
    { s: 'fuuka', f: 'surprised', t: "*Solar— I can hear six upstairs. Six heartbeats, all in one room, they're— they're okay, they're scared. And the rest of the house is—*" },
    { s: 'chenle', f: 'neutral', t: "*It's loud. The house is really loud, it's like a— like a busy restaurant with the sound off. I can't find anything in it. There's a room at the end of the upstairs hall and it's quiet. It's the only quiet place. Like the bridge.*" },
    { s: 'fuuka', f: 'neutral', t: "*Mrs. Oka's room. That's her room. Don't— there's no reason to go in there. There'll be a coffin. Don't go in there.*" },
    { n: "Nobody had been going to. Solar looked up the dark stairs anyway, to the landing, to the end of the upstairs hall where a door stood shut with no light under it, and couldn't look away from it for a second, and then could." },
    { n: "The sounds were coming from the front room. Small, and careful, and domestic. *Click.* A plate set down on wood. *Click.* A cup. *Click, click*, chopsticks laid side by side. Unhurried. Like somebody setting a table for guests they were very much looking forward to." },
    { place: 'The Oka Boarding House · The Long Table', time: 'The Dark Hour', bg: 'eqx-oka-kitchen', music: 'badfeeling' },
    // BG: oka-dining-room-redhour — the long low dining room of the old house in red light, the table running the length of the room set with stacked bowls and cups at every place, every cushion but one at the far end pushed back to the walls.
    { n: "The long table ran the length of the room. Every place was set, three deep, bowls stacked on bowls, cups on cups, the way Kazuha had said. Every cushion had been taken away and stacked against the walls. All but the ones at the far end." },
    { n: "At the far end, the head of the table, where nobody ever sat, there were three places set side by side. Not stacked. Three bowls, three cups, three pairs of chopsticks laid neat. And a little folded card at each one. And behind them, one chair." },
    { n: "One. A real chair, a Western one, wooden, with arms, the kind that didn't belong in a house like this at all. Placed square behind the middle setting, waiting." },
    { n: "Solar went down the side of the table, along the wall, toward the head of it, and Haechan came with her, at her shoulder, and Jungwon at her back. She could see the cards now. Three of them. A name on each. Her name, on all three." },
    { n: "*Solar Lee*, the first said, in English, in a round neat hand with a little flourish on the S, a hand she knew from every birthday card she'd ever got in one life, from every note in a lunchbox." },
    { n: "*이솔라*, said the second, in Korean, small and upright and precise, the way the cards on the side table in a house on a hill had always been written, a hand she'd watched write her name on an envelope once, very carefully, as if it might break." },
    { n: "*김솔라*, said the third, in quick slanting Korean that ran off the edge of the card, the hand on every permission slip and every sticky note on a steel door that had ever said *rice in the cooker, don't wait up*." },
    { n: "Her mothers' handwriting. All three. Laid out at a table in the red, at three places, in front of one chair." },
    // CG: eqx-three-cards — the head of a long low table in red light: three neat place settings side by side, each with a small folded place card in a different handwriting, and one wooden Western armchair standing empty behind them.
    { s: 'haechan', f: 'neutral', t: "...Don't touch them." },
    { s: 'jungwon', f: 'neutral', t: "Solar. Don't sit down." },
    { n: "She hadn't been going to. She hadn't. She was only standing very close to the chair, close enough to see that the wood of its arms was worn pale in two places, where hands had held them, and that the seat was a little dished in the middle, the way a seat goes when somebody has sat in it every night for years, and that it was warm. She could feel it from where she stood. Warm, like somebody had just got up." },
    { n: "Behind her, along the walls, the stacked cushions moved." },
    { n: "Not the cushions. The chairs. There'd been no chairs. There were chairs now, three of them, standing against the wall in the red where the cushions had been, three Western chairs like the one at the head of the table, wooden, empty, with arms; and as she turned, all three of them turned too, on their legs, scraping on the tatami, *skrrrk*, toward her." },
    { n: "They didn't have faces. They didn't need them. They came down the room the way chairs come down a room when somebody's pushing them in to a table, all three at once, the legs scraping, the empty seats toward her, and from each empty seat, as it came, a voice. Not one voice. Two in each. A man's and a woman's, together, like a couple finishing each other's sentence." },
    { n: "*Which one is ours?*" },
    { n: "In English. In Korean, softly. In Korean again, quick and cross. *Which one is ours. Which one of you is ours. Which one, which one, there's only one chair, which one of you is ours—*" },
    { s: 'mitsuru', f: 'serious', t: "Behind me. All of you. Now." },
    { n: "The middle chair rose. It went up off the floor on its four legs the way a held breath goes up, and over the table, scattering the stacked bowls, and stood in the air above the three settings with its empty seat turned down at Solar like a mouth, and the other two came up on either side of it, and the voices stopped being two at a time and became six at once, all of them, three couples at once, every one of them asking, *which one is ours*, *ours*, *ours*." },
    { s: 'haechan', f: 'serious', t: "*Dalnim.* Come on." },
    { s: 'jungwon', f: 'serious', t: "Hyeonmu." },
    { summon: 'haenim', name: 'Haenim', sub: 'The Long Table.' },
    { battle: { id: 'eqx-table-op', op: 'eqx-table-op', kind: 'operation', title: 'Full Moon · The Long Table', desc: 'A long table in the red, set three deep, three place cards in three hands at its head, and one empty chair. The chairs want to know which one of her is theirs.', forced: true } },
    { music: 'night' },
    { n: "The last chair came down on the table and broke. Not like a Shadow breaks, into ash; like a chair breaks, with a crack of dry wood, the legs going out four ways and the seat splitting down the grain. It lay across the three settings. The voices went out of it in a long sigh, six voices letting go of one word." },
    { n: "Then it was quiet. The red, and the long table, and the broken bowls, and the four of them standing in it breathing hard." },
    { n: "And then it wasn't empty." },
    { n: "Solar didn't see them come. Nobody did; she asked, after, and nobody had. She looked down at the broken chair on the table, and looked up, and there were people sitting at the long table." },
    { n: "Six of them. Sitting on nothing, on the bare tatami, three on each side of the head of the table, as if they'd been there all evening and had only just this second been noticed. Blinking in the red. Looking at their hands, at the bowls in front of them, at each other. In the clothes they'd been wearing somewhere else, a moment ago, in a life where it had been some other time of night." },
    { n: "A man in a dark suit with the tie pulled loose, a pen still in his hand, uncapped. A woman beside him in a cream cardigan, with her reading glasses pushed up into her hair, very still, the way people are still when they've walked into a room and forgotten why." },
    { n: "Across from them, a man in shirtsleeves, gray at the temples, square-shouldered, sitting very upright with his hands flat on his knees, as if he'd been sitting at the bottom of a staircase and the staircase had been taken away. A woman beside him in a soft house cardigan with her hair pinned up, and on her right hand, on the third finger, a ring she turned once, with her thumb, without looking at it." },
    { n: "And at the end, a man in a gray fleece with a television remote in his hand, looking at it with total incomprehension; and a woman in a jacket with her handbag over her shoulder and her car keys in her fist, held so hard the teeth of the keys stuck out between her knuckles, as if she'd been on her way out of a door to go and look for somebody." },
    // CG: eqx-long-table-six — six adults in ordinary clothes from three different homes sitting along both sides of a long low table in a red-lit Japanese dining room, blinking, bewildered, a broken wooden chair lying across the bowls at the table's head and a girl standing frozen behind it.
    { n: "Six of them. Looking up. At the head of the table. At her." },
    { n: "Nobody said anything for a long time." },
    { n: "Then the man in the fleece looked from the remote in his hand to the girl standing at the head of the table, and from her to the other five people round him, and said, slowly, in Korean, in the voice of a man who's been asked a question on a quiz show he hasn't been watching:" },
    { s: 'kim-dad', f: 'surprised', t: "...Which one is ours?" },
    { s: 'kim-mom', f: 'serious', t: "Don't be stupid. That's her." },
    { s: 'kim-mom', f: 'neutral', t: "That's her. Look at her. She's standing exactly the way she stands when she's broken something." },
    { n: "And all six of them stood up." },
    { n: "Solar couldn't remember, after, which of them reached her first. She remembered arms, a lot of arms; she remembered being held from three sides at once and the smell of three different houses, a perfume she'd bought one woman for Christmas in one life and soap from a bathroom in another and laundry powder from a third, and her own face pressed into somebody's cardigan, and the car keys digging into her back between her shoulder blades because Mrs. Kim had forgotten she was holding them and wasn't going to let go of either." },
    { n: "She remembered a hand on her hair. Small and dry and careful, the ring cold against her scalp. Not stroking. Just resting there, the way you'd put your hand on something to make sure it was solid." },
    { s: 'miyeon-strangers', f: 'sad', t: "...You've not been eating." },
    { n: "That was all Miseon said. That was all she ever said, Solar would think later, in any life; and it meant everything it had ever meant." },
    { ifFlag: 'eqx-from-strangers-family', then: [
      { n: "Taejoon didn't hold her. He stood behind his wife with his hands at his sides and looked at Solar over Miseon's shoulder, and his jaw worked, and when he spoke it was so low that only she heard it." },
      { s: 'taesang-strangers', f: 'neutral', t: "...Was the light still on? When you went. The one on the stairs. I left it on." },
      { s: 'solar', f: 'neutral', t: "It was on, Appa." },
      { n: "He nodded. Once. As if a figure had come out right. Then he looked away at the wall, for a long time, and didn't say anything else at all, very loudly." }
    ], else: [
      { n: "Taejoon didn't hold her. He stood behind his wife with his hands at his sides and looked at Solar over Miseon's shoulder, and his jaw worked, and when he spoke it was so low that only she heard it." },
      { s: 'taesang-strangers', f: 'neutral', t: "...Sol-ah." },
      { n: "Just that. Her name, the short way. He nodded, once, as if a figure had come out right, and then looked away at the wall for a long time, and didn't say anything else at all, very loudly." }
    ] },
    { n: "Jaesang was the last. He stood at the edge of it, in his loosened tie, with the pen still in his hand, and Solar saw him look at her, and then past her, over her shoulder, at the door of the front room, where Jaehyun had come down the stairs, against every rule on every rota, and was standing in the doorway in his socks with his hand on the frame and his face white." },
    { n: "Father and son looked at each other across the long table in the red. Solar had never once in her life seen either of them not know what to say." },
    { s: 'jaesang-runners', f: 'neutral', t: "...Jaehyun." },
    { s: 'jaehyun', f: 'neutral', t: "Dad." },
    { s: 'jaesang-runners', f: 'neutral', t: "You didn't— you didn't pick up. I called. Every morning. Seven fifteen. You didn't pick up." },
    { n: "Jaehyun opened his mouth. Nothing came out of it. Solji went past her husband, past the end of the table, without a word, and took her son's face in both her hands in the doorway, the way you'd take hold of something you'd dropped and found again, and Jaehyun's knees went, a little, and he put his forehead down on his mother's shoulder and stayed there." },
    { n: "Jaesang looked down at the pen in his hand. He capped it. Carefully. He put it in his inside pocket. He straightened his cuff. And then he stood there in the red with nothing left in his hands to do, and looked at his daughter, and Solar watched her father, who had a plan for everything, understand that he didn't have one for this." },
    { place: 'The Oka Boarding House · The Long Table', time: 'Late Night', bg: 'eqx-oka-kitchen', music: 'eerie' },
    { dark: false },
    { n: "The red went out at nineteen minutes to two. Late, even for a full moon. Akihiko would text it later: *78:12*. The lamp over the long table came on by itself, ordinary yellow, as if somebody had been waiting with a hand on the switch." },
    { n: "And down the stairs, slowly, one hand on the wall, the way an old woman comes down in the night, came Mrs. Oka." },
    { n: "In her cotton nightgown and her cardigan, her gray hair down in a plait over one shoulder. And her gloves on. She stopped in the doorway of the front room, beside Solji and Jaehyun, and looked down the long table at the six strangers standing round her daughter at the head of it, and put her gloved hands together under her chin, and her eyes filled." },
    { s: 'mrsoka', f: 'happy', t: "Oh. Oh, look. Look at you all. Six of you. Six!" },
    { s: 'mrsoka', f: 'happy', t: "I knew it. I knew you'd come. I've had the table set since Saturday. I said to the girls, I'm expecting family." },
    { n: "She came in, past them, along the table, touching the backs of their shoulders lightly as she went, *welcome, welcome, welcome*, the way you touch the heads of children at a door, and reached the head of the table, and looked at the broken chair lying across the three settings, and clicked her tongue softly, fondly, as if someone had spilled a drink." },
    { s: 'mrsoka', f: 'neutral', t: "Never mind. Never mind that. There's room for everyone. There's always room. Sit down, sit down, all of you, you've come such a long way. I'll put the rice on." },
    { n: "Mitsuru was in the doorway behind them, with her hand on the hilt of her rapier, not drawing it, very white. Solar watched her look at the six parents, and at the landlady, and at the table set three deep, and do the sums, and come out with a number she didn't like." },
    { n: "Mr. Kim, beside Solar, still had the television remote. He looked at it. He looked at Mrs. Oka, already at the kitchen door, the light on in the kitchen, the sound of water running into a pot. He leaned down to his daughter, who he hadn't seen in he didn't know how long, in a country he didn't know he was in, in the middle of the night, and said, in Korean, very quietly, in the voice of a man trying very hard to be a good guest:" },
    { s: 'kim-dad', f: 'neutral', t: "...Who's the nice lady?" },
    { flag: 'eqx-parents-here' }
  ] },

  { id: 'eqx-three-breakfasts', date: '8/26', slot: 'early', consumes: true, title: 'all of them right', place: 'The Oka Boarding House · The Long Table', time: 'Early Morning',
    cast: { solar: 'Solar', mrsoka: 'Mrs. Oka', mitsuru: 'Mitsuru', junpei: 'Junpei', haechan: 'Haechan', jungwon: 'Jungwon', jihoon: 'Jihoon', jaehyun: 'Jaehyun', shinjiro: 'Shinjiro', aigis: 'Aigis', ken: 'Ken', yunjin: 'Yunjin',
      'jaesang-runners': 'Jaesang', 'solji-runners': 'Solji', 'taesang-strangers': 'Taejoon', 'miyeon-strangers': 'Miseon', 'kim-dad': 'Mr. Kim', 'kim-mom': 'Mrs. Kim' },
    scene: [
    { bg: 'eqx-oka-kitchen', music: 'joy' },
    // BG: oka-dining-room-morning — the long low dining room of the old house full of morning sun, screens open to the garden, the long table crowded with dishes and people on cushions down both sides.
    { n: "By seven the whole household had heard, and by half past it had come down the river street in twos and threes and sixes to see for itself, and by eight the long table at the boarding house was the most crowded it had been all summer, and Solar was sitting at the head of it, on a cushion, where the chair had been, between six parents who had all slept, between them, perhaps four hours, and all of whom had opinions about her breakfast." },
    { n: "That was the thing. That was the thing she'd remember about that morning when she remembered it later, after, on the nights when she could make herself remember anything from before. Not the fear. The breakfast." },
    { s: 'solji-runners', f: 'happy', t: "She'll have the egg whites. Just the whites. And fruit. She doesn't really eat in the morning, she just has a coffee and pretends, don't you, sweetheart. Black." },
    { s: 'miyeon-strangers', f: 'neutral', t: "Soup. She'll have soup. Something warm. She skips breakfast and then she's cold by eleven." },
    { s: 'kim-mom', f: 'neutral', t: "Fried egg on rice. Soft yolk. Ketchup. Don't look at me like that. She's eaten it every day since she was seven. Haven't you. Don't lie to me, I'm your mother." },
    { n: "All three of them looked at her. And then, slowly, at each other." },
    { n: "Solar sat at the head of the table with her hands in her lap and felt her face go hot to the ears, because the terrible thing, the thing she couldn't say, the thing every person at that table who'd lived with her in any life could see on her face, was that all three of them were right." },
    { n: "Egg whites and black coffee, at a marble counter on the Upper East Side, standing up, with her bag already on her shoulder. Soup, at a low table in a house on a hill, with her hands round the bowl to warm them and somebody's eyes on her to make sure she finished it. A fried egg on rice with ketchup in a steel-doored apartment, eaten out of the pan, before school, with her phone in her other hand. All of them. Every morning. In three different lives." },
    { n: "Mrs. Oka came out of the kitchen with a tray. On the tray was a bowl of soup, and a plate with an egg-white omelette and sliced peaches, and a cup of black coffee, and a bowl of rice with a fried egg on top, soft yolk, and ketchup. She set them down in front of Solar, one at a time, and folded her gloved hands." },
    { s: 'mrsoka', f: 'happy', t: "There we are. I know, I know. I couldn't decide either." },
    { n: "Nobody had told her. Solar looked at the tray and felt the skin on the back of her neck go tight." },
    { n: "Junpei, three places down, had a pen out and the betting book open on his knee under the table and was writing very fast." },
    { s: 'junpei', f: 'happy', t: "Okay, okay, okay, new page, new page. *Which Dad Wins.* I'm opening a book. Odds on, uh, Lee Senior Number One, Lee Senior Number Two, and Mister Kim. Categories. Breakfast, which is a tie, I'm calling it a tie, look at that tray—" },
    { s: 'yunjin', f: 'neutral', t: "Junpei. They can all hear you." },
    { s: 'junpei', f: 'surprised', t: "...They speak Japanese?" },
    { s: 'yunjin', f: 'neutral', t: "Everybody speaks everything here. You know that. You've known that since April." },
    { n: "Junpei looked up. Six parents were looking at him. Jaesang with his coffee halfway to his mouth and one eyebrow up, the way he looked at a junior associate who'd said something in a meeting. Taejoon with no expression at all. Mr. Kim with enormous interest." },
    { s: 'kim-dad', f: 'happy', t: "What are the odds on me?" },
    { s: 'junpei', f: 'flustered', t: "Uh. Uh, good! Good odds, sir. Great odds. You're the— you're the people's choice." },
    { s: 'kim-dad', f: 'happy', t: "I'll take that." },
    { s: 'kim-mom', f: 'neutral', t: "You will not take that." },
    { place: 'The Oka Boarding House · The Long Table', time: 'Morning', bg: 'eqx-oka-kitchen', music: 'joy', soft: true },
    { n: "Mitsuru did the introductions, because somebody had to and nobody else could have. She stood at the side of the table in a pressed blouse at eight in the morning as if she'd slept twelve hours and went round all six of them, formally, in three languages, explaining who she was, and where they were, and that the Group would see to everything, and that they were very welcome, and not one word of it was untrue and not one word of it explained anything, and all six of them listened to her with the expressions of people being given a tour of a building that was on fire." },
    { n: "Then she went round the household. All of it. Down the table. And the parents watched each name go past, and Solar watched the parents." },
    { n: "Taejoon, when Mitsuru got to Haechan, didn't wait for the name. He'd been looking at Haechan since the boy came in the door at half past seven with his hair still wet. He looked at him now down the length of the table and said one word, in Korean, not loud, the way you'd say it across a kitchen." },
    { s: 'taesang-strangers', f: 'neutral', t: "Son." },
    { n: "Haechan put his chopsticks down. Something went across his face, fast, and was put away." },
    { s: 'haechan', f: 'neutral', t: "...Abeonim." },
    { n: "Jaesang, two places along, put his coffee down too. He looked at Taejoon. He looked at Haechan. He looked at Taejoon again, a man in shirtsleeves he had met six hours ago at a table in the dark." },
    { s: 'jaesang-runners', f: 'neutral', t: "...Son?" },
    { s: 'taesang-strangers', f: 'neutral', t: "Mm." },
    { s: 'jaesang-runners', f: 'neutral', t: "That's the boy from the house with the Greek letters. I'm fairly sure that's the boy from the house with the Greek letters. Lee Donghyuck." },
    { s: 'haechan', f: 'neutral', t: "Mr. Lee. Sir. Good morning, sir." },
    { n: "He said it in perfect English. And then turned his head and said something to Taejoon in Korean that made Taejoon's mouth do something it almost never did, and Jaesang looked between them with the expression of a man realising there was a second meeting going on in the room in a language he spoke worse than he'd told anyone." },
    { s: 'haechan', f: 'neutral', t: "...Don't ask me which one of me's translating. I don't know either." },
    { n: "Mr. Kim, when Mitsuru got to Jungwon, didn't wait either. He half got up off his cushion, beaming, and reached across two people and the tray of pickles to grab Jungwon's hand and shake it." },
    { s: 'kim-dad', f: 'happy', t: "Jungwon-ah! There you are. You've lost weight. Are they feeding you? Look at him, he's lost weight. Honey, he's lost weight." },
    { s: 'jungwon', f: 'flustered', t: "...Good morning, Father. Mother. I've eaten. I eat. Thank you." },
    { n: "He'd called him *Father*. In the formal way. Out of habit, from a life two streets from the Kims' front door. And across the table, in shirtsleeves, very still, Taejoon had looked up at the sound of Jungwon's voice, and looked at him for a long, level moment, a different kind of look entirely, with a different kind of history in it; and Jungwon, feeling it, had gone pale, and then red, and then sat up very straight, and bowed his head to Taejoon too, lower, without a word, the way you bow to a man whose house you've stood in." },
    { n: "Two fathers. Two lives. One boy at a breakfast table holding both of them at once, not dropping either. Solar watched him do it and couldn't eat anything at all." },
    { n: "Mrs. Kim, when Mitsuru got to Jihoon, didn't get up. She didn't smile. She put her chopsticks down, side by side, very neatly, and looked down the table at him where he sat next to Cherry with his hood up, and said his name the way she'd have read it off a list of people who'd been called to the office." },
    { s: 'kim-mom', f: 'serious', t: "Park Jihoon." },
    { n: "Jihoon took his hood down. He got up off his cushion, all the way up, and bowed to her, from the waist, deep, the way he hadn't bowed to anyone since he was nine, and held it." },
    { s: 'jihoon', f: 'neutral', t: "...Good morning, Auntie. It's good to see you. You look well." },
    { s: 'kim-mom', f: 'serious', t: "Mm." },
    { n: "That was all. She picked up her chopsticks again. She didn't look at him for the rest of breakfast. She didn't need to; everybody at the table could feel her not looking at him. Cherry, beside him, kept her eyes on her bowl and her hand on his sleeve under the table, and Jihoon sat down again very slowly, as if the cushion might not be there." },
    { place: 'The Oka Boarding House · The Long Table', time: 'Morning', bg: 'eqx-oka-kitchen', music: 'eerie', soft: true },
    { n: "Mrs. Oka went round with the tea. She knew how they took it. All six. She hadn't asked. Black for Jaesang. Barley for Taejoon, very hot. Milk and two sugars for Mr. Kim, who said *how did you know* in delight and was told *oh, I just knew, I always know*. She stood behind each of them as she poured, close, and when she straightened up she let her gloved hand rest a moment on each mother's shoulder, the way you'd rest a hand on a daughter's." },
    { s: 'mrsoka', f: 'neutral', t: "Such a long way. Such a long way you've all come. For her." },
    { s: 'mrsoka', f: 'neutral', t: "You'll want to take her home, of course. Of course you will. Every mother does." },
    { n: "She said it softly, pouring Miseon's tea. Miseon's hand on her cup went still. Solji, across the table, looked up at Solar. Mrs. Kim, at the end, didn't look up, and her knuckles round her chopsticks went white." },
    { n: "Nobody said anything. Mrs. Oka didn't seem to need anybody to. She went back to the kitchen with the pot, humming." },
    { n: "Three men in dark suits came at nine. Mitsuru met them at the gate and brought them in and stood them at the end of the table, and they bowed together, three of them, in a row." },
    { s: 'mitsuru', f: 'neutral', t: "Mr. Ishida. Mr. Kubo. Mr. Sakai. From the Group. They'll be at the house. Day and night. Wherever you go in the town, one of them will be with you. They're very good. They've worked nights before; they know what nights are like here." },
    { n: "Ishida was the oldest, gray at the temples, with a face like a closed door and very kind eyes. Kubo was young, round-faced, with an earpiece that kept slipping; he pushed it back in twice during the bow. Sakai was tall and said nothing at all. They'd been, Mitsuru told Solar later, in the hall, in the Group's night unit, years ago, before any of this. Men who'd stayed awake when the town went green, and been paid not to talk about it. She'd picked them herself." },
    { n: "Mr. Kim offered Kubo a piece of toast. Kubo, who had been told very firmly not to accept anything from the families, looked at Ishida, and Ishida, after a moment, very slightly, nodded, and Kubo took the toast and ate it standing at attention by the door, and Mr. Kim looked enormously pleased." },
    { n: "Miseon, without asking, without a word, got up and poured Ishida a cup of tea and put it in his hand, and went back to her cushion; and Ishida stood holding it, and looked down at it for a long moment, and then at her, and bowed his head over it, very low, as if she'd done something much larger." },
    { n: "The tin was on the table by the rice. The cranes on its lid. Full. Solji had the lid off. She was holding one up, turning it in her fingers, delighted." },
    { s: 'solji-runners', f: 'happy', t: "These are wonderful. What on earth is in these? Jaesang, try one, they're— I've never had anything like it. What's in them?" },
    { s: 'mrsoka', f: 'happy', t: "Oh, it's the flour, dear. It's all in the flour." },
    { n: "Shinjiro was in the doorway. He'd come down with the dorm's twos and stood there the whole of breakfast with his hands in his pockets and hadn't come in, and Solar saw him now, watching Solji with the rice cake halfway to her mouth, and saw his face." },
    { choose: [
      { t: "(Take the tin. Say Ken's been wanting them.)", flag: 'eqx-tin-parents', then: [
        { n: "She got up and took the tin out from in front of Solji, lid and all, with a bright face, *sorry, sorry, I promised Ken, he's been asking all week*, and her mother laughed and let her, and put the one she was holding back in, a little puzzled, and wiped her fingers on her napkin." },
        { n: "Ken, at the far end of the table, who hadn't eaten anything soft since July, looked at the tin coming toward him in Solar's hands with total horror. She walked past him with it, out of the front room, into the hall, and Shinjiro was there and took it off her without a word, and that was the second tin of Mrs. Oka's he'd made disappear that month." },
        { n: "But Mr. Kim had already had one. And Taejoon. She'd seen them. She sat back down at the head of the table and couldn't stop seeing them." }
      ] },
      { t: "(Let it be. It's their first morning.)", then: [
        { n: "She let it be. It was their first morning. Solji ate the rice cake, and closed her eyes, and laughed, and passed the tin to Jaesang, who took one to be polite and then another, and it went round the table, to Taejoon, to Miseon, to the Kims, and everyone who'd ever lived with her in any life sat at the long table in the sun eating Mrs. Oka's rice cakes and saying how good they were, how *good*." },
        { n: "In the doorway Shinjiro turned round and went out into the hall, and Solar heard the front door, and his steps on the path, and then nothing, and she didn't eat anything else that morning, and nobody at the table noticed, because there was so much on her tray." }
      ] }
    ] },
    { n: "Aigis had been sitting at the far end of the table all breakfast with her hands in her lap, looking at Mrs. Oka." },
    { n: "Not openly. Aigis didn't do anything openly anymore. But Solar had seen her, every time the landlady passed behind the parents with the pot, go a fraction still, the way she went still on the dorm roof when she was counting heartbeats. She'd been given her exception. Any reading she liked. She'd come to breakfast to take it." },
    { n: "She didn't take it. At the end, when the plates were going, Solar caught her eye down the length of the table, and Aigis shook her head, very slightly." },
    { n: "Later, on the walk back up the hill, in their twos, she said why, without being asked." },
    { s: 'aigis', f: 'neutral', t: "There were forty-three heartbeats in that room. Forty-four with Koromaru on the step. The parents' were very fast. Everyone's was very fast. It is very loud in that house when it is full." },
    { s: 'aigis', f: 'serious', t: "I could not find hers. I could not separate it. I would like to take it when there are fewer people. I would like to take it when she is close to me, and there is nobody else near her, and nothing to hold in my hands." }
  ] },

  { id: 'eqx-three-dads', date: '8/28', slot: 'after', consumes: true, title: 'which dad wins', place: 'Iwatodai Station · Konbini', time: 'Daytime',
    cast: { solar: 'Solar', haechan: 'Haechan', junpei: 'Junpei', 'jaesang-runners': 'Jaesang', 'taesang-strangers': 'Taejoon', 'kim-dad': 'Mr. Kim', jungwon: 'Jungwon', jihoon: 'Jihoon', akihiko: 'Akihiko', minji: 'Minji', shinjiro: 'Shinjiro' },
    scene: [
    { bg: 'shopping-street', music: 'joy' },
    // BG: eqx-konbini-day — the bright inside of a Japanese convenience store by a station on a summer afternoon, shelves of onigiri and drinks, a till with a bored clerk, three middle-aged men in very different clothes standing in the aisle.
    { n: "It was Haechan's idea, in the sense that it was Haechan who was standing nearest the door when the three fathers came out of the boarding house gate on Saturday afternoon looking for something to do with their hands, and Haechan who said, without thinking, *you guys want to see a konbini?*, and Haechan who then had to take them." },
    { n: "He took Solar, because twos, and because he'd looked at her across the garden with an expression of mute pleading so complete that she'd put her shoes on before he finished it. Ishida came too, ten steps behind, in his dark suit in the heat, as if he happened to be going the same way." },
    { n: "The konbini by the station was the size of a large closet and the temperature of a refrigerator and Taejoon stood in the doorway of it, in his shirtsleeves, with the automatic door trying to close on his shoulder and opening again, and looked at the aisles the way he'd have looked at a room with too many exits." },
    { s: 'haechan', f: 'neutral', t: "It's just a shop, Abeonim. It's like the one at the bottom of the hill. It's just a shop that never shuts." },
    { s: 'taesang-strangers', f: 'neutral', t: "...Never?" },
    { s: 'haechan', f: 'happy', t: "Never. Twenty-four hours. Christmas. Typhoons. You can come in at four in the morning and buy a sandwich and a phone charger and pay your gas bill." },
    { n: "Taejoon looked at him. Then at the shop. Then, slowly, with the deep seriousness of a man being given intelligence about the enemy's position, he went in." },
    { n: "He went down every aisle. All of them. In order. He picked things up and put them back exactly where they'd come from, label facing out. He stood in front of the rice balls for four minutes. He picked one up, a salmon one, in its triangle of plastic film, and turned it over, and looked at the little numbered tabs, *1, 2, 3*, and the arrows, and Solar watched her father, who in another life had a reputation she would not think about in a konbini, try to open a rice ball and tear the seaweed in half." },
    { s: 'taesang-strangers', f: 'neutral', t: "..." },
    { s: 'haechan', f: 'neutral', t: "You pull the middle one first. Down. Then the sides. One, then two. The seaweed's in its own little— it's in its own sleeve. It's so it stays crispy. It's actually genius." },
    { n: "Taejoon looked at the ruined rice ball. He put it in the basket Haechan was holding. He picked up another one, the same kind, and held it out to Haechan, and waited, his face perfectly blank, and Haechan showed him, slowly, one tab, then two, then three; and Taejoon watched, and nodded, and took a third rice ball off the shelf, and did it himself, all three tabs, in order, and the seaweed came out perfect round the rice, and he stood holding it in the cold air of the konbini looking at it as if he'd defused something." },
    { n: "Mr. Kim, meanwhile, had found the Kit Kats." },
    { n: "There were eleven flavors. Matcha and strawberry and sake and wasabi and sweet potato and something purple. He had one of each in his arms, and was going back for the second rows, the seasonal ones, with the dedication of a man on a mission from God." },
    { s: 'kim-dad', f: 'happy', t: "Wasabi! Solar-ya. Wasabi Kit Kat. Your mother is going to hate this so much." },
    { n: "Jaesang had picked up a bottle of water and stood at the till with it, and taken out his wallet, and taken out a black card, and handed it to the clerk, who was nineteen and had dyed hair and looked at the card, and at Jaesang, and ran it, and handed it back." },
    { n: "It hadn't worked. It would never work. It belonged to a bank in a city that wasn't here. Jaesang looked at the card in his hand for a long moment, a man who had never in his adult life been handed a card back; and then Ishida was there at his elbow, from nowhere, in his dark suit, with a Kirijo card, and paid for the water, and Mr. Kim's eleven Kit Kats, and the four rice balls, and a phone charger nobody had asked for, and stepped back ten paces, and was a man waiting for a bus." },
    { s: 'jaesang-runners', f: 'neutral', t: "...Thank you." },
    { n: "Ishida bowed. Jaesang, after a second, a little stiffly, a little late, bowed back. Solar had never once seen her father bow to anyone." },
    { place: 'Iwatodai Station · Bench', time: 'Daytime', bg: 'iwatodai-station', music: 'joy', soft: true },
    { n: "They sat on the bench outside the station afterward, all five of them in a row in the heat, three fathers and two children, with rice balls and Kit Kats and a bottle of water, the trains going over, and it was so ordinary that Solar forgot, for nearly ten minutes, to be afraid of anything." },
    { n: "Then Mr. Kim took a small notebook out of his fleece pocket. A small notebook with a stiff cover. With *WHO GETS CAUGHT FIRST: SEASON TWO* on it in marker, and, underneath, newer, in different marker, *WHICH DAD WINS.*" },
    { s: 'solar', f: 'surprised', t: "...Where did you get that." },
    { s: 'kim-dad', f: 'happy', t: "The funny boy with the hat. Junpei! Lovely boy. He lent it to me for the weekend. He said I had good odds. He said I should *study the form*." },
    { s: 'kim-dad', f: 'neutral', t: "So. I've studied the form. And I have some questions." },
    { n: "Jaesang leaned over to look. Taejoon, on the end of the bench, with his perfect rice ball, didn't lean over; he didn't have to. He was sitting very still in the way that meant he was listening to every word." },
    { n: "Haechan, on Solar's other side, had gone completely silent, and was looking at the trains with the fixed attention of a man who would rather be under one." },
    dating('haechan', [
      { s: 'kim-dad', f: 'neutral', t: "Page four. It says here, and I'm reading, *Lee Haechan: SEEN. Roof. Do not ask him about the roof. He will not tell you about the roof. Two to one.*" },
      { s: 'kim-dad', f: 'surprised', t: "...Two to one on *what*?" },
      { n: "Three fathers turned to look at Haechan. Simultaneously. Like a firing squad, if a firing squad had three different reasons." },
      { s: 'jaesang-runners', f: 'neutral', t: "The roof." },
      { s: 'taesang-strangers', f: 'neutral', t: "Mm." },
      { s: 'jaesang-runners', f: 'neutral', t: "...What does *mm* mean? Does *mm* mean you knew? Did you know about a roof?" },
      { s: 'taesang-strangers', f: 'neutral', t: "He's been in my house since he was a boy. I know about every roof." },
      { s: 'haechan', f: 'flustered', t: "There was no— it was a roof, it was a normal roof, sir, sirs, it's a dorm, it has a roof, everybody goes on the roof—" },
      { s: 'jaesang-runners', f: 'serious', t: "In my life, young man, you are the boy from the house with the Greek letters. I have a file. I'd like to know which file I'm supposed to be using." },
      { s: 'haechan', f: 'neutral', t: "...Both, sir. Honestly? Both. I'm sorry. I'm really sorry. It's both." },
      { n: "Jaesang looked at him for a long time. Taejoon looked at Jaesang looking at him. Then Taejoon, very slowly, took the second rice ball out of the bag, the one he'd opened perfectly himself, and held it out along the bench, past Solar, to Haechan, without a word." },
      { n: "Haechan took it. He held it in both hands. He didn't eat it. He sat holding it as if it were something considerably heavier than a rice ball, and Jaesang watched the whole exchange with the expression of a man who's just been outvoted in a language he doesn't speak." }
    ]),
    dating('jungwon', [
      { s: 'kim-dad', f: 'neutral', t: "Here. Page six. *Yang Jungwon: council room door, twice, minimum. Evens.*" },
      { s: 'kim-dad', f: 'happy', t: "Well, that's no surprise. That's not news. That's Jungwon. Jungwon's ours. He's been ours since middle school. He fixed our router." },
      { n: "On the end of the bench, Taejoon turned his head. Slowly. And looked at Mr. Kim, a man in a fleece with a Kit Kat in his hand, who had just said *ours* about a boy who had stood in Taejoon's front hall with his shoes off on more nights than Taejoon would ever say out loud." },
      { s: 'taesang-strangers', f: 'neutral', t: "...Yours." },
      { s: 'kim-dad', f: 'neutral', t: "Well— ours. You know. He's practically— he's around a lot. He's a good boy. Very polite. He's always eating at ours." },
      { s: 'taesang-strangers', f: 'neutral', t: "He eats at mine." },
      { n: "They looked at each other along the bench, the man in the fleece and the man in the shirtsleeves, two fathers of one girl who had each, in a different life, made room at their table for the same boy, and Solar sat between them and felt something enormous and unsayable go past over her head, back and forth, like a ball over a net." },
      { s: 'kim-dad', f: 'happy', t: "...Well. He can eat at both. He's lost weight." },
      { s: 'taesang-strangers', f: 'neutral', t: "Mm." },
      { n: "And that was that. A treaty, signed on a bench, with a Kit Kat. Jaesang looked between them with the face of a man who'd missed the entire meeting." }
    ]),
    dating('jihoon', [
      { s: 'kim-dad', f: 'neutral', t: "And— hm. Page nine. *Park Jihoon: arcade, photo booth, the roof of the guesthouse, nobody knows anything, nobody saw anything, Cherry's counting. Long odds. LONG.*" },
      { n: "Mr. Kim stopped reading. He looked at the page for a long time. He closed the book on his finger. When he spoke again his voice was very different, quiet and careful, the voice of a man who'd known a boy since the boy was in short trousers and taught her to play crane games at the old mall." },
      { s: 'kim-dad', f: 'neutral', t: "...Does your mother know?" },
      { s: 'solar', f: 'neutral', t: "There's nothing to know." },
      { s: 'kim-dad', f: 'neutral', t: "She knows. Your mother always knows. She knew at breakfast. You saw her face." },
      { s: 'kim-dad', f: 'sad', t: "Sweetheart, I'm not going to say anything. I've never said anything. I'm the one who doesn't say anything, that's my whole job. I just— he's a sweet boy. He was always a sweet boy. He used to bring you the prizes. I just don't want anybody to get hurt." },
      { n: "Jaesang, leaning over the book, read the line and looked at Solar with an expression she'd seen on his face in another life over a newspaper, and said nothing. Taejoon, on the end, didn't need to read it; he'd watched Mrs. Kim not look at Jihoon all through breakfast, and he was a man who knew exactly what it meant when a mother didn't look at somebody." }
    ]),
    dating('akihiko', [
      { s: 'kim-dad', f: 'neutral', t: "And who's this. Page eleven. *Senpai: lamp post, pier, ask him about his split times and watch him go red. Rival odds.*" },
      { s: 'jaesang-runners', f: 'neutral', t: "...Senpai." },
      { s: 'solar', f: 'neutral', t: "Akihiko. He's— he was in the dorm. Last year. He's the one who runs." },
      { s: 'jaesang-runners', f: 'neutral', t: "The silver-haired boy. With the tape on his hand. Who stood up when we came in at breakfast and stayed standing until your mother sat down." },
      { s: 'jaesang-runners', f: 'neutral', t: "...Hm. Good posture." },
      { s: 'kim-dad', f: 'surprised', t: "He boxes, apparently. The funny boy says he boxes." },
      { s: 'taesang-strangers', f: 'neutral', t: "He watches the door. Every room. He sits where he can see the door." },
      { n: "Taejoon said it the way you'd say a boy had good handwriting. Jaesang looked at him. Mr. Kim looked at him. And all three fathers sat on the bench with the trains going over, considering, separately and in silence, a boy none of them had a file on, who stood up when their wives sat down and sat where he could see the door, and Solar would have given anything to be under a train." }
    ]),
    dating('minji', [
      { s: 'kim-dad', f: 'neutral', t: "Page twelve. *Minji: the camera's down. THE CAMERA'S DOWN. Nobody's ever seen the camera down.* What does that mean?" },
      { s: 'jaesang-runners', f: 'neutral', t: "Minji. The Kim girl. From school. In my life. She was at the house at Thanksgiving with a camera in my soup." },
      { s: 'jaesang-runners', f: 'neutral', t: "...She put it down?" },
      { s: 'solar', f: 'neutral', t: "Sometimes." },
      { n: "Her father looked at her for a long moment, over the book, and she saw him do a calculation he'd never in his life expected to have to do, and come out the other side of it, and file it, and say nothing. Which was, she thought, the single most generous thing she'd ever seen him do." }
    ]),
    dating('shinjiro', [
      { s: 'kim-dad', f: 'neutral', t: "Page thirteen. Underlined. *Shinjiro-senpai: DO NOT BET ON THIS. I MEAN IT. He knows where I sleep.*" },
      { s: 'taesang-strangers', f: 'neutral', t: "...The one in the coat. In the doorway. Who wouldn't come in." },
      { s: 'taesang-strangers', f: 'neutral', t: "He took the tin away." },
      { n: "Jaesang and Mr. Kim looked at him, puzzled. Taejoon didn't explain. He sat with his rice ball and nodded, once, very slightly, to himself, the way he'd have nodded about a man who'd done a thing in his house that needed doing without being asked." }
    ]),
    nobody([
      { s: 'kim-dad', f: 'neutral', t: "...Hm. There's a lot of pages here. And your name's on all of them. And there's nothing under it. Not one." },
      { s: 'kim-dad', f: 'happy', t: "He's very thorough, the funny boy. He's even got a page called *literally anyone, please*." },
      { n: "Taejoon, on the end of the bench, let out a breath so long and so quiet that only Solar heard it. Jaesang looked faintly suspicious, the way he looked at any set of accounts that came out too clean. Mr. Kim closed the book, beaming." },
      { s: 'kim-dad', f: 'happy', t: "Well. I'm calling that a win. That's a win for all of us. That's a three-way tie." }
    ]),
    { n: "A train went over. The bench shook. Mr. Kim offered the wasabi Kit Kat round, and Jaesang took one to be polite and made a face like a man being shot, and Haechan laughed so hard that he had to put his head between his knees, and Taejoon, on the end, very slowly, unwrapped a second Kit Kat by its little tab, perfectly, and ate it." },
    { n: "Ishida, ten paces off, waiting for a bus that wasn't coming, was smiling. Solar saw him. He put it away the moment he saw her see." }
  ] },

  { id: 'eqx-surname', date: '9/1', slot: 'after', consumes: true, title: 'the surname box', place: 'Gekkoukan High · Faculty Office', time: 'After School',
    cast: { solar: 'Solar', mitsuru: 'Mitsuru', 'jaesang-runners': 'Jaesang', 'taesang-strangers': 'Taejoon', 'kim-dad': 'Mr. Kim', 'solji-runners': 'Solji', 'miyeon-strangers': 'Miseon', 'kim-mom': 'Mrs. Kim', teacher: 'Homeroom Teacher', rio: 'Rio', saori: 'Saori' },
    scene: [
    { bg: 'gekkoukan-classroom-evening', music: 'school' },
    // BG: eqx-faculty-office — a Japanese high school faculty office after hours, rows of cluttered teachers' desks, a single form under a desk lamp, three middle-aged men crowded round one desk.
    { n: "The second term started on a Wednesday, in a heat that hadn't heard about September. Solar walked through the gates at eight with Yukari and Junpei and Fuuka and Aigis like it was any first day, and sat at her desk in 3-F with the window open and the cicadas going, and the homeroom teacher with his glasses on a cord read the register, and got to her, and said *and, ah*, and looked at the box, and went on." },
    { n: "It was, in its way, a good morning. Ken had eaten a bowl of rice at breakfast. Soft rice, Shinjiro's, the first soft thing since July; he'd looked at it for a long time and then eaten it, all of it, steadily, and Shinjiro, at the stove, had pretended very hard not to be watching, and had burned the toast he was making in case." },
    { n: "At four, the fathers came." },
    { n: "Mitsuru had warned her at lunch, by text, in a single line: *They've asked to see your enrollment. All three. I said I'd arrange it. I couldn't think of a reason not to.* And then, a minute later: *I've thought of several since. Too late.*" },
    { n: "They came through the school gates at four in a group, with Mitsuru in front and the mothers behind and Kubo trailing in his dark suit with his earpiece in his hand, and every student still in the courtyard turned to watch six foreign parents in their good clothes cross the paving past the well, which none of them looked at." },
    { n: "Rio and Saori were on the bench by the well. They watched the parents go past. Saori had her gray notebook open on her knee. Rio, when Solar passed, caught her eye and lifted her chin at the six of them, *yours?*, and Solar, after a second, nodded, and Rio's face did something complicated and soft." },
    { s: 'rio', f: 'neutral', t: "...All of them?" },
    { s: 'solar', f: 'neutral', t: "All of them." },
    { s: 'saori', f: 'neutral', t: "I'm writing that down." },
    { place: 'Gekkoukan High · Faculty Office', time: 'After School', bg: 'gekkoukan-classroom-evening', music: 'mystery', soft: true },
    { n: "The form was on the homeroom teacher's desk under the lamp. One sheet. Kirijo letterhead, the Group's seal, her photograph in the corner, the one from April, in which she looked like somebody who'd been told to look at a camera and hadn't been told why." },
    { n: "Name. *Solar.* Year. *3.* Class. *?* Date of birth: a June date, right. Address: the dorm. And the surname box. Empty. And at the bottom, *Guardian*, and a signature." },
    { n: "The three fathers bent over it. All at once, from three sides, three heads over one sheet of paper under one lamp, in a faculty office that smelled of chalk and instant coffee, while the teacher with the glasses stood by the window and looked deeply unhappy and Mitsuru stood by the door with her arms folded." },
    { s: 'jaesang-runners', f: 'neutral', t: "...Who signed as her guardian?" },
    { n: "Nobody answered." },
    { n: "The signature was in a hand none of them knew. Heavy. Pressed so hard into the paper that it had come through on the back; you could read it backward against the lamp. Looping, unreadable, a long line with a hook at the end like a claw on a branch. It didn't spell anything. It wasn't anybody's name." },
    { s: 'jaesang-runners', f: 'neutral', t: "Did you sign this?" },
    { s: 'kim-dad', f: 'neutral', t: "No." },
    { s: 'jaesang-runners', f: 'neutral', t: "Did you?" },
    { s: 'taesang-strangers', f: 'neutral', t: "No." },
    { s: 'jaesang-runners', f: 'neutral', t: "I didn't sign it." },
    { n: "They stood there. Three fathers. Looking at a signature on the line that said *guardian*, under their daughter's photograph, that none of them had made." },
    { s: 'mitsuru', f: 'neutral', t: "...Nobody did. Nobody we can find. I've tried since April. It was on the desk on the morning of the eighth. Nobody brought it." },
    { n: "Jaesang straightened up. He took his pen out of his inside pocket. The same pen. He uncapped it, the way he'd uncap it at the bottom of a contract, and bent over the form again, and put the nib to the surname box." },
    { s: 'jaesang-runners', f: 'neutral', t: "Well. That's easily fixed. Lee." },
    { n: "He wrote it. Or tried to. The nib touched the paper inside the box and the ink didn't go. It beaded. It sat on the paper in a little black bead, round and wet, like ink on wax, like water on a leaf. He drew the pen across. The ink went across the paper in a line of tiny round drops, not touching, not soaking in, and the paper under them stayed white." },
    { n: "He stopped. He looked at it. He tried again, harder, pressing, the way you'd press a pen that had dried. The beads gathered in the bottom of the box and sat there." },
    { n: "Taejoon took the pen out of his hand. Without asking. Jaesang let him. Taejoon bent over the box, and wrote it, slowly, carefully, the single character, in Korean." },
    { s: 'taesang-strangers', f: 'neutral', t: "Lee." },
    { n: "The same. The ink beaded. It sat on the paper in a little cluster of black drops in the shape of a character, not touching the page at all, and when he breathed out over it they shivered." },
    { n: "Jaesang and Taejoon looked at each other over the form. *Lee*, and *Lee*. Two men with the same name, who had both just tried to give it to her, and been refused." },
    { s: 'kim-dad', f: 'neutral', t: "...My turn." },
    { n: "Mr. Kim took the pen. He wrote *Kim* in the box, in big confident letters, the way he'd have signed a birthday card. It beaded. All of it. The three names lay in the bottom of the empty box in little black drops, one on top of the other, *Lee* and *Lee* and *Kim*, none of them on the paper, all of them sitting there, waiting, like guests at a door nobody had opened." },
    // CG: eqx-surname-box — a school enrollment form under a desk lamp, a small photograph in its corner, the surname box empty but for beads of black ink sitting on the paper's surface in three clusters, a fountain pen lying across it, three men's hands at the edges of the frame.
    { n: "Nobody said anything for a long time. The teacher with the glasses had come away from the window and was looking at the form over Mr. Kim's shoulder with his mouth open." },
    { n: "Then Mrs. Kim came in from the corridor, where the mothers had been waiting, and looked at the three of them crowded round the desk, and at the form, and at the beads of ink, and said, in a voice of total exhaustion with the male sex:" },
    { s: 'kim-mom', f: 'serious', t: "What did you do." },
    { s: 'kim-dad', f: 'flustered', t: "We didn't do anything! It won't— honey, it won't take it. The ink. It won't take any of us." },
    { n: "Mrs. Kim looked at the form. Solji and Miseon had come in behind her; they looked too. Solji put her hand to her mouth. Miseon didn't do anything at all, except that her thumb went to the ring on her right hand and turned it, once, all the way round." },
    { n: "Mrs. Kim held her hand out for the pen. Mr. Kim gave it to her. She didn't bend over the form. She held the pen out, past all of them, across the desk, to her daughter." },
    { s: 'kim-mom', f: 'neutral', t: "...You do it." },
    { choose: [
      { t: "(Take the pen. Leave the box empty.)", flag: 'eqx-box-empty', then: [
        { n: "She took the pen. She looked at the box, at the three names sitting in it in beads, refused. She thought about it. Lee. Lee. Kim. Every one of them was hers. Every one of them was true." },
        { n: "She capped the pen and gave it back to her father, who took it without a word, and she left the box empty, and something in the room let out a breath; she felt it on the back of her neck, warm and close, like somebody standing too near behind her who'd been waiting to see which she'd pick, and was disappointed, and was patient." },
        { s: 'solar', f: 'neutral', t: "It's fine. It's been empty since April. It can stay empty a bit longer." },
        { n: "Mitsuru, by the door, unfolded her arms." }
      ] },
      { t: "(Write it yourself. All three.)", then: [
        { n: "She took the pen. She bent over the box under the lamp with six parents watching her and wrote all three in it, small, one above the other, *Lee* and *이* and *김*, and the ink beaded, all of it, every stroke, and sat on the paper in tiny black drops and wouldn't go in." },
        { n: "She stood looking at it. Her own hand. Refused." },
        { n: "Behind her, very softly, so softly she'd never be sure afterward that it had been in the room and not in her own head, somebody laughed. Not unkindly. Fondly. The way you laugh at a child who's tried to lift something far too heavy for her." }
      ] }
    ] },
    { n: "The teacher with the glasses took the form, in the end, by the corner, with two fingers, and put it in the drawer of his desk, and locked the drawer, and put the key on the cord round his neck with his glasses, and said, to nobody, *and, ah*, and went home." },
    { n: "On the walk back across the courtyard the mothers went first, together, ahead of the fathers, three women who'd met six days ago walking arm in arm across a school courtyard in a country none of them had chosen, talking low. Solar couldn't hear what about. She watched them pass the well. Solji looked at it. Miseon didn't. Mrs. Kim stopped, and looked at the plank lid, and the sign, *Maintenance. Do not lean.*, and then looked up, across the courtyard, at Solar." },
    { s: 'kim-mom', f: 'neutral', t: "...Don't you lean on that." },
    { s: 'solar', f: 'neutral', t: "I don't." },
    { s: 'kim-mom', f: 'serious', t: "I know you. You'll lean on it. Don't." }
  ] },

  { id: 'eqx-moon-ask', date: '9/11', slot: 'evening', consumes: true, title: 'one more day', place: 'The Oka Boarding House · The Long Table', time: 'Evening',
    cast: { solar: 'Solar', mrsoka: 'Mrs. Oka', hayashi: 'Mr. Hayashi', arai: 'Mrs. Arai', 'solji-runners': 'Solji', 'miyeon-strangers': 'Miseon', 'kim-mom': 'Mrs. Kim', 'kim-dad': 'Mr. Kim', danielle: 'Danielle', aigis: 'Aigis', haechan: 'Haechan', kazuha: 'Kazuha' },
    scene: [
    { bg: 'eqx-oka-kitchen', music: 'tender' },
    { n: "By the second Saturday of September the long table was full every night, and it wasn't only them anymore." },
    { n: "The six old men from the pier came at four, as they had all summer, and sat at the kitchen end in their caps and ate like boys. Mr. Hayashi had put on weight. He said so, proudly, patting it, like Nozomi had. Mrs. Arai from the third house at the bottom of the dorm's street came at five now, in her good cardigan, with a little covered dish of her own pickles for the table every time, and sat by Kazuha, whom she'd decided was her granddaughter, and told her about her son, who came home late." },
    { s: 'arai', f: 'neutral', t: "He's always late. He works so hard. But he'll be home soon. Mrs. Oka says. She says, *Arai-san, you just stay here where it's warm, and when he comes, we'll know*. Isn't she kind. Isn't she the kindest woman." },
    { n: "Kazuha held her hand and said *yes*, and looked at Solar over the old woman's head with her face doing nothing at all." },
    { n: "There were others. People Solar half-knew from the town. The woman from the flower shop. A salaryman from the Strip who'd lost his job in June and came every night in his suit. And at the corner of the table nearest the garden, a couple Solar knew from last year, from the bookshop at the bottom of the Strip, the old man with the round glasses and his wife with her hair in a bun; Bunkichi and Mitsuko, who sold her a novel once and talked about their son, who'd been a teacher, who'd died." },
    { n: "Bunkichi didn't remember her. Nobody in the town remembered her. He beamed at her across the table anyway, the way he beamed at everyone, and passed her the pickles." },
    { n: "Mrs. Oka came round behind him with the rice. She stopped, and put her gloved hand on his shoulder, and bent down to him, the way she bent to everyone, close, warm." },
    { s: 'mrsoka', f: 'neutral', t: "You'll stay one more day, won't you, Bunkichi-san. Just one more. You never know who might come to the door. On a night like this. With the moon getting big." },
    { n: "The old man looked up at her. And something came into his face, very soft, very far away; the look of a man who'd spent years waiting at a bookshop door for somebody who wasn't going to come home from work." },
    { n: "*One more day*, he said. *Yes. Yes, all right. One more day. Why not.*" },
    { n: "Mitsuko, beside him, took his hand under the table. Solar saw her do it. Her face was smiling and her knuckles were white." },
    { place: 'The Oka Boarding House · The Long Table', time: 'Evening', bg: 'eqx-oka-kitchen', music: 'eerie', soft: true },
    { n: "The mothers helped serve now. That had started on the third day, the way it always starts: Miseon getting up without a word to carry a pot, and then Solji, who couldn't sit still while someone else worked, and then Mrs. Kim, who couldn't stand to be the only one sitting. Mrs. Oka let them. She was delighted. She gave them aprons; they hung on hooks by the kitchen door, white, three of them, new." },
    { n: "Solar watched her mothers go up and down the long table with dishes in their hands in Mrs. Oka's aprons, feeding the town, and couldn't have said what it was in her chest." },
    { n: "Mrs. Oka stopped at the head of the table, by Solar's cushion. She didn't sit. She never sat. She stood with the rice pot against her hip and looked down the length of the room, at all of it, the crowded table and the lamp and the faces and the mothers in her aprons, the way you'd look at a garden you'd planted, and then she looked down at Solar." },
    { s: 'mrsoka', f: 'happy', t: "Look at it. Isn't it lovely. Everyone at one table. I always wanted a big table." },
    { s: 'mrsoka', f: 'neutral', t: "It's the harvest moon on the twenty-third. Did you know? The big one. On the equinox. It hardly ever falls on the equinox; I've only seen it twice. Day and night the same length, and the biggest moon of the year." },
    { s: 'mrsoka', f: 'neutral', t: "We'll have a moon-viewing. All of us. Down by the sea, at the park, where you can see it come up out of the water; I'll do the dango. A hundred dango. Your mothers will help me. Won't you stay for the moon, Solar-chan? All of you. Every one. Stay for the moon." },
    { n: "Down the table, every head turned. Forty faces in the lamp light. The mothers, with the dishes in their hands. Haechan, halfway through a bowl of rice, very still. And in the garden doorway, on the step, Koromaru, standing up." },
    { choose: [
      { t: "We'll stay for the moon. Of course we will.", tally: { cakes: 1, 'asks.solar.moon': 'yes' }, flag: 'eqx-moon-stayed', then: [
        { n: "She said it, and the whole table breathed out. She heard it. Forty people letting go of a breath they hadn't known they were holding, the way a room does when the girl at the center of it says the right thing. Somebody clapped. Mr. Kim. Then the old men from the pier, banging the table." },
        { n: "Mrs. Oka put her gloved hand on Solar's head, lightly, just for a moment. The four small hard points of the fingertips through the cotton, on her scalp." },
        { s: 'mrsoka', f: 'happy', t: "Good girl." },
        { n: "Solar felt it go. The small warm thing from under her ribs. Out of her, into the room, into the lamp light, gone. She couldn't have said where. She only knew that the rice in her bowl, when she looked down at it, smelled better than any rice she'd ever smelled in her life, sweet at the back, and she wanted it so badly that her mouth ached, and she put her chopsticks down." }
      ] },
      { t: "I'll come if I'm free.", tally: { 'asks.solar.moon': 'no' }, then: [
        { n: "It came out lighter than she meant, almost rude, and she watched it land: a flicker on Mrs. Oka's face, there and gone, the way a lamp flickers when somebody opens a door somewhere else in the house. The room went a degree colder. Nobody noticed but her. And Koromaru, on the step, who lay back down." },
        { s: 'mrsoka', f: 'neutral', t: "...Of course, child. Of course. If you're free. I'll keep you a place." },
        { n: "She went back down the table with the pot, humming. And at the head of the table, at Solar's elbow, in the space beside her cushion where nobody was sitting, there was a bowl Solar hadn't seen put down, full, with chopsticks laid across it." }
      ] },
      { t: "Everyone can decide that for themselves.", tally: { choose: 1, 'asks.solar.moon': 'choose' }, flag: 'eqx-moon-mine', then: [
        { n: "Mrs. Oka went still. Completely still, the pot against her hip, the way a cat goes still at a window. For one second the lamp light seemed to sit on her very heavily, and her face didn't do anything at all." },
        { s: 'mrsoka', f: 'happy', t: "...Isn't that a lovely thing to be able to say. Everyone for themselves." },
        { s: 'mrsoka', f: 'neutral', t: "Then I'll ask them each. Myself. That's only fair, isn't it." },
        { n: "She smiled down at Solar, and went down the table with the pot, and stopped behind each mother as she passed, and bent, and said something low into each one's ear; and each of them, Solji, Miseon, Mrs. Kim, looked up at her, startled, and then smiled, and nodded. *Of course. Of course we will. We'd love to.*" },
        { n: "Solar watched it happen down the length of the table, three times, and couldn't do anything about it, and understood, with her whole body, that that was the point." }
      ] }
    ] },
    { n: "Danielle was on the street. Solar saw her through the window when she went out to the gate for air: across the river street, on the far pavement, under the lamp, leaning on the wall with her phone in her hand, the way she'd been on the street outside every place this town ate in all summer, never coming in. She lifted her chin at Solar. Solar crossed to her." },
    { s: 'danielle', f: 'neutral', t: "I've stopped writing names. There's no point. It's everybody." },
    { s: 'danielle', f: 'neutral', t: "I write the ones who say no now. It's a shorter list." },
    { n: "She held the phone up. One screen. Eleven names on it, since April. Solar read them under the lamp. Her own was on it, once, from June. Shinjiro's, twice. Koromaru's, with a dog emoji, every single day." },
    { s: 'danielle', f: 'neutral', t: "...Your mothers aren't on it. None of them. Not once. I've been watching since the twenty-sixth." },
    { n: "She put the phone away. She didn't say anything else; that was the thing about Danielle, she never said the second thing. She just looked at Solar across a meter of hot pavement with an expression that, on anybody else, Solar would have called pity, and then went back to watching the window." },
    { n: "Inside, through the glass, in the lamp light, the three mothers were laughing at something together at the kitchen door, in Mrs. Oka's aprons, with the persimmon tree black against the last of the light behind them." },
    { n: "Akihiko texted the hour at one. *66:31.* And then: *it went up eight seconds tonight. Eight. Nobody died. I checked. I called round. Everybody's alive.* And then: *so what got fed.*" }
  ] },

  { id: 'eqx-hanne-page', date: '9/20', slot: 'late', consumes: true, title: 'a page come back', place: 'The Velvet Room', time: 'Late Night',
    cast: { solar: 'Solar', elizabeth: 'Elizabeth', theodore: 'Theodore' },
    scene: [
    { bg: 'velvetroom-1', music: 'velvet' },
    { n: "The blue card was under her door at ten. Elizabeth's hand, the old elegant one, not the heavy one. Four words. *Please come. Bring nothing.*" },
    { n: "She went to sleep and woke in the blue." },
    { n: "It was the Room as it always was, the velvet and the long table and the low lamps and the endless quiet, and it wasn't, because Elizabeth wasn't sitting. She was standing by the door at the far end, the one with the line of gold light under it, with her back to it, as she'd stood every time Solar had come this year; and there was a second figure in the Room, by the shelves, in the same blue, tall and fair and very upright, with a book held open on one gloved palm." },
    { s: 'theodore', f: 'happy', t: "Ah. Good evening. You'll be Solar. I've heard a very great deal. I'm Theodore. I mind things, when my sister's minding something else." },
    { s: 'theodore', f: 'flustered', t: "Would you like tea? I've been practising. I've been told I'm heavy-handed with doors, but I'm reliably told I'm quite good with a pot." },
    { s: 'elizabeth', f: 'neutral', t: "He is. It's very annoying. Sit, please. Theo, the book." },
    { n: "Theodore brought it. The great book, bound in blue, that Elizabeth had laid open in front of her in April with Solar's page full of other people's handwriting. He set it down on the table in front of Solar carefully, as if it might wake, and opened it, not at her page. Further on. Further back. A page Solar had never been shown." },
    { s: 'elizabeth', f: 'neutral', t: "This page has been empty since the sixth of March of last year. I closed it myself. I held a door for its owner and she went through it and I watched it shut, and the page went blank, as they do, when someone goes home." },
    { s: 'elizabeth', f: 'serious', t: "It came back on Tuesday. The sixteenth of August. At about the time, I believe, that a great many paper lanterns came back up a river." },
    { n: "There was writing on it. Not much. A name at the top, in a hand Solar didn't know, small and slanting, a musician's hand, the hand of somebody who'd written their name in the corner of a great many sheets of music: *Hanne*." },
    { n: "And under it, filling the rest of the page, line after line, pressed so hard into the paper that the page had puckered and torn in two places, in the heavy hand, the fourth one, the one from Solar's page and the enrollment form and the ward's sign-in book, one word. Over and over and over, down the whole page, the way a child writes lines." },
    { n: "*play play play play play play play play play play play*" },
    // CG: eqx-hanne-page — an open blue-bound book on a velvet table under a low lamp, one page with a small slanting name written at the top and, below it, a single word repeated in a heavy, pressed, tearing hand until the page has puckered.
    { n: "Solar put her hand on it. She didn't mean to. The paper was warm, and under her palm, very faintly, it was moving. Not the page. Something under the page. The way the skin on a wrist moves over a pulse." },
    { n: "It was keeping time." },
    { s: 'elizabeth', f: 'neutral', t: "You know her. Don't you. You said her name on a platform. You're the only one who ever said it. I wrote it down myself, that night. It was the last thing on this page that was in anyone's hand but hers." },
    { s: 'solar', f: 'neutral', t: "...She plays on the bridge. In the red. Since June. And in the daytime, once. And when she plays, the hour gets longer." },
    { s: 'elizabeth', f: 'serious', t: "Yes. She's on your side of the door. She shouldn't be able to be. I held that door. I held it rather a long time, I think. I wanted to be quite sure it had shut behind her." },
    { n: "She said it lightly. Her hands, folded in front of her apron, had gone very tight. Theodore, at the shelves, looked at his sister's hands and then very carefully at the book on his palm." },
    { s: 'elizabeth', f: 'neutral', t: "On the twenty-third, the night is the same length as the day. Every door is at its widest. Every one. The ones I'm holding. The ones I'm not. You'll feel it from the morning. Everything will feel a little ajar." },
    { s: 'elizabeth', f: 'serious', t: "Whoever is writing on this page has been very patient. I don't think they are going to be patient on the twenty-third." },
    { choose: [
      { t: "Can you close it? Her page?", then: [
        { s: 'elizabeth', f: 'sad', t: "It isn't mine to close. It's hers. I tried, on Tuesday. I put my hand flat on it to shut it and it shut and I took my hand away and it was open again, at the same place. Like a book somebody else is reading over your shoulder." },
        { s: 'elizabeth', f: 'neutral', t: "Somebody else is reading it. That's what frightens me. Somebody's holding it open." }
      ] },
      { t: "She isn't the one doing it. She's being made to.", then: [
        { s: 'elizabeth', f: 'neutral', t: "...Why do you say that?" },
        { s: 'solar', f: 'neutral', t: "Because when she stops playing, she looks at the river. Like she's waiting to be told off." },
        { n: "Elizabeth looked at her for a long time. Then down at the page. At the word, over and over. Her face did something it almost never did; it was, very briefly, frightened, and then it was put away." },
        { s: 'elizabeth', f: 'neutral', t: "Yes. That's what this hand writes like, isn't it. Like somebody telling a child to practise." }
      ] }
    ] },
    { n: "Theodore poured the tea. He'd been right; he was good with a pot. He put a cup in front of Solar and one at Elizabeth's empty chair, which she didn't sit in, and stood back with the pot in both hands, and cleared his throat." },
    { s: 'theodore', f: 'neutral', t: "If I may. I know I'm only minding things. But if there's ever a night you need someone at a door, I'm very good at standing in front of them. I've had a great deal of practice. It's practically the only thing we're for." },
    { s: 'theodore', f: 'happy', t: "I'd like to be useful to you. My sister talks about you constantly. It's quite tiresome. I'd like to see what the fuss is about." },
    { s: 'elizabeth', f: 'neutral', t: "Theo." },
    { s: 'theodore', f: 'happy', t: "Sorry. Sorry. Drink your tea." },
    { n: "She drank it. It was very good. The page lay open on the table between them the whole time, and under it, faint, steady, something kept time; and when Solar woke in her own bed in the dorm at two in the morning, she could still feel it in the palm of her hand, the way you feel a train for a while after you've got off." }
  ] },

  { id: 'eqx-songpyeon', date: '9/22', slot: 'after', consumes: true, title: 'half-moons', place: 'The Oka Boarding House · Kitchen', time: 'After School',
    cast: { solar: 'Solar', mrsoka: 'Mrs. Oka', 'solji-runners': 'Solji', 'miyeon-strangers': 'Miseon', 'kim-mom': 'Mrs. Kim', aigis: 'Aigis', yunjin: 'Yunjin' },
    scene: [
    { bg: 'eqx-oka-kitchen', music: 'tender' },
    { n: "It was Chuseok at home. Some homes. Two of them. Nobody here had a word for it; the town calendar said *Wednesday* and the school said *second term* and the dorm said *rota*, and in the boarding house kitchen, at four in the afternoon, three women from three lives and a landlady from this one were making songpyeon, because Miseon had said, on Monday, quietly, at the sink, that she'd never once in her life not made it, and Mrs. Oka had said *then you shan't start now*." },
    { n: "Solar came straight from school in her uniform. She'd been sent for. Mrs. Kim had texted her from a phone Mitsuru had given her that morning, the first text she'd ever sent on it, in capitals: *KITCHEN. NOW. YOUR MOTHERS ARE FIGHTING ABOUT PINE NEEDLES.*" },
    { n: "They weren't fighting. They were standing at the long counter shoulder to shoulder in Mrs. Oka's three white aprons with their sleeves pushed up and their hands in the same big wooden bowl of dough, rice dough, white and soft, pinching off pieces and rolling them in their palms and pressing their thumbs into them to make little cups, and arguing, in two languages, cheerfully, about everything." },
    { n: "Miseon in a hanbok. Solar hadn't seen her in one since a different autumn. Soft green, the jacket short, the long skirt tied high, the sleeves pinned back with two of Mrs. Oka's clothes pegs so they wouldn't go in the dough. She looked up when Solar came in and didn't smile, and her eyes went over Solar's face once, checking, the way they always had, *has she eaten, has she slept*, and went back to the dough, and her hands didn't stop." },
    { s: 'kim-mom', f: 'neutral', t: "Sesame. They're sesame inside. Honey and sesame. That's how you make them. Tell her." },
    { s: 'miyeon-strangers', f: 'neutral', t: "Chestnut. And beans. And sesame. All three. You make all three. So there's one for everyone." },
    { s: 'solji-runners', f: 'happy', t: "I bought them from a shop on 32nd Street every year. I'm learning. I'm learning! Look at mine. Mine's a disaster. Sweetheart, look at mine." },
    { n: "Hers was a disaster. A lopsided half-moon with a crack in it and sesame coming out of the crack. She held it up, laughing, and Mrs. Kim laughed, and Miseon looked at it and very nearly smiled, and reached over and took it out of Solji's palm and pinched the crack shut with two fingers, perfectly, in one movement, and gave it back, and Solji looked at it as if she'd been given a gift." },
    { n: "Mrs. Oka was at the stove with the steamer and the pine needles. The needles were for the steamer; you laid the half-moons on a bed of them and the steam came up through and the pine went into the rice. Somebody had brought a whole branch of them in from somewhere. The kitchen smelled like a forest after rain, and like sugar, and under it, at the back, faint, the other thing." },
    { s: 'mrsoka', f: 'happy', t: "Solar-chan. Wash your hands. Come and pinch. Your mothers have been telling me about you all afternoon." },
    { place: 'The Oka Boarding House · Kitchen', time: 'After School', bg: 'eqx-oka-kitchen', music: 'tender', soft: true },
    { n: "She washed her hands. She came and stood at the counter between them. And her mothers taught her to make songpyeon, all three of them at once, three different ways, in three languages, and she did all three, and they were all right." },
    { n: "Solji's way: carefully, frowning, getting it wrong, laughing. Mrs. Kim's way: fast, her thumb going into the dough like a stamp, a half-moon every four seconds, *don't fuss it, it's food, it's not jewelry*. Miseon's way: slow, without a word, her hands over Solar's hands, pressing Solar's fingers into the dough with her own, the ring cold on Solar's knuckle, folding the edge over, pinching it shut, a perfect small moon." },
    { n: "Somewhere in it, with their hands in the bowl, they started talking about the story." },
    { n: "Solar didn't know who started it. Mrs. Kim, maybe; she'd been saying that her mother had made songpyeon with her every year and told her stories while they did it, and that she'd done the same, and Solji said *oh, which ones*, and Mrs. Kim said *oh, you know, the usual. The sun and the moon.* And all three of them stopped, with their hands in the dough." },
    { s: 'solji-runners', f: 'surprised', t: "...The sun and the moon? The brother and sister? With the rope? I told her that. I told her that one every night for a year. It was the only one she'd go to sleep for." },
    { s: 'kim-mom', f: 'surprised', t: "So did I. Off a picture book. A big one, with the tiger on the cover. She used to make me do the voice." },
    { n: "They both looked at Miseon. Miseon's hands had gone still in the bowl." },
    { s: 'miyeon-strangers', f: 'neutral', t: "...With the lights off. She didn't like the light on. She liked it better in the dark. I'd sit on the floor by the bed." },
    { n: "The three of them looked at each other over the bowl. Three women, from three lives, who had each, at a bedside, in the dark or the lamp light or the light of a picture book, told the same little girl the same story." },
    { s: 'solji-runners', f: 'sad', t: "...I always stopped before the tiger. Did you? I always left it out. I'd say, the mother walked home over the hills, and then I'd skip to the rope. *And then the children climbed up and up and up.* She never noticed. Did you notice, sweetheart?" },
    { s: 'solar', f: 'neutral', t: "I noticed." },
    { s: 'kim-mom', f: 'neutral', t: "I did the tiger. All of it. I did it so well she cried. Every time. And then she'd make me do it again. *Do the door, Mom. Do the door.*" },
    { s: 'miyeon-strangers', f: 'neutral', t: "I stopped at the rope. Every night. I said, and then heaven let down a rope. And then I said, and that's enough for tonight. And turned the light off. She never asked what happened after." },
    { s: 'solar', f: 'neutral', t: "...I didn't want to know." },
    { n: "Miseon looked at her. Her hands in the dough. For a long time. And then, very slightly, so slightly that only Solar would have seen it, her face moved." },
    { n: "Mrs. Oka, at the stove, with her back to them, laid the last of the pine needles in the steamer, and began, softly, without turning round, to finish it for them." },
    { s: 'mrsoka', f: 'neutral', t: "*And on the last hill the tiger ate her all up. And it put on her clothes. And it put on her apron, and her headscarf. And it went down the hill to the little house where the children were waiting, and it knocked on the door. Twice. And it said—*" },
    { n: "She turned round. She was smiling. Her gloved hands were folded in front of her apron, white with flour, and the steam was coming up behind her off the stove in a soft white cloud, and she said it in a mother's voice. Any mother's. The kindest voice in the world." },
    { s: 'mrsoka', f: 'happy', t: "*Open the door. It's only me.*" },
    { n: "Solji laughed. A little too loud. Mrs. Kim laughed. Miseon didn't. Mrs. Oka laughed too, delighted, *oh, I always loved that part, I always did the voice*, and turned back to the steamer, and the three mothers stood with their hands in the dough and looked at each other and then, all at once, as if somebody had said *carry on*, went back to pinching moons." },
    { place: 'The Oka Boarding House · Kitchen Door', time: 'Evening', bg: 'eqx-oka-kitchen', music: 'eerie' },
    { n: "Aigis came at six. With Yunjin; twos. She stood in the kitchen doorway and didn't come in, and Mrs. Oka said *come in, come in, child, there's plenty*, and Aigis said *thank you, I will stand here*, and stood there." },
    { n: "Solar knew what she was doing. She'd known since the funeral hall. She watched Aigis's head tip very slightly to one side, the way it tipped on the dorm roof at midnight; and she watched her eyes, which didn't move, which were fixed on the counter, on the four women at it, the three mothers and the landlady, who'd come away from the stove now with the first steamer of finished moons and was standing among them, shoulder to shoulder, her gloved hands in the same bowl as theirs." },
    { n: "Four women at one counter, close as a family, all their hands in one bowl of white dough, in a cloud of steam and pine and flour so thick it hung in the air like snow in the lamp light." },
    { n: "It took Aigis a long time. Longer than it ever took her. Then she looked at Solar across the kitchen, and her face did the thing it had done on the morning of the twenty-seventh, holding a cup of tea. And she said it, low, in the doorway, to Solar, so that nobody at the counter could hear." },
    { s: 'aigis', f: 'serious', t: "...Forty." },
    { s: 'aigis', f: 'neutral', t: "Large. Warm-blooded. Resting heart rate forty. The same as the twelfth of April, at the third house, knocking. The same exactly." },
    { flag: 'eqx-aigis-forty' },
    { s: 'solar', f: 'neutral', t: "Who?" },
    { n: "Aigis didn't answer for a long moment." },
    { s: 'aigis', f: 'sad', t: "...I can't separate it. There are four of them at the counter. Their hands are in the same bowl. They're touching. The flour is in the air; it's in everything; it's on all their hands." },
    { s: 'aigis', f: 'serious', t: "It is one of the four women at that counter. I'm certain of that. I have never been more certain of a reading. I can't tell you which." },
    { n: "Solar looked at the counter. At the four of them. Solji laughing with sesame on her fingers. Mrs. Kim, fast and efficient, stamping out moons. Miseon in her green hanbok with her sleeves pegged back, silent, perfect, pinching shut. Mrs. Oka among them, in the middle, gloved, floured, humming." },
    { n: "Four women. Four mothers. All of them hers, or wanting to be. All of their hands white to the wrist." },
    { n: "Yunjin, behind Aigis in the doorway, had heard. Solar saw it go through her, saw her hand go to the frame and grip it. She didn't say anything. She looked at Miseon, at the counter, with an expression of naked, helpless dread, and then away." },
    { n: "Mrs. Oka turned round with a plate of moons, hot, glistening, the pine needles still stuck to their undersides." },
    { s: 'mrsoka', f: 'happy', t: "Here we are. The first ones. The first one's always for the youngest. That's you, Solar-chan." },
    { choose: [
      { t: "(Take the first one. Eat it.)", flag: 'eqx-songpyeon-ate', then: [
        { n: "She took it. She ate it, standing at the counter between her mothers, with all three of them watching her face the way they'd watched it at every table in every life, waiting to see if she liked it. It was the best thing she'd ever eaten. Sesame and honey and pine, and the rice soft as skin, and sweet at the back. Sweet in the wrong place." },
        { n: "All three of them smiled at once. The same smile. She'd never seen them smile the same smile before." }
      ] },
      { t: "(Take it. Put it in your pocket for later.)", then: [
        { n: "She took it and wrapped it in a napkin and put it in her uniform pocket, *for later, I just ate*, and Miseon's eyes went to the pocket and then to Solar's face, and something in them, briefly, was hurt, the way it had been hurt in another life every time Solar hadn't finished her soup. Solar felt it like a hand on her chest." },
        { n: "She threw it in the river on the way home. It didn't float. It went straight down, as if something had been waiting underneath to take it." }
      ] }
    ] },
    { n: "Walking back up the hill at seven, in twos, Aigis said one more thing. She said it to the road ahead of them, not to Solar." },
    { s: 'aigis', f: 'neutral', t: "I'm going to tell Mitsuru-san tonight. She asked to be told first. I'll tell her it was one of four. She'll ask me which four." },
    { s: 'aigis', f: 'sad', t: "...I would very much like to have been interrupted again." },
    { n: "Behind them, down the hill, in the boarding house kitchen, the three mothers were still at the counter. Solar could hear them, faint, through the open window, laughing at something, in two languages; and over the top of the laughing, tunelessly, happily, someone humming. Three up, two down, a long one." },
    { n: "She couldn't tell whose voice it was. That was the thing she'd remember. She'd lie awake that night trying to remember whose voice it had been, and couldn't, and it was the last night she'd ever have to wonder." }
  ] },

  { id: 'eqx-equinox', date: '9/23', slot: 'evening', consumes: true, title: 'day equals night', place: 'Port Island · Seaside Park', time: 'Evening',
    cast: { solar: 'Solar', mitsuru: 'Mitsuru', akihiko: 'Akihiko', haechan: 'Haechan', fuuka: 'Fuuka', chenle: 'Chenle', mrsoka: 'Mrs. Oka', ken: 'Ken', shinjiro: 'Shinjiro', junpei: 'Junpei', yukari: 'Yukari', hanni: 'Hanni', hyein: 'Hyein', yunjin: 'Yunjin', jaehyun: 'Jaehyun',
      'jaesang-runners': 'Jaesang', 'solji-runners': 'Solji', 'taesang-strangers': 'Taejoon', 'miyeon-strangers': 'Miseon', 'kim-dad': 'Mr. Kim', 'kim-mom': 'Mrs. Kim' },
    scene: [
    { bg: 'port-island-seaside-park-sunset', music: 'tender' },
    // BG: eqx-tsukimi — a seaside park on a man-made island at dusk on a September holiday, picnic blankets in a long row on the grass by the sea wall, trays of white round dumplings stacked in pyramids, pampas grass in vases, people in light jackets looking east over a flat calm sea.
    { n: "It was a holiday. That was the first thing everyone said that morning and the last thing anybody remembered about it: that it was a holiday, the autumn equinox, the day and the night the same length, and the sky was clear from end to end for the first time in a week, and Mitsuru looked at it from the dorm roof at seven in the morning and said *well*, the way she said it before an exam." },
    { n: "Elizabeth had been right. Everything felt ajar. All day. Doors that should have shut swung back a centimeter. The fridge in the dorm kitchen wouldn't stay closed. Hanni found the bell on Hyein's door handle ringing, softly, at noon, with the door shut and nobody near it, and stood in the hall looking at it for a long time, and then took it off and put it in her pocket where she could feel it." },
    { n: "Akihiko's number from the night before was *67:12*. He'd said it at breakfast and nobody had answered him." },
    { n: "They went down to Seaside Park at four anyway. All of them. Because Mrs. Oka had asked, and the parents had said yes, and once the parents had said yes there wasn't anybody in the household who could stand the thought of the six of them going without the rest. Mitsuru had looked at that sum for three days and come out, every time, with the same answer: if they were going to be anywhere, they'd be together, and in the open, and in the light." },
    { n: "Ishida, Kubo and Sakai walked with the mothers. They had since August. Wherever the mothers went, one of them; on the moon night, Mitsuru had said, all three." },
    { n: "Mrs. Oka had been there since two. A row of blankets along the grass above the sea wall, end to end, and on the blankets trays of white round dumplings stacked in pyramids, a hundred of them, more, and tall vases of pampas grass at each end, and thermoses of tea, and cushions. She stood among it all in a dark kimono with her white gloves and her face lit up, waving everyone in, *sit, sit, it'll be up any minute*." },
    { n: "The mothers had helped. They'd been at the boarding house since noon. Solji in a cream cardigan, the one she'd come through in, her hair down. Miseon in her green hanbok again; Solar didn't ask why; she thought she knew. Mrs. Kim in a sensible jacket and flat shoes, the car keys in her pocket, the way they'd been in her pocket every day since August, as if she might need to go somewhere in a hurry." },
    { place: 'Port Island · Seaside Park', time: 'Evening', bg: 'port-island-seaside-park-sunset', music: 'tender', soft: true },
    { n: "At a quarter past five, Mrs. Oka stood up and brushed off her kimono." },
    { s: 'mrsoka', f: 'happy', t: "I'll go on ahead. I'll put the kettle on for when you're back. It's a long walk over the bridge for an old woman, and you young things will want to stay and watch it come all the way up." },
    { s: 'solji-runners', f: 'surprised', t: "Oh, you'll miss it! Stay, stay, after all this—" },
    { s: 'mrsoka', f: 'neutral', t: "Oh, I've seen it, dear. I've seen a great many. You watch it for me." },
    { n: "She went along the row of blankets, touching shoulders, the way she did, *enjoy it, enjoy it, eat up*, and stopped behind the three mothers, and bent between them, and said something to them that Solar couldn't hear; and the mothers laughed, and nodded; and then she straightened, and looked down the row of blankets to where Solar sat between Haechan and Hanni, and smiled at her, and lifted one gloved hand, and walked away along the sea wall toward the bridge in the last of the sun, unhurried, small, her shadow very long on the paving behind her." },
    { n: "Her shadow. Solar watched it go with her. Long and thin and dark on the stones. It had a shadow. Of course it did. Of course she did." },
    { n: "At five-forty, the moon came up out of the sea." },
    { place: 'Port Island · Seaside Park', time: 'Dusk', bg: 'port-island-seaside-park-sunset', music: 'badfeeling' },
    { n: "It came up enormous. Bigger than any moon Solar had ever seen in any life. It came up out of the flat sea in the east like something surfacing, orange, then gold, the whole bottom edge of it still in the water, and the sea all the way from the horizon to the wall under their feet lit up in a long road of gold, as if you could walk out on it." },
    { n: "Somebody on the blankets said *oh*. Somebody else started to clap." },
    { n: "Then the moon cleared the water. And it was red." },
    { n: "Not orange. Not the low gold of a moon in haze. Red. The red of the hour. And as it cleared the water, the red came off it the way light comes off a lamp when you switch it on, and went across the sea, and over the wall, and over the park, and over them." },
    { dark: true },
    { n: "At five-forty-two in the evening, in full daylight, with the sun not yet down in the west behind them, the town went red." },
    { s: 'fuuka', f: 'surprised', t: "*No. No, no, it's— it's not midnight. It can't be— Mitsuru-senpai, it's not midnight, it's not even dark—*" },
    { n: "All along the sea wall, all over the park, the people who'd come out to see the moon stopped. The couples on the benches. The families on the grass. A boy on a bicycle. They stopped, and the dark came up out of the ground round each of them, and closed, and there were coffins on the benches and coffins on the grass and a coffin standing beside a bicycle lying on its side with its wheel still turning." },
    { n: "On the blankets, the household didn't stop. Nobody stopped. Forty people and a dog, and six parents, and three men in dark suits, sitting in the red in daylight among a hundred white dumplings and two vases of pampas grass, looking at each other." },
    { s: 'mitsuru', f: 'serious', t: "Home. Everyone. Now. Over the bridge, as fast as you can walk, and nobody stops, and nobody turns round for anything. Twos. Go." },
    { place: 'Moonlight Bridge', time: 'The Red Hour', bg: 'darkhour-moonlight-bridge', music: 'darkhour' },
    { n: "Moonlight Bridge was a kilometer and a half, end to end, from Port Island to Iwatodai. On an ordinary night you walked it in twenty minutes. Solar had walked it a hundred times." },
    { n: "They went onto it in a long uneven line, the whole household, along the pedestrian walk at the edge, with the traffic lanes stopped beside them, every car standing still where it had been at five-forty-two with a coffin at the wheel, and the red moon climbing behind them, and the hum." },
    { n: "And the fathers, God help her, the fathers fought over who got to walk next to her." },
    { n: "Not fought. Nothing so obvious. But Solar had Haechan at her back and Akihiko and Mitsuru ahead of her, and the moment they were on the bridge Taejoon was at her left, without a word, the way he'd have walked her down a hill at home, close, his hand an inch from her elbow; and then Jaesang was at her right, a beat later, smoothly, as if he'd been there all along, his hand on the small of her back the way it had been on the small of her back at every party she'd ever been walked into; and Mr. Kim, outmaneuvered on both sides, went round in front of her and walked backward, facing her, talking, *it's fine, it's fine, sweetheart, it's just a bridge, look at me, look at your dad*." },
    { s: 'jaesang-runners', f: 'neutral', t: "...You're on her left." },
    { s: 'taesang-strangers', f: 'neutral', t: "Mm." },
    { s: 'jaesang-runners', f: 'neutral', t: "I'm on her right. That's— fine. That's fine. We'll just— both." },
    { s: 'kim-dad', f: 'neutral', t: "And I'm in front! Somebody's got to be in front. I'm the vanguard. Honey, I'm the vanguard!" },
    { n: "Behind them, way back, Mrs. Kim's voice came up the line, exasperated and fond, *watch where you're going, you idiot, you'll walk into a car*; and the mothers laughed. Solar heard them. All three. At the back of the line, in a knot, slow, because Solji's heels were wrong for a bridge and Miseon's hanbok was long, with the three men in dark suits round them like a wall, and they were laughing at the three fathers fighting over their daughter at the front." },
    { n: "*Let them*, Solji said, somewhere back there. Solar heard it. *Let them have her for a bit.*" },
    { n: "That was the last thing she heard any of them say." },
    { place: 'Moonlight Bridge', time: 'The Red Hour', bg: 'darkhour-moonlight-bridge', music: 'eerie' },
    { n: "The viola started halfway across." },
    { n: "Ahead of them. At the rail, at the very top of the span, where the bridge was highest over the water. The blue coat, buttoned to the throat. The black case open at her feet. Her back to the road, to them, to all of it; her face to the bay and the red moon; and her arm going, slow, long, the bow drawn all the way out and all the way back, *the long way round*." },
    { s: 'chenle', f: 'surprised', t: "*Oh— oh no. Oh no, the bridge is— Fuuka-noona, the bridge is getting longer. It's getting longer. I can hear it. Every bar she plays there's more of it—*" },
    { s: 'fuuka', f: 'surprised', t: "*I can't hear the back. Solar, I can't hear the back of the line anymore. It's like— there's a hand over it. There's a hand over the back of the bridge—*" },
    { n: "Solar looked back." },
    { n: "The bridge behind her went on too far. That was the first thing. The lamps along the rail, the tall ones, red, every thirty meters; she'd walked past maybe twenty of them; and behind her there were sixty, eighty, a hundred, going away down the walk in a long dwindling line to a point so far off it was almost nothing, and at the very end of it, at the vanishing point, small as a thumbnail, a knot of people. Six people. Three in light colors and three in dark." },
    { n: "The mothers. And the men. So far back. Too far back. They'd been twenty meters behind her a minute ago." },
    { n: "The viola went on, and with every long note the lamps between them multiplied, *one more, one more, one more*, the bridge spinning itself out longer and longer under the moon like thread off a wheel." },
    { s: 'solar', f: 'surprised', t: "Hanne. Hanne, stop. *Stop*, please—" },
    { n: "The woman at the rail didn't stop. She didn't turn. Her bow went on, all the way out, all the way back, and her head was bowed over the instrument, and her shoulders were shaking." },
    { n: "Then, from the back of the bridge, so far away it should have been impossible, so clear it was like a voice in Solar's own ear, a child said: *Mommy.*" },
    { n: "Solar knew the voice. She'd have known it anywhere. She'd been hearing it on recordings her whole life: on old videos at Thanksgiving, on a cassette in a drawer in a house on a hill, on the camcorder tape Mr. Kim played every New Year whether anyone wanted it or not." },
    { n: "It was her voice. Her own. At five years old." },
    { place: 'Moonlight Bridge', time: 'The Red Hour', bg: 'darkhour-moonlight-bridge', music: 'tension' },
    { n: "She ran. They all ran. Back down the bridge toward the knot at the end of it, and the bridge ran away from them under their feet, lamp after lamp after lamp, and they gained on it, and lost, and gained, and the fathers ran with her, and Akihiko ahead of all of them with his taped hand out in front of him as if he could take hold of the distance and pull." },
    { n: "And because it was so far, and because it took so long, they saw everything." },
    { n: "There was something with the mothers. Low. About the height of a child. Solar couldn't see it properly. Nobody could; they compared it afterward and nobody had seen the same thing. It was a shape in the red at the edge of the walk, a smudge in the air like heat over a road, and it hummed, it hummed the lullaby, three up, two down, a long one, and the whole bridge hummed with it in its cables." },
    { n: "Kubo stepped in front of it. The young one, with the earpiece. He had his hand up, the way you'd stop traffic, and he was saying something, *ma'am, ma'am, behind me, please*, and the thing in the air took him by the wrists." },
    { n: "Solar saw it. She'd see it for the rest of her life." },
    { n: "It lifted him. Off the walk, by his wrists, his arms out to either side, the way you'd lift a child by its hands to swing it. And it kept pulling. Slowly. Patiently. Both ways at once. His jacket split at the shoulder seams, and then his shirt, and then he did; his arms came away from him at the shoulders, slowly, steadily, the skin stretching and stretching and then opening, peeling back off them like the sleeves of a sweater pulled off inside out, and there was no blood. There was no blood at all. Under the skin he was pale, and dry, and fine, like the inside of a loaf, and as his arms came free a white dust came off them into the red air and drifted out over the rail and the water like flour shaken off a cloth." },
    { n: "He was still saying *ma'am*. Solar would remember that. He was still saying it when the thing let go of his arms and they fell on the walk, two empty sleeves of skin, and he sat down on the bridge with nothing at his shoulders and a look on his face of total surprise." },
    { n: "Sakai went next. Tall, silent Sakai. He'd got the mothers behind him against the rail and put his back to them and his face to it, and it came over the rail beside him, and took him by the belt and the collar, and bent him backward over the rail, and he folded, too far, much too far, the way a man doesn't fold; and the skin of his back opened, in a line, from his collar to his belt, neat as a seam unpicked; and something went in. Solar saw the back of his jacket move. Saw him go full and then go slack. He hung over the rail and he emptied, like a glove pulled off a hand, the whole long shape of him settling down inside his own suit, folding in on itself, until there was only the suit, hung over the rail, with a man's skin in it, very flat, like laundry." },
    { n: "Ishida was last. Gray, kind Ishida, with the face like a closed door. He had Miseon behind him. He had her pressed back against the rail with his own body and his arms spread on either side of her, and he was talking to her, low and steady, *don't look, ma'am, look at me, don't look at it, look at me*, the way you'd talk to someone on a ledge." },
    { n: "It took his face." },
    { n: "It took it from the top. From the hairline. It peeled it down, slowly, the whole face in one piece, the way you'd lift a mask off, and he was still talking under it, *look at me, ma'am*, his mouth moving under where his mouth had been; and it held the face up in the red, his face, gray and kind, and looked at it, as if it were deciding whether it suited; and then laid it on the rail. Carefully. Face up. Looking at the moon." },
    { n: "What was left of Ishida stood for a moment longer with his arms spread in front of Miseon. Then he folded down, slowly, the way a coat folds when you take it off the hook, onto the walk at her feet." },
    // CG: eqx-bridge-rail — the rail of a long bridge in red light under an enormous red moon; laid neatly on the rail's flat top, face up toward the sky, a pale empty mask of a gray-haired man's face; far down the bridge, out of focus, a cluster of figures running.
    { n: "Somebody behind Solar was screaming. She thought it was Yukari. She thought it might have been her." },
    { place: 'Moonlight Bridge', time: 'The Red Hour', bg: 'darkhour-moonlight-bridge', music: 'eerie' },
    { n: "Then the asking." },
    { n: "It was so small. That was what nobody could ever explain afterward, at the inquiry Mitsuru held in the command room with the lights all on, over and over, all of them telling it, none of them able to make it sound like anything. It was so small. It was the smallest thing in the world." },
    { n: "*Mommy*, said the child's voice, at hip height, by Solji, in English. Solar's voice, at five. *Mommy, hold my hand across. It's so high. Hold my hand across.*" },
    { n: "And Solji looked down. Solar saw her look down, at nothing, at the red air beside her knee, and saw her face change. Saw it go soft and sure and certain, the way it had gone soft and sure at a crossing on Lexington Avenue fifteen years ago, when a small hand had come up into hers. And Solji, very naturally, without a second's thought, held out her hand, down, at the height of a child's hand, and closed it on something." },
    { n: "*Eomma*, said the voice, by Miseon, in Korean, low, the way a child talks in a dark room with the light off. *Eomma, carry this for me. It's heavy. Carry it for me.*" },
    { n: "And Miseon, with Ishida folded at her feet, with his face on the rail beside her looking at the moon, looked down. And her arms came up. Very gently. The way they come up for a sleeping child, or for something precious that's been handed to you to hold for a moment. And closed round nothing. And held it." },
    { n: "*Mom*, said the voice, by Mrs. Kim, quick and cross and out of breath, a girl running to catch up, *Mom, wait for me! Wait! Wait for me!*" },
    { n: "And Mrs. Kim, who had been backing away along the rail with her car keys out in her fist like a weapon, stopped. And turned round. Toward the voice. And waited." },
    { n: "That was all. A hand. Two arms. A woman stopping on a bridge to let her daughter catch up." },
    { n: "Each of them gave it. And each of them was gone." },
    { n: "Not taken away. Not dragged. Solar was nearly there by then, nearly, ten lamps off, five, close enough to see their faces; and she saw them go, all three in the same second, the way a picture goes when somebody switches off the screen. There and then not." },
    { n: "Where they'd stood, on the walk by the rail, in a neat row, there were three pairs of shoes." },
    { n: "Solji's heels. Miseon's soft embroidered slippers. Mrs. Kim's flat black sensible shoes. Side by side. Neatly. The way you'd leave your shoes at the door of a house. Their toes all pointing the same way along the bridge, toward Iwatodai. Toward the town. Toward home." },
    // CG: eqx-shoes — three pairs of women's shoes standing neatly side by side on the walkway of a bridge in red light, a pair of heels, a pair of embroidered slippers, a pair of plain flat shoes, toes all pointing the same way down the bridge toward a distant shore.
    { n: "The viola stopped. Mid-note." },
    { n: "And the bridge came back. All at once, with a jolt that went up through Solar's feet, the lamps collapsing back into their right number like a telescope closing, a hundred, eighty, sixty, twenty, and she was there. She was standing on the walk where her mothers had stood, with their shoes at her feet, with her fathers arriving behind her one after another, out of breath, running, and stopping, and seeing." },
    { n: "Nobody said anything. There wasn't anything." },
    { n: "Then, on the walk, at the rail, in the red, the three suits moved." },
    { n: "Kubo's first. His arms, the two long sleeves of skin, lying on the walk where they'd dropped; they twitched; and the rest of him, sitting propped against the rail with nothing at his shoulders, stood up. Sakai's suit came down off the rail where it had hung and stood up beside him, flat, empty, full of air, his skin hanging in it like a costume on a hook. And Ishida's. Folded at the foot of the rail where Miseon had stood. It stood up last, without a face, and turned the front of its head toward Solar." },
    { n: "Three men in dark suits, with nobody in them. Standing in a row between her and the town. With the hum coming up out of them. The way you'd stand at a door to stop someone getting past." },
    { n: "And behind them, in the air, the thing that had done it. The smudge. The heat over a road. Still there, low, humming, in the red; and as Solar looked at it, for the first time, it stopped being the height of a child. It rose. It went up into the red like steam, and spread, and hung over the walk between the three suits and the shore, a shape you couldn't look at properly, a balance, a beam with nothing on either side of it, tipping, very slowly, toward the town." },
    { s: 'akihiko', f: 'serious', t: "...Get back. All of you. Get the fathers back. Shinjiro, Ken. Get them *back*." },
    { s: 'mitsuru', f: 'serious', t: "Solar. Haechan. With me. Akihiko, with me." },
    { n: "Her voice was perfectly level. Her face was white to the lips. She'd drawn the rapier. She was looking at the empty suit that had been Ishida with an expression Solar had never seen on her face in two years, and never wanted to again." },
    { s: 'haechan', f: 'serious', t: "*Dalnim.*" },
    { summon: 'haenim', name: 'Haenim', sub: 'Day equals night.' },
    { battle: { id: 'eqx-equinox', op: 'eqx-equinox', kind: 'operation', title: 'Full Moon · The Equinox', desc: 'Moonlight Bridge at the harvest moon, the red come early, three empty suits standing in a row between her and the shore, and something over them, tipping toward the town.', forced: true } },
    { music: 'night' },
    { n: "The beam came down. Not like ash. Like dust shaken off a cloth: white, fine, sweet, a long pale cloud of it going out over the rail on a wind that wasn't there and down onto the black water of the bay, where it lay on the surface in a skin, and didn't sink." },
    { n: "The three suits fell where they stood. Flat. Finally. Empty. Kubo's against the rail. Sakai's across the walk. Ishida's at Solar's feet, face down, if he'd had a face; the face was on the rail, still, looking at the moon." },
    { n: "Mitsuru went down on her knees beside it. She took off her jacket. She reached up and took Ishida's face off the rail, in both hands, gently, the way you'd take down a photograph; and laid it face down on the jacket, and folded the jacket over it, and sat back on her heels with it in her lap and didn't move." },
    { s: 'mitsuru', f: 'sad', t: "...Ishida Tetsuo. Fifty-four. Two daughters. He used to bring me sweets in a paper bag when I was eight. He was in my father's night unit before I could walk." },
    { s: 'mitsuru', f: 'sad', t: "Kubo Ryota. Twenty-six. His mother lives in Okayama. He sends her money on the twenty-fifth." },
    { s: 'mitsuru', f: 'sad', t: "Sakai Minoru. Thirty-eight. He didn't talk. He never talked. He was the best of them." },
    { n: "Nobody said anything. Junpei had come back down the walk against orders; he was standing over Sakai, looking at him, with his hands at his sides opening and closing. Ken had his face in Shinjiro's coat and Shinjiro's hand was over the back of his head, holding it there, and Shinjiro was looking at the suit on the walk with no expression at all. Yukari was on her knees at the rail being sick through the bars into the bay, and Hanni was holding her hair, and Hanni's own face was gray and wet and perfectly calm." },
    { n: "The fathers were at the shoes." },
    { n: "Taejoon was on his knees. He had picked up Miseon's slippers, both, in his two hands, and was holding them, not tightly, in his lap, the way he'd have held her hands. He didn't make a sound. His face didn't do anything. He knelt on the bridge in the red holding his wife's shoes and looking at the town, at the place where the toes had been pointing, and said nothing, very loudly, and went on saying it." },
    { n: "Jaesang couldn't touch Solji's. He stood over them. His hands were out a little from his sides as if he'd been about to pick them up and stopped, and stayed like that, stopped. Akihiko had him by the arm. Solar didn't know when that had happened. Akihiko was standing beside her father holding his arm above the elbow, not gripping, just holding, and her father was letting him." },
    { n: "Mr. Kim was walking. Up and down. Three steps up the bridge, toward the town, and three back. Talking. In Korean, fast, reasonable, the voice of a man explaining something simple to a policeman." },
    { s: 'kim-dad', f: 'sad', t: "She's gone ahead. She does that. She always goes ahead. She gets impatient. She'll be at the end of the bridge. She'll be at the end of the bridge waiting with the car keys going, *where have you been, what took you so long*—" },
    { n: "Nobody told him she wouldn't. Nobody could. He went on walking, three steps and three back, and on the walk at his feet her flat black shoes stood in their row with their toes pointing at the town." },
    { place: 'Moonlight Bridge', time: 'The Red Hour', bg: 'darkhour-moonlight-bridge', music: 'eerie', soft: true },
    { n: "Solar was the only one looking down the bridge." },
    { n: "She didn't know why. She'd been standing at the shoes and something made her look up, toward the town, along the walk where the toes were pointing; and the bridge was its right length again, a long red line under the lamps down to the Iwatodai shore; and there were three women walking along it." },
    { n: "Away from her. Toward the town. Unhurried. Three women walking home together after a party, close, in a knot, the way the mothers had walked at the back of the line, shoulder to shoulder." },
    { n: "Barefoot." },
    { n: "A cream cardigan. A green hanbok, the long skirt moving. A sensible jacket." },
    { n: "She opened her mouth to scream their names and nothing came. Her feet didn't move. Nobody else had looked up. Nobody else saw." },
    { n: "Under the last lamp before the shore, the woman in the cream cardigan turned her head." },
    { n: "It was her mother's face. It was Solji's face. Solar was a hundred meters off and she saw it as clearly as if it were an inch from hers, under the red lamp, turned back over its shoulder toward her." },
    { n: "It didn't fit. That was the thing. It was her mother's face, every line of it, the mole by the left eye, the soft mouth, and it didn't fit; it hung a little loose, the way a sleeve hangs on a thinner arm. It had slipped. At the jaw. Just slightly. Just enough that you could see where the edge of it was, and that there was something else under the edge, and that the eyes in the eyeholes of her mother's face, looking back at Solar down a hundred meters of red bridge, were not her mother's eyes. They were wet and dark and very patient, and they were looking at her with enormous, overwhelming fondness." },
    { n: "And down the back of the cream cardigan, from the collar to the hem, there was a line. A seam. Open a finger's width. And inside it, in the red light, something moved." },
    // CG: eqx-walking-home — three barefoot women seen from far behind walking away together down a long bridge in red light toward a dark shore, a cream cardigan, a green hanbok, a plain jacket; the nearest has turned her head back over her shoulder, her face lit by a red lamp, too far away to read.
    { n: "Then the face turned away. And the three of them walked on, off the end of the bridge, into the red, into the town, home, and were gone." },
    { flag: ['eqx-mothers-taken', 'eqx-saw-face'] },
    { n: "Solar stood on Moonlight Bridge with her mothers' shoes at her feet and her fathers round her and knew, the way you know you've been cut before it starts to hurt, that somebody was wearing them." },
    { n: "Somebody was wearing her mothers home." }
  ] },

  { id: 'eqx-glove', date: '9/23', slot: 'late', consumes: true, title: 'show me your hand', place: 'Iwatodai Dorm · Lounge', time: 'The Red Hour',
    cast: { solar: 'Solar', mitsuru: 'Mitsuru', akihiko: 'Akihiko', haechan: 'Haechan', fuuka: 'Fuuka', ken: 'Ken', junpei: 'Junpei', jaehyun: 'Jaehyun', yunjin: 'Yunjin', hanni: 'Hanni',
      'jaesang-runners': 'Jaesang', 'taesang-strangers': 'Taejoon', 'kim-dad': 'Mr. Kim' },
    scene: [
    { bg: 'darkhour-dorm-lounge', music: 'darkhour' },
    { dark: true },
    { n: "The red didn't end." },
    { n: "Midnight came and went. On the clock on the lounge wall, which had stopped at five-forty-two with its second hand trembling on the eight, it didn't come at all. On Akihiko's stopwatch, which was running, which he'd started on the sea wall when the moon cleared the water and hadn't stopped, it came and went and kept going: six hours. Six hours and four minutes. Six hours and five." },
    { n: "He sat on the arm of the couch with it in his taped hand and watched the numbers turn over and didn't say any of them out loud." },
    { n: "The whole household was in the lounge. Nobody had been told to be. Nobody could have been anywhere else. Every lamp lit and every one of them red. The windows red. The coffins standing in the beds of every house down the hill, and in the dorm itself, in no bed at all, because there was nobody in the dorm who wasn't awake: forty people and a dog and three fathers, on the couches and the floor and the stairs, in the red, in a silence so complete that you could hear the hum in the walls, and under it, if you listened, and nobody could stop listening, the sea." },
    { n: "The fathers were on the couch. All three. Somebody had put them there. Somebody had put blankets round their shoulders, though it wasn't cold; Hanni, Solar thought, or Fuuka. They sat in a row, the way they'd sat on the bench outside the station with the Kit Kats, and didn't look at each other." },
    { n: "Taejoon had the slippers in his lap. He hadn't put them down since the bridge. Mr. Kim had stopped talking an hour ago and was looking at his hands. Jaesang sat very upright with his cuffs straight and his eyes open and his face completely still, a man in a meeting that had gone on so long he'd forgotten what it was for; and Jaehyun was on the floor at his father's feet with his back against the couch and his head against his father's knee, and his father's hand was on his hair, and neither of them seemed to know it." },
    { n: "Mitsuru stood at the whiteboard. She'd been standing there for some time with the red pen in her hand." },
    { n: "Under HUNTING, under the boxed names of the four girls, under *Hanne?*, she wrote three names, small and square and very straight." },
    { n: "*Ishida T. Kubo R. Sakai M.*" },
    { n: "She drew a line under them. She stood looking at the line. Then she wrote, under it, three more names. She wrote them in their own scripts. She'd asked each father for the spelling, an hour ago, quietly, one by one, crouched in front of the couch; and each of them had told her, and Solar had watched each of them have to say it." },
    { n: "*Solji. 미선. 한소연.*" },
    { n: "Beside them she didn't write anything. Not *dead*. Not *taken*. She held the pen over the space for a long moment and then capped it, and put it down on the ledge, and stood with her back to the room and her hand flat on the board beside the names, and Solar saw her shoulders, once, go." },
    { place: 'Iwatodai Dorm · Lounge', time: 'The Red Hour', bg: 'darkhour-dorm-lounge', music: 'eerie', soft: true },
    { n: "Haechan found her on the stairs. The seventh one up. She hadn't counted; she'd just sat down where her legs stopped. He sat down on the step below her, with his back against the wall, so that his shoulder was against her shin, and didn't say anything for a long time." },
    { s: 'haechan', f: 'neutral', t: "...You saw something. On the bridge. After. You were looking down the bridge and your face did a thing and you haven't said a word since." },
    { s: 'haechan', f: 'neutral', t: "I'm not asking. I'm just— saying I saw your face." },
    { n: "She looked down at him. At the back of his head, the rope scar on the palm of his hand where it lay on his knee. Down the stairs, through the lounge door, at the three fathers on the couch, at Taejoon holding the slippers." },
    { choose: [
      { t: "(Tell him. Quietly. All of it.)", flag: 'eqx-face-told', then: [
        { n: "She told him. Very quietly, on the stairs, with her mouth near his ear, so that it couldn't go any further down the stairs than him. The three women walking home barefoot. The cream cardigan. Her mother's face turning under the last lamp, and the way it hung, and the edge at the jaw, and the eyes. The line down the back. The thing moving in it." },
        { n: "He didn't move while she said it. When she finished he didn't move for a long time after." },
        { s: 'haechan', f: 'serious', t: "...Okay. Okay." },
        { s: 'haechan', f: 'serious', t: "Nobody else. Not them. Not tonight. Not your dads. Okay? Not till we know what we're— not till we know. They can't. They'll go. They'll go down the hill right now in the red and knock on every door in this town." },
        { n: "He turned round on the step and put his arms round her knees, and his forehead against them, and held on, hard, the way he'd held onto a rope halfway down a well, and she put her hand on the back of his head, and they stayed like that on the seventh stair, and neither of them said anything else for a long time, and she understood that she wasn't carrying it alone anymore, and that he'd picked it up without being asked." }
      ] },
      { t: "(Don't. Not yet. Put your hand on his hair.)", flag: 'eqx-face-kept', then: [
        { n: "She didn't. She couldn't. She put her hand on his hair instead, the back of his head, and left it there, and he understood that too, the way he understood most things about her before she did; he went still under her hand and didn't ask again." },
        { s: 'haechan', f: 'neutral', t: "...Okay. When you want. Or never. Both of those are okay." },
        { n: "She sat on the seventh stair with her hand on his head and her mother's face in the dark behind her eyes, turning, turning, under the last lamp, and the edge at the jaw, and she held onto it alone, which was its own sentence." }
      ] }
    ] },
    { n: "Akihiko said it out loud at last, at what would have been four in the morning, in a voice so quiet that only the stairs heard it." },
    { s: 'akihiko', f: 'neutral', t: "...Ten hours, eleven minutes." },
    { place: 'Iwatodai · River Street', time: 'The Red Hour', bg: 'darkhour-iwatodai-street', music: 'darkhour' },
    { away: true },
    { n: "Hanne walked off the bridge with her case." },
    { n: "Off the Iwatodai end, at the bottom, where the walk came down to the road along the river. She'd watched them from the top of the span. All of it. She'd watched with her bow arm still going, still going, because she couldn't stop it, because when she stopped it the humming in her head got so loud that her eyes ran; and she'd watched the three men, and the three women, and the shoes, and the girl who'd once said her name on a platform running down the bridge toward them screaming it, and the bridge running away from her, and her own bow, drawing it out. Long and longer. The long way round." },
    { n: "She had thought it was for a table." },
    { n: "That was the thing she kept saying to herself, under her breath, all the way along the river in the red, with the coffins standing in the windows of every house she passed. *I thought it was for a table. I thought it was for a long table. I thought it was so nobody would ever be left on the platform.*" },
    { n: "She'd thought she was building a house where nobody had to go home to an empty flat. Where everyone was held. Where the doors stayed open. She'd thought the voice that came to her door in the spring, her mother's voice, *open the door, it's only me*, had come to help her build it." },
    { n: "Her right hand on the handle of the case was shaking so badly that the case knocked against her leg with every step." },
    { place: 'A Kitchen by the River', time: 'The Red Hour', bg: 'darkhour-iwatodai-street', music: 'eerie' },
    { dark: true },
    // BG: none on purpose — the kitchen is only its lamp, a counter, a stove, and someone's back.
    { n: "The kitchen door was open. Of course it was. It was always open, for her." },
    { n: "There was a lamp on. One. Over the counter, in the red, burning red. A pot on the stove, not steaming. A bowl of white dough on the counter under a damp cloth. The smell of rice, and sugar, and pine, and under it, at the back, sweet in the wrong place." },
    { n: "A woman stood at the counter with her back to the door. Her sleeves pushed up. A white apron tied over a cream cardigan. Bare feet on the boards. Her hands in the bowl, kneading. Slowly. Patiently. Humming. Three up, two down, a long one." },
    { n: "Hanne stood in the doorway. She didn't put the case down. She held onto it as if it were the only thing in the world with a handle." },
    { n: "*Why*, she said. It came out of her very small." },
    { n: "The woman at the counter didn't turn round. Her hands didn't stop. *Oh*, she said, *there you are*, warm, fond, delighted, in a voice that was a mother's voice, any mother's, Hanne's own mother's, and then for one word slipped and was somebody else's, an American woman's, and then slid back. *There you are. You played so beautifully tonight. You've never played so well. Come in. Come in out of the cold, child.*" },
    { n: "Hanne didn't come in. She stood in the doorway and looked at the back of the cardigan. At the line down it. The seam, from the collar to the apron strings, open a finger's width. At what was inside it, moving, in the red." },
    { n: "Then she looked at the hands. In the bowl. In the dough. Gloved. White cotton gloves, white to the wrist with flour, the fingertips darned over and over." },
    { n: "She'd never seen them without the gloves. She'd never asked. Nobody had ever asked. That was the thing. In all these months, in this whole town, nobody had ever once asked." },
    { n: "*Show me your hand*, Hanne said." },
    { n: "The kneading stopped." },
    { n: "*Please*, Hanne said. Her voice was shaking. Her whole body was shaking; the case was knocking against the door frame, *tock, tock, tock*. *Please. Take off your glove. Show me your hand. I want to see your hand.*" },
    { n: "For a long moment nothing in the kitchen moved. The lamp burned red. The pot didn't steam. The woman at the counter stood with her hands in the bowl and her back to the door and didn't breathe, or didn't need to." },
    { n: "Then, slowly, she took her right hand out of the dough." },
    { n: "She held it up. In the lamp light. Over her shoulder, so Hanne could see it, the way you'd hold up a hand to show a child there was nothing in it. And with the other hand, unhurried, finger by finger, she drew the glove off." },
    { n: "It wasn't a hand." },
    { n: "Hanne would try to say what it was, later. Four days later, in a room with a girl holding her other hand, she'd try, and it would cost her. It was a hand the way a mask is a face. It was very large. It was much too large to have been in that glove; it came out of the glove the way a foot comes out of a shoe that was always too small for it, unfolding, easing, pleased to be out. It was covered in something dense and short and coarse. Striped. Under the flour. The flour had been rubbed into it, carefully, over and over, for years, to make it pale, to make it soft, the way you'd powder a face. And at the ends of it, where the darned fingertips of the glove had been, four curved, yellow, patient points, each one as long as Hanne's finger." },
    // CG: eqx-glove — in red lamp light, over the shoulder of a woman standing at a kitchen counter with her back turned, a raised hand half out of a white cotton glove: what comes out of the glove is far too large, coarse, striped under a dusting of flour, with long curved points where the fingertips should be.
    { n: "It turned in the lamp light, so she could see it from both sides. It flexed. The points came out a little further, and went back. It was showing her. It was so proud." },
    { n: "*There*, said the woman at the counter, fondly, in no voice in particular. *There. Now you've seen. Now you know. And you'll go on playing anyway, won't you, child. Because who else is going to hold you.*" },
    { n: "And the hand reached back over her shoulder, unhurried, the whole long arm of it coming out of the cream cardigan's sleeve much further than an arm should, and took Hanne's right hand, the bow hand, the one shaking on the case, in its own." },
    { n: "Gently. The way you'd take a child's hand to cross a road." },
    { n: "And closed." },
    { n: "Hanne didn't scream. She'd think about that afterward, too. She stood in the kitchen doorway with her hand in it and felt it close, slowly, slowly, warm, heavy, rough, and felt every small bone in her own hand, one by one, begin to understand the shape of what was holding it; and the woman at the counter put her other hand back in the dough, and went on kneading, and went on humming, three up, two down, a long one, while she held on." },
    { flag: 'eqx-hanne-hand' },
    { act: { numeral: 'Equinox', title: 'day equals night' } }
  ] },

  { id: 'eqx-shoes', date: '9/24', slot: 'early', consumes: true, title: 'facing home', place: 'Moonlight Bridge', time: 'Dawn',
    cast: { solar: 'Solar', mitsuru: 'Mitsuru', akihiko: 'Akihiko', haechan: 'Haechan', mrsoka: 'Mrs. Oka', aigis: 'Aigis', shinjiro: 'Shinjiro', jaehyun: 'Jaehyun',
      'jaesang-runners': 'Jaesang', 'taesang-strangers': 'Taejoon', 'kim-dad': 'Mr. Kim' },
    scene: [
    { bg: 'iwatodaidorm-livingroom-night-autumn', music: 'night' },
    { away: false },
    { dark: false },
    { n: "At five-forty-two in the morning the red went out." },
    { n: "Not all at once. The way a fever goes. The color draining back out of the lamps and the windows, the hum going down into the ground, the coffins in the beds down the hill sinking and opening and being people again, people who'd gone to bed and would wake up at seven having slept twelve hours without knowing it and feeling, all of them, strangely, very rested." },
    { n: "Akihiko stopped the stopwatch. He looked at it. He held it up so the room could see it, because he couldn't say it." },
    { n: "*12:00:00.*" },
    { n: "Twelve hours. To the second. From the moon clearing the water to now, the sun coming up gray behind the hill. The hour had been exactly as long as the day." },
    { s: 'akihiko', f: 'neutral', t: "...Day equals night." },
    { n: "Nobody said anything." },
    { place: 'Moonlight Bridge', time: 'Dawn', bg: 'moonlightbridge', music: 'tender' },
    { n: "They went back for the shoes at six." },
    { n: "The fathers wouldn't be kept from it and nobody tried. Mitsuru had sent for the Group at five-forty-three, and the Group had come, in vans, men in gray coveralls with stretchers and long faces, and by the time the household came along the walk in the thin gray light the suits were gone off the bridge, all three, and the walk had been washed, and there was nothing at the rail where Kubo had sat down, and nothing at the rail where the face had been." },
    { n: "The shoes were still there." },
    { n: "Nobody from the Group had touched them. Mitsuru had told them not to. Three pairs. In a row. At the rail. In the gray dawn with the first traffic going past in the lanes beside them, ordinary cars full of ordinary people on their way to work, who looked at the knot of people standing on the walk and at the three pairs of women's shoes at their feet and then looked away, the way people do." },
    { n: "The toes were still pointing at the town." },
    { n: "Taejoon set the slippers down. The ones he'd been holding all night. He crouched, and set them down in the row, back where they'd been, exactly, toes to the town, between the heels and the flat black shoes. As if he were putting things back where somebody would come looking for them. He stayed crouched there with his hand on them a moment longer. Then he stood up." },
    { n: "Jaesang knelt. In his suit, on the wet walk. He picked up Solji's heels, one in each hand, and held them, and looked at them, and Solar saw him see the scuff on the left one, the one she'd made on the sea wall steps getting up off the blanket, laughing; and he put his thumb on the scuff, and rubbed it, once, as if it would come off." },
    { n: "Mr. Kim picked up the flat black shoes and held them against his chest, and turned toward the town, and looked at it for a long time, at the river street and the hill and the roofs, and then said, in Korean, to nobody, very reasonably:" },
    { s: 'kim-dad', f: 'sad', t: "...She'll need these. She's got no shoes on. She'll have cold feet." },
    { n: "Somebody was coming along the bridge from the Iwatodai end." },
    { n: "Small. Unhurried. In a dark kimono with a shawl over it, against the early chill, and a basket on her arm, and a big thermos in her other hand, and her white gloves on. Coming along the walk in the gray light toward them, her face crumpled and wet, the way it had been crumpled and wet on the morning of the twenty-seventh of July." },
    { s: 'mrsoka', f: 'sad', t: "I heard. Oh, I heard. Oh, you poor things. You poor, poor things. I've been up all night, I couldn't— I've brought tea. I've brought you something. You've not eaten. None of you have eaten." },
    { n: "She came right up to them. She didn't stop at the edge of them the way she stopped at a threshold. She came in among them, the basket on her arm, and put down the thermos, and went to the fathers." },
    { n: "Solar watched her do it. She'd remember it. She'd remember it on the worst nights for the rest of the year." },
    { n: "Mrs. Oka put her arms round Mr. Kim, with his wife's shoes held against his chest. And he let her. He put his face down on her shoulder, a man in a fleece with a pair of black shoes in his arms, and sobbed, once, a great dragging sound, and she held him, and patted his back, twice, and said *there, there*." },
    { n: "Then Jaesang, on his knees. She crouched beside him and put her gloved hand on the back of his neck, and he didn't move away. He shut his eyes." },
    { n: "Then Taejoon. Standing. Who didn't let anyone touch him. Who stood with his hands at his sides looking at the row of shoes. She came and stood beside him and didn't touch him; she only stood there, close, the way you'd stand beside somebody at a grave; and after a long time he let out a breath, and his shoulders came down, a centimeter, and she put her hand, very lightly, on his arm, and he let it stay." },
    { n: "She held them. All three. The way a mother holds people. And they let her, because there was nobody else in the world left to do it." },
    // CG: eqx-there-there — dawn on a long bridge over a gray bay, a small old woman in a dark kimono and white gloves holding a grieving middle-aged man against her shoulder, two other men standing close by, three pairs of women's shoes in a neat row at the rail.
    { n: "Aigis, beside Solar, had gone completely still." },
    { n: "Solar looked at her. Aigis's eyes were on Mrs. Oka. On her gloved hand on Jaesang's neck. On her face, wet, crumpled, kind. And Aigis's head was tipped, very slightly, to one side, the way it tipped on the roof at midnight, counting." },
    { n: "Solar touched her arm. Aigis didn't look round. When she spoke it was so low that only Solar heard it, and her voice did something Solar had never heard it do: it hesitated." },
    { s: 'aigis', f: 'sad', t: "...I'm not reading anything. Not her. Not the fathers. Not you. I've been in the red for twelve hours and everything is quiet. Everything is like the bridge." },
    { s: 'aigis', f: 'neutral', t: "I would like to take it again. When I can hear. I would like that very much." },
    { n: "She didn't look away from the landlady. Then, after a long time, she did, out at the bay, where a skin of fine white dust still lay on the water in the dawn, very faintly, and hadn't sunk." },
    { n: "Mrs. Oka poured the tea. She poured a cup for each of them from the big thermos, and put it in their hands, and closed their fingers round it with hers. Jaesang. Taejoon. Mr. Kim. Jaehyun, who took it without looking at it. Mitsuru, who took it, and held it, and didn't drink. Haechan, who took it and put it down on the walk at his feet very carefully, as if it might go off." },
    { n: "She came to Solar last. She put the cup in Solar's hands and closed Solar's fingers round it with her own, the gloves warm, the four small hard points pressing, and held them there, and looked up into her face. Her eyes were wet and dark and very patient." },
    { s: 'mrsoka', f: 'sad', t: "Oh, child. Oh, my poor child. All three of them. All at once. Whatever will you do." },
    { s: 'mrsoka', f: 'neutral', t: "You'll stay with me now, won't you. All of you. You'll let me look after you. Somebody has to." },
    { n: "Solar stood on Moonlight Bridge in the gray dawn with a cup of tea in her hands and the landlady's hands round hers and her mothers' shoes in a row at her feet, facing home." },
    { n: "She didn't answer. She didn't drink. She stood there with the cup going cold between their four hands and looked at Mrs. Oka's face, so kind, so close, so sorry, and somewhere very deep, somewhere under her ribs where the small warm things went when she gave them away, something she didn't have a name for yet turned over, once, like a card." },
    { n: "Down the walk, on the rail, a gull came down and stood where the face had been, and looked at the water, and didn't take anything." }
  ] }
);
}
